('mcq', 5, 2, 'الوحل مخلوط معلق تترسب جسيماته عند تركه دون تحريك، والمعلق أحد نوعي المخاليط غير المتجانسة؛ فتصنيفه غير متجانس صحيح.', '["الحليب مخلوط غروي (مستحلب)، والغروي من المخاليط غير المتجانسة.","الهواء محلول غازي، والمحاليل مخاليط متجانسة.","","الفولاذ محلول صلب (الكربون في الحديد)، فهو مخلوط متجانس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.298Z"}'::jsonb),
('mcq', 6, 0, 'النيتينول محلول صلب يتكون من التيتانيوم المذاب في النيكل، والمحاليل مخاليط متجانسة.', '["","لا تترسب مكونات النيتينول ولا يمكن تمييزها؛ فهو ليس معلقًا.","النيتينول محلول (مذاب في مذيب)، وليس جسيمات منتشرة في وسط انتشار.","الحالة الصلبة لا تعني النقاء؛ فالنيتينول مزيج من فلزين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.298Z"}'::jsonb),
('mcq', 7, 1, 'المحاليل هي المخاليط المتجانسة، أما المخاليط فتشمل أيضًا المخاليط غير المتجانسة (المعلقة والغروية)؛ لذا كل محلول مخلوط، وليس كل مخلوط محلولًا.', '["عكست العلاقة؛ فالمعلق والغروي مخاليط وليست محاليل، وكل محلول مخلوط.","","المحلول يحتوي على مذاب ومذيب، فهو مخلوط لا مادة نقية.","المحاليل مخاليط متجانسة؛ وغير المتجانسة هي المعلقة والغروية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.298Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) المخاليط غير المتجانسة: مخاليط لا تمتزج مكوناتها تمامًا معًا، أي يمكن تمييز كل منها، وهي نوعان: المعلق والغروي؛ مثل الوحل (معلق) أو الحليب (غروي). 2) المخاليط المتجانسة (المحاليل): مخاليط تحتوي على مذاب ومذيب لا يمكن التمييز بينهما عند النظر إلى المحلول؛ مثل الهواء أو ماء البحر أو الفولاذ. ويقبل أي مثال صحيح.', '["النوع الأول: المخاليط غير المتجانسة","تعريفها: لا تمتزج مكوناتها تمامًا ويمكن تمييزها","مثال: الوحل أو الحليب","النوع الثاني: المخاليط المتجانسة (المحاليل)","تعريفها: لا يمكن التمييز بين المذاب والمذيب","مثال: الهواء أو ماء البحر"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر النوعين","marks":2},{"element":"تعريف كل نوع","marks":2},{"element":"مثال صحيح لكل نوع","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"ذكر النوعين وتعريفهما ومثال صحيح لكل منهما"},{"level":"3–5 درجات","description":"ذكر النوعين مع نقص في التعريف أو الأمثلة"},{"level":"1–2 درجة","description":"ذكر النوعين فقط دون تعريف أو مثال"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر المعلق والغروي بوصفهما نوعي المخاليط كلها","التمثيل للمخلوط المتجانس بالحليب","تعريف المتجانس بأنه المخلوط الذي لا يمكن فصل مكوناته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.298Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الوحل: غير متجانس (معلق). الهواء: متجانس (محلول غازي). الجيلاتين: غير متجانس (غروي، صلب في سائل). ماء البحر بعد ترشيحه: متجانس (محلول سائل، كلوريد الصوديوم في الماء). الدخان في الهواء: غير متجانس (غروي، هباء جوي صلب). مانع التجمد: متجانس (محلول سائل، الإيثيلين جلايكول في الماء).', '["الوحل غير متجانس معلق","الهواء متجانس","الجيلاتين غير متجانس غروي","ماء البحر المرشح متجانس","الدخان في الهواء غير متجانس غروي","مانع التجمد متجانس"]'::jsonb, '[]'::jsonb, '[{"element":"الوحل","marks":1},{"element":"الهواء","marks":1},{"element":"الجيلاتين","marks":1},{"element":"ماء البحر بعد ترشيحه","marks":1},{"element":"الدخان في الهواء","marks":1},{"element":"مانع التجمد","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف المخاليط الستة تصنيفًا صحيحًا مع تحديد نوع غير المتجانس"},{"level":"3–5 درجات","description":"تصنيف صحيح لثلاثة إلى خمسة مخاليط"},{"level":"1–2 درجة","description":"تصنيف صحيح لمخلوط أو مخلوطين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الجيلاتين محلولًا لأنه يبدو متجانس المظهر","عدّ الدخان في الهواء محلولًا غازيًّا كالهواء","تصنيف ماء البحر المرشح غير متجانس لأن ماء البحر الأصلي تترسب منه مواد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.299Z"}'::jsonb),
('essay', 3, null::int, null, null, 'ماء البحر الذي جُمع في الكأس يحتوي على مواد تترسب عند تركه دون تحريك، ويمكن تمييزها؛ لذا فهو يحتوي على مخلوط غير متجانس (معلق). أما الماء الصافي المالح فوق الراسب فهو محلول (مخلوط متجانس) من كلوريد الصوديوم وغيره مذابًا في الماء؛ فالملح لا يترسب ولا يمكن تمييزه من الماء بالنظر، لكن الملوحة تدل على وجوده. إذن تكشف المشاهدة عن نوعي المخاليط: غير المتجانس (الجزء المترسب) والمتجانس (الماء المالح).', '["المواد المترسبة تدل على مخلوط غير متجانس معلق","التبرير: تترسب ويمكن تمييزها","الماء المالح الصافي محلول متجانس","التبرير: الملح ذائب لا يترسب ولا يُميَّز، والملوحة دليل وجوده"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الجزء غير المتجانس ونوعه","marks":1},{"element":"تبرير عدّه غير متجانس","marks":1},{"element":"تحديد الجزء المتجانس (المحلول)","marks":1},{"element":"تبرير عدّه متجانسًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد نوعي المخاليط في المشاهدة مع تبرير كل منهما"},{"level":"2–3 درجات","description":"تحديد النوعين مع تبرير ناقص"},{"level":"1 درجة","description":"تحديد نوع واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء الصافي ماء نقي","عدّ ماء البحر كله محلولًا متجانسًا رغم الترسب","الخلط بين الترسب والذوبان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.299Z"}'::jsonb)
