('mcq', 4, 'يُسمّى المخلوط الذي لا تمتزج مكوناته تمامًا معًا، فيمكن تمييز كل منها:', null, '["مخلوطًا غير متجانس","محلولًا متجانسًا","مخلوطًا متجانسًا","مركبًا كيميائيًّا"]'::jsonb, 'تذكر', 'استدعاء مصطلح من تعريفه', 'سهل', 'الكتاب ص 14 — المخاليط غير المتجانسة'),
