('mcq', 3, 2, 'هناك نوعان من المخاليط غير المتجانسة هما المعلق والغروي.', '["المحاليل بأنواعها الثلاثة مخاليط متجانسة.","قد تكون مكوناتها صلبة أو سائلة أو غازية، كالوحل (صلب في سائل) والضباب (سائل في غاز).","","جسيمات المعلق كبيرة، وجسيمات الغروي بين 1 nm و1000 nm؛ فليست أصغر من 1 nm."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.301Z"}'::jsonb),
('mcq', 4, 0, 'هذا هو تعريف المخلوط غير المتجانس.', '["","المحلول متجانس، ولا يمكن التمييز بين مكوناته (المذاب والمذيب).","المخلوط المتجانس تمتزج مكوناته تمامًا ولا يمكن تمييزها.","المركب مادة نقية تتحد فيها العناصر كيميائيًّا، وليس مخلوطًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.301Z"}'::jsonb),
('mcq', 5, 3, 'في الوحل لا يمتزج الطين بالماء تمامًا؛ فيمكن تمييزه، ويترسب إذا تُرك دون تحريك، وهذا ينطبق على تعريف المخلوط غير المتجانس.', '["لو ذاب الطين تمامًا لتكوّن محلول متجانس لا يمكن تمييز مكوناته.","الوحل مزيج من مادتين (طين وماء)، فهو مخلوط لا مادة نقية.","جسيمات الوحل المعلقة تُفصل بالترشيح، فهذا السبب غير صحيح.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.301Z"}'::jsonb),
('mcq', 6, 2, 'المخلوط الذي يمكن تمييز مكوناته (ص) غير متجانس، والمخلوط الذي لا يمكن التمييز بين مذابه ومذيبه (س) محلول، أي مخلوط متجانس.', '["عكس التصنيف؛ فإمكانية تمييز المكونات صفة غير المتجانس لا المتجانس.","(س) لا تُميَّز مكوناته، فهو محلول متجانس.","","(ص) تُميَّز مكوناته، فهو غير متجانس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.301Z"}'::jsonb),
('mcq', 7, 1, 'يبدو الغروي المخفف متجانسًا لقلة عدد جسيماته، لكنها جسيمات منتشرة لم تمتزج تمامًا بوسط الانتشار، وتكشف عن وجودها بتشتيت الضوء (تأثير تندال)؛ لذا فهو غير متجانس.', '["جسيمات المخلوط الغروي لا تترسب؛ الترسب صفة المعلق.","","المخلوط الغروي مكوّن من جسيمات منتشرة ووسط انتشار، فليس مادة نقية.","لو ذابت تمامًا لكان محلولًا لا يشتت الضوء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.301Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المخلوط غير المتجانس: مخلوط لا تمتزج مكوناته تمامًا معًا؛ أي يمكن تمييز كل منها. وهو نوعان: المخلوط المعلق، مثل الوحل، والمخلوط الغروي، مثل الحليب.', '["لا تمتزج مكوناته تمامًا","يمكن تمييز كل مكون","النوع الأول: المعلق (مثل الوحل)","النوع الثاني: الغروي (مثل الحليب)"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"النوعان","marks":1},{"element":"مثال لكل نوع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل، وذكر النوعين، ومثال صحيح لكل منهما"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في الأنواع أو الأمثلة"},{"level":"1 درجة","description":"ذكر النوعين أو مثال دون تعريف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفه بأنه المخلوط الذي تترسب مكوناته","عدّ المحلول أحد نوعيه","التمثيل بالهواء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.301Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المتجانس: تمتزج مكوناته تمامًا؛ غير المتجانس: لا تمتزج مكوناته تمامًا. (ب) المتجانس: لا يمكن التمييز بين المذاب والمذيب؛ غير المتجانس: يمكن تمييز كل مكون. (ج) المتجانس: المحاليل (غازية أو سائلة أو صلبة)؛ غير المتجانس: المعلق والغروي. (د) المتجانس: الهواء أو ماء البحر المرشح أو الفولاذ؛ غير المتجانس: الوحل أو الحليب أو الضباب.', '["امتزاج المكونات: تام / غير تام","التمييز: لا يمكن / يمكن","الأنواع: محاليل / معلق وغروي","الأمثلة المناسبة"]'::jsonb, '[]'::jsonb, '[{"element":"امتزاج المكونات","marks":2},{"element":"إمكانية التمييز","marks":2},{"element":"الأنواع","marks":1},{"element":"الأمثلة","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة صحيحة في البنود الأربعة"},{"level":"3–5 درجات","description":"مقارنة صحيحة في بندين أو ثلاثة"},{"level":"1–2 درجة","description":"مقارنة صحيحة في بند واحد أو وصف أحد الطرفين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف طرف واحد دون مقابله","عدّ الغروي من المخاليط المتجانسة لأنه قد يبدو صافيًا","التمثيل للمتجانس بمخلوط معلق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.302Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التعريف غير صحيح؛ لأنه ينطبق على المخلوط المعلق وحده، في حين أن المخلوط الغروي غير متجانس أيضًا لكن جسيماته لا تترسب؛ فالحليب مثلًا مخلوط غروي غير متجانس لا تترسب جسيماته ولا يُفصل بالترويق أو الترشيح. التعريف الصحيح: المخلوط غير المتجانس مخلوط لا تمتزج مكوناته تمامًا معًا؛ أي يمكن تمييز كل منها.', '["الحكم: التعريف غير صحيح (ناقص)","الخطأ: يقتصر على المعلق","مثال مضاد: الحليب أو الدم أو الضباب (غروي لا يترسب)","التعريف الصحيح"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على التعريف","marks":1},{"element":"تحديد سبب الخطأ","marks":1},{"element":"مثال مضاد صحيح","marks":1},{"element":"كتابة التعريف الصحيح","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح مع تحديد الخطأ ومثال مضاد وتعريف صحيح كامل"},{"level":"3–4 درجات","description":"حكم وتعريف صحيحان دون مثال أو تحديد دقيق للخطأ"},{"level":"1–2 درجة","description":"الحكم بخطأ التعريف دون تعليل أو تصحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول التعريف لأنه صحيح للمعلق","التمثيل بمحلول بدل مخلوط غروي","تصحيح التعريف بتعريف المحلول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.302Z"}'::jsonb)
