('essay', 1, null::int, null, null, 'مثال المعلق: الوحل؛ لأنه يحتوي على جسيمات طين كبيرة تترسب إذا تُرك دون تحريك، وتُفصل بالترشيح. مثالا الغروي: الحليب؛ لأنه مستحلب تنتشر فيه جسيمات سائلة في وسط سائل ولا تترسب، والضباب؛ لأنه هباء جوي سائل تنتشر فيه قطيرات سائلة في الهواء ولا تترسب ويشتت الضوء. (تُقبل أمثلة أخرى مثل الدم والجيلاتين والزبد والدخان).', '["مثال معلق صحيح (الوحل)","سبب تصنيفه: جسيماته تترسب/تُفصل بالترشيح","مثالان غرويان صحيحان","سبب تصنيفهما: جسيمات متوسطة الحجم منتشرة لا تترسب"]'::jsonb, '[]'::jsonb, '[{"element":"مثال المعلق","marks":1},{"element":"سبب تصنيف المعلق","marks":1},{"element":"المثالان الغرويان","marks":2},{"element":"سبب تصنيف الغرويين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ثلاثة أمثلة صحيحة مع أسباب صحيحة"},{"level":"3–4 درجات","description":"أمثلة صحيحة مع نقص في الأسباب"},{"level":"1–2 درجة","description":"مثال أو مثالان صحيحان دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التمثيل للغروي بمحلول كماء البحر المرشح","التمثيل للمعلق بالحليب","تعليل التصنيف بالمظهر فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.304Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الوحل: مخلوط معلق. الزبد: مخلوط غروي (مستحلب صلب). الهواء: محلول (غازي). الدم: مخلوط غروي (صلب في سائل). الغيوم: مخلوط غروي (هباء جوي سائل). الماء الغازي: محلول (سائل). حلوى الخطمي: مخلوط غروي (رغوة صلبة).', '["الوحل معلق","الزبد غروي","الهواء محلول","الدم غروي","الغيوم غروي","الماء الغازي محلول","حلوى الخطمي غروي"]'::jsonb, '[]'::jsonb, '[{"element":"الوحل","marks":1},{"element":"الزبد","marks":1},{"element":"الهواء","marks":1},{"element":"الدم","marks":1},{"element":"الغيوم","marks":1},{"element":"الماء الغازي","marks":1},{"element":"حلوى الخطمي","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"تصنيف الأمثلة السبعة تصنيفًا صحيحًا"},{"level":"4–6 درجات","description":"تصنيف صحيح لأربعة إلى ستة أمثلة"},{"level":"1–3 درجات","description":"تصنيف صحيح لمثال إلى ثلاثة أمثلة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الدم محلولًا","عدّ الماء الغازي مخلوطًا غرويًّا لوجود فقاعات","عدّ الغيوم معلقًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.304Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الدخان: هباء جوي صلب؛ جسيماته المنتشرة صلبة ووسط انتشاره غاز (الهواء)، ومثال آخر عليه: الغبار في الهواء. الغيوم: هباء جوي سائل؛ جسيماته المنتشرة سائلة (قطيرات ماء) ووسط انتشاره غاز، ومثال آخر عليه: الضباب أو رذاذ مزيل العرق. الفرق بينهما في حالة الجسيمات المنتشرة: صلبة في الدخان، وسائلة في الغيوم، مع أن وسط الانتشار في كليهما غاز.', '["الدخان: هباء جوي صلب","الغيوم: هباء جوي سائل","الفرق: الجسيمات المنتشرة صلبة/سائلة، والوسط غاز في الحالتين","مثال آخر للهباء الصلب: الغبار في الهواء","مثال آخر للهباء السائل: الضباب أو رذاذ مزيل العرق"]'::jsonb, '[]'::jsonb, '[{"element":"نوع الدخان","marks":1},{"element":"نوع الغيوم","marks":1},{"element":"توضيح الفرق","marks":1},{"element":"مثال آخر لكل نوع","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحديد النوعين وتوضيح الفرق ومثالين صحيحين"},{"level":"3–4 درجات","description":"تحديد النوعين مع نقص في الفرق أو الأمثلة"},{"level":"1–2 درجة","description":"تحديد نوع واحد أو مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الغيوم هباءً جويًّا صلبًا","الخلط بين الجسيمات المنتشرة ووسط الانتشار","التمثيل للهباء السائل بالدخان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.304Z"}'::jsonb)
