('mcq', 1, 2, 'المحلول قد يكون غازيًّا أو سائلًا أو صلبًا اعتمادًا على الحالة الفيزيائية للمذيب.', '["المذاب قد يكون غازًا أو سائلًا أو صلبًا في محلول واحد النوع؛ فالماء الغازي محلول سائل مذابه غاز.","كمية المذاب تحدد تركيز المحلول لا حالته الفيزيائية.","","درجة الحرارة ليست أساس تصنيف المحاليل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.305Z"}'::jsonb),
('mcq', 2, 3, 'المذيب هو الوسط الذي يذيب المذاب، وهو هنا النيكل (صلب)؛ لذا فالنيتينول محلول صلب.', '["التيتانيوم هو المذاب لأنه مذاب في النيكل، لا المذيب.","النيكل صلب، وحالة المحلول تتبع حالة المذيب؛ فالمحلول صلب.","التيتانيوم هو المذاب، ولا يوجد مكون غازي في النيتينول.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.306Z"}'::jsonb),
('mcq', 3, 0, 'المذيب في لغم الأسنان هو الفضة، وهي صلبة؛ وبما أن حالة المحلول تعتمد على حالة المذيب فهو محلول صلب.', '["","صُنّف المحلول وفق حالة المذاب، والصحيح أن التصنيف يعتمد على حالة المذيب.","لا يوجد في لغم الأسنان مذيب غازي؛ فالمذيب الفضة الصلبة.","لغم الأسنان محلول صلب لا مخلوطًا غرويًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.306Z"}'::jsonb),
('mcq', 4, 1, 'مذيب الرطوبة هو الهواء الجوي (غاز)، فهي محلول غازي رغم أن مذابها سائل؛ لأن حالة المحلول تتبع حالة المذيب.', '["صُنّفت الرطوبة وفق مذابها (الماء)، والصحيح التصنيف وفق المذيب (الهواء الجوي).","","مذيب ماء البحر الماء السائل؛ فهو محلول سائل، وكلوريد الصوديوم الصلب هو المذاب.","مذيب الفولاذ الحديد الصلب؛ فهو محلول صلب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.306Z"}'::jsonb),
('mcq', 5, 2, 'في المحاليل السائلة قد يكون المذاب غازًا (كثاني أكسيد الكربون في الماء الغازي) أو سائلًا (كالإيثيلين جلايكول في مانع التجمد) أو صلبًا (ككلوريد الصوديوم في ماء البحر).', '["الماء الغازي مثلًا مذيبه سائل ومذابه غاز؛ فلا يشترط تساوي الحالتين.","الفولاذ ولغم الأسنان والنيتينول محاليل صلبة.","","معظم المحاليل تكون في الحالة السائلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.306Z"}'::jsonb),
('mcq', 6, 3, 'الهواء محلول غازي مذيبه النيتروجين (غاز) ومن مذاباته الأكسجين (غاز).', '["مذيب الرطوبة غاز لكن مذابها الماء السائل.","مذاب الماء الغازي غاز (CO₂) لكن مذيبه الماء السائل.","الفولاذ محلول صلب: مذيبه الحديد ومذابه الكربون، وكلاهما صلب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.306Z"}'::jsonb),
('mcq', 7, 0, '(س) مذيبه سائل فهو محلول سائل، ومثاله ماء البحر (كلوريد الصوديوم الصلب في الماء). (ص) مذيبه غاز فهو محلول غازي، ومثاله الرطوبة (الماء السائل في الهواء الجوي).', '["","صُنّف المحلولان وفق حالة المذاب لا المذيب، والمثالان لا يطابقان الوصف.","التصنيف صحيح لكن المثالين خطأ: مذاب الماء الغازي غاز، ومذاب الهواء غاز.","صُنّف المحلولان وفق المذاب، ولغم الأسنان مذيبه صلب ومذابه سائل عكس (س)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.307Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تُصنَّف المحاليل إلى غازية أو سائلة أو صلبة اعتمادًا على الحالة الفيزيائية للمذيب، في حين قد يكون المذاب غازًا أو سائلًا أو صلبًا. المحلول الغازي: الهواء؛ المذيب النيتروجين (غاز) والمذاب الأكسجين (غاز). المحلول السائل: ماء البحر؛ المذيب الماء (سائل) والمذاب كلوريد الصوديوم (صلب). المحلول الصلب: الفولاذ؛ المذيب الحديد (صلب) والمذاب الكربون (صلب). (ويقبل أي مثال صحيح).', '["الأساس: الحالة الفيزيائية للمذيب","مثال محلول غازي مع مذيبه ومذابه","مثال محلول سائل مع مذيبه ومذابه","مثال محلول صلب مع مذيبه ومذابه"]'::jsonb, '[]'::jsonb, '[{"element":"أساس التصنيف","marks":1},{"element":"مثال المحلول الغازي مع المذيب والمذاب","marks":1},{"element":"مثال المحلول السائل مع المذيب والمذاب","marks":1},{"element":"مثال المحلول الصلب مع المذيب والمذاب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ذكر الأساس الصحيح وثلاثة أمثلة صحيحة محددة المذيب والمذاب"},{"level":"2–3 درجات","description":"الأساس الصحيح مع مثال أو مثالين صحيحين"},{"level":"1 درجة","description":"ذكر الأساس فقط أو أمثلة دون تحديد المذيب والمذاب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل أساس التصنيف حالة المذاب","عدّ الأكسجين مذيبًا في الهواء","التمثيل للمحلول الصلب بمخلوط غروي كالجبن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.307Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المذيب الكحول وهو سائل؛ فالمحلول سائل. (ب) المذيب النحاس وهو صلب؛ فالمحلول صلب. (ج) المذيب الهيليوم وهو غاز؛ فالمحلول غازي. والتبرير في الحالات الثلاث أن حالة المحلول تعتمد على الحالة الفيزيائية للمذيب لا المذاب.', '["(أ) المذيب الكحول، محلول سائل","(ب) المذيب النحاس، محلول صلب","(ج) المذيب الهيليوم، محلول غازي","التبرير: التصنيف وفق حالة المذيب"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) المذيب والتصنيف","marks":2},{"element":"(ب) المذيب والتصنيف","marks":2},{"element":"(ج) المذيب والتصنيف","marks":2},{"element":"التبرير","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"تحديد المذيب والتصنيف الصحيح في الحالات الثلاث مع التبرير"},{"level":"4–6 درجات","description":"حالتان صحيحتان أو ثلاث حالات دون تبرير"},{"level":"1–3 درجات","description":"حالة واحدة صحيحة أو تحديد مذيبات دون تصنيف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف (أ) صلبًا لأن اليود صلب","عدّ الخارصين مذيبًا في النحاس الأصفر","تصنيف (ج) وفق الأكسجين بدل الهيليوم مع صحة النتيجة مصادفة دون تبرير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.307Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة في الحالتين؛ لأن الطالب صنّف المحلولين وفق حالة المذاب، والصحيح أن المحلول يُصنَّف وفق الحالة الفيزيائية للمذيب. الماء الغازي: المذيب الماء (سائل) والمذاب ثاني أكسيد الكربون (غاز)؛ فهو محلول سائل. الرطوبة: المذيب الهواء الجوي (غاز) والمذاب بخار الماء (غاز)؛ فهي محلول غازي.', '["الحكم: العبارة خاطئة","سبب الخطأ: التصنيف وفق المذاب","الماء الغازي محلول سائل لأن مذيبه الماء","الرطوبة محلول غازي لأن مذيبها الهواء الجوي"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم وسبب الخطأ","marks":2},{"element":"تصحيح تصنيف الماء الغازي مع التعليل","marks":2},{"element":"تصحيح تصنيف الرطوبة مع التعليل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"حكم صحيح مع تحديد سبب الخطأ وتصحيح التصنيفين معللًا"},{"level":"3–5 درجات","description":"تصحيح أحد التصنيفين معللًا أو التصنيفين دون تعليل"},{"level":"1–2 درجة","description":"الحكم بالخطأ دون تصحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول تصنيف أحد المحلولين","تحديد المذيب في الرطوبة بأنه الماء","تصحيح التصنيف دون بيان القاعدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.307Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
