('mcq', 1, 'ما مدى أقطار الجسيمات المنتشرة في المخلوط الغروي؟', null, '["أقل من 1 nm","بين 1 nm و1000 nm","أكبر من 1000 nm بكثير","بين 0.1 nm و1 nm"]'::jsonb, 'تذكر', 'تذكر حقيقة رقمية', 'سهل', 'الكتاب ص 15 — المخاليط الغروية'),
('mcq', 2, 'أيّ المخاليط الآتية تترسب جسيماته إذا تُرك فترة دون تحريك؟', null, '["المخلوط المعلق","المخلوط الغروي","المحلول","المستحلب الغروي"]'::jsonb, 'فهم', 'مقارنة خاصية', 'سهل', 'الكتاب ص 14–15 — المخلوط المعلق والغروي'),
('mcq', 3, 'يبيّن الجدول نتائج اختبار ثلاثة مخاليط. ما التصنيف الصحيح لها؟', '{"headers":["المخلوط","تترسب جسيماته عند تركه؟","يُفصل بالترشيح؟","يشتت حزمة الضوء؟"],"rows":[["(أ)","نعم","نعم","نعم"],["(ب)","لا","لا","نعم"],["(ج)","لا","لا","لا"]]}'::jsonb, '["(أ) غروي، (ب) معلق، (ج) محلول","(أ) معلق، (ب) محلول، (ج) غروي","(أ) محلول، (ب) غروي، (ج) معلق","(أ) معلق، (ب) غروي، (ج) محلول"]'::jsonb, 'فهم', 'تفسير بيانات جدول', 'متوسط', 'الكتاب ص 14–16 — المخلوط المعلق والغروي، تأثير تندال'),
('mcq', 4, 'ما الخاصية التي يشترك فيها المخلوط المعلق والمخلوط الغروي، ولا يشترك فيها المحلول؟', null, '["ترسب الجسيمات عند ترك المخلوط","فصل المكونات بالترشيح","إظهار تأثير تندال","تعذر التمييز بين المكونات بالنظر"]'::jsonb, 'فهم', 'تحديد خاصية مشتركة', 'سهل', 'الكتاب ص 16 — تأثير تندال'),
('mcq', 5, 'بمَ يختلف المخلوط الغروي عن المخلوط المعلق؟', null, '["جسيمات الغروي أكبر، وتترسب أسرع","جسيمات الغروي أصغر، ولا تترسب، ولا تُفصل بالترشيح","الغروي لا يُظهر تأثير تندال، بخلاف المعلق","الغروي متجانس، والمعلق غير متجانس"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 14–16 — المخلوط المعلق والغروي، تأثير تندال'),
('mcq', 6, 'مُرِّر مخلوط خلال ورقة ترشيح فلم ينفصل منه شيء، ثم مُرِّرت فيه حزمة ضوء فظهر مسارها بوضوح. ما نوع المخلوط؟', null, '["مخلوط غروي","محلول","مخلوط معلق","مادة نقية"]'::jsonb, 'تطبيق', 'استنتاج من مشاهدات', 'صعب', 'الكتاب ص 14–16 — المخلوط المعلق والغروي، تأثير تندال'),
('mcq', 7, 'أيّ المخاليط الآتية لا يمكن التمييز بين مكوناته عند النظر إليه، ولا يُظهر تأثير تندال؟', null, '["الحليب المخفف بالماء","الماء الموحل","محلول السكر في الماء","الهواء المشبع بالدخان"]'::jsonb, 'فهم', 'تطبيق معيارين للمقارنة', 'متوسط', 'الكتاب ص 16 — تأثير تندال، المخاليط المتجانسة'),
('essay', 1, 'كوّن جدولًا تقارن فيه بين المحلول والمخلوط الغروي والمخلوط المعلق من حيث: (1) حجم الجسيمات، (2) ترسب الجسيمات عند ترك المخلوط، (3) فصل المكونات بالترويق أو الترشيح، (4) تأثير تندال.', null, null, 'فهم', 'مقارنة بجدول', 'متوسط', 'الكتاب ص 14–16، 18 — التقويم 1-1 س8'),
('essay', 2, 'لديك ثلاث كؤوس غير معلّمة تحتوي على: ماء موحل، وحليب مخفف، ومحلول ملح. صف خطوات للتمييز بينها باستعمال: ترك الكؤوس دون تحريك، وورقة الترشيح، ومصباح يدوي، مبينًا النتيجة المتوقعة لكل كأس.', null, null, 'تطبيق', 'تصميم خطوات تمييز', 'صعب', 'الكتاب ص 14–16 — المخلوط المعلق والغروي، تأثير تندال'),
('essay', 3, 'ميّز بين المخلوط الغروي والمخلوط المعلق، ثم فسّر لماذا لا يكفي تأثير تندال وحده للتمييز بينهما، واقترح خاصية تصلح لذلك.', null, null, 'تحليل', 'تمييز وتفسير', 'صعب', 'الكتاب ص 14–16، 18 — التقويم 1-1 س2')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
