from (values
('mcq', 1, 1, 'أقطار الجسيمات في المخلوط الغروي تتراوح بين 1 nm و1000 nm.', '["هذا أصغر من جسيمات الغروي، ويوافق جسيمات المحلول الذائبة.","","الجسيمات الأكبر كثيرًا هي جسيمات المعلق التي تترسب.","هذا المدى أصغر من الحد الأدنى لجسيمات الغروي (1 nm)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.308Z"}'::jsonb),
('mcq', 2, 0, 'المخلوط المعلق يحتوي على جسيمات كبيرة يمكن أن تترسب بتركه فترة دون تحريك (الترويق).', '["","جسيمات المخلوط الغروي متوسطة الحجم ولا تترسب.","جسيمات المذاب في المحلول ذائبة ولا تترسب.","المستحلب نوع من المخاليط الغروية، وجسيماته لا تترسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.308Z"}'::jsonb),
('mcq', 3, 3, '(أ) تترسب جسيماته وتُفصل بالترشيح فهو معلق. (ب) لا يترسب ولا يُفصل بالترشيح لكنه يشتت الضوء فهو غروي. (ج) لا يترسب ولا يُفصل ولا يشتت الضوء فهو محلول.', '["الغروي لا تترسب جسيماته ولا تُفصل بالترشيح، فلا يكون (أ).","المحلول لا يشتت الضوء، فلا يكون (ب)؛ والغروي يشتته فلا يكون (ج).","المحلول لا تترسب جسيماته، والمعلق تترسب جسيماته وتُفصل بالترشيح.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-17T11:36:22.308Z"}'::jsonb),
('mcq', 4, 2, 'المخاليط الغروية والمعلقة تُظهر تأثير تندال، أما المحاليل فلا يمكن أن تُظهره.', '["الترسب خاصية المعلق وحده؛ فجسيمات الغروي لا تترسب.","الترشيح يفصل جسيمات المعلق، ولا يفصل مكونات الغروي.","","تعذر التمييز بين المذاب والمذيب صفة المحلول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.308Z"}'::jsonb),
('mcq', 5, 1, 'جسيمات المعلق أكبر كثيرًا فتترسب وتُفصل بالترشيح، أما جسيمات الغروي فمتوسطة الحجم (1–1000 nm) ولا تترسب ولا تُفصل بالترويق أو الترشيح.', '["عكس الحقيقة؛ فجسيمات المعلق هي الأكبر، وهي التي تترسب.","","كلاهما يُظهر تأثير تندال، فلا يصلح هذا للتمييز بينهما.","كلاهما من المخاليط غير المتجانسة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.309Z"}'::jsonb),
('mcq', 6, 0, 'عدم انفصال شيء بالترشيح يستبعد المعلق، وظهور مسار الضوء (تأثير تندال) يستبعد المحلول؛ فهو مخلوط غروي.', '["","المحلول لا يُظهر تأثير تندال، فلا يظهر فيه مسار الحزمة.","جسيمات المعلق تُفصل بالترشيح، والمخلوط لم ينفصل منه شيء.","المادة النقية لا تحتوي على جسيمات منتشرة تشتت الضوء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.309Z"}'::jsonb),
('mcq', 7, 2, 'محلول السكر مخلوط متجانس لا يمكن التمييز فيه بين المذاب والمذيب، والمحاليل لا تُظهر تأثير تندال.', '["الحليب المخفف مخلوط غروي يُظهر تأثير تندال رغم أنه قد يبدو صافيًا.","الماء الموحل معلق يمكن تمييز جسيماته ويُظهر تأثير تندال.","","الدخان مخلوط غروي في الهواء، ويُلاحظ فيه تأثير تندال عند مرور أشعة الشمس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.309Z"}'::jsonb),
('essay', 1, null::int, null, null, 'حجم الجسيمات: المحلول أصغر جسيمات (مذاب ذائب)؛ الغروي متوسطة بأقطار بين 1 nm و1000 nm؛ المعلق كبيرة جدًّا. الترسب: المحلول لا يترسب؛ الغروي لا يترسب؛ المعلق يترسب إذا تُرك دون تحريك. الفصل بالترويق أو الترشيح: المحلول لا؛ الغروي لا؛ المعلق نعم. تأثير تندال: المحلول لا يُظهره؛ الغروي يُظهره؛ المعلق يُظهره.', '["حجم الجسيمات للأنواع الثلاثة (الغروي 1–1000 nm)","الترسب: المعلق فقط","الفصل بالترويق/الترشيح: المعلق فقط","تأثير تندال: الغروي والمعلق دون المحلول"]'::jsonb, '[]'::jsonb, '[{"element":"حجم الجسيمات","marks":2},{"element":"الترسب","marks":2},{"element":"الفصل بالترويق أو الترشيح","marks":2},{"element":"تأثير تندال","marks":2}]'::jsonb, '[{"level":"8 درجات","description":"الجدول صحيح كامل في المعايير الأربعة للأنواع الثلاثة"},{"level":"4–7 درجات","description":"معياران أو ثلاثة صحيحة، أو أخطاء متفرقة في الخلايا"},{"level":"1–3 درجات","description":"معيار واحد صحيح أو وصف نوع واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المعلق لا يُظهر تأثير تندال","القول إن جسيمات الغروي تترسب ببطء","جعل مدى 1–1000 nm لجسيمات المعلق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.309Z"}'::jsonb),
('essay', 2, null::int, null, null, '1) تُترك الكؤوس فترة دون تحريك: الكأس التي يترسب فيها راسب هي الماء الموحل (معلق). 2) لتأكيد ذلك يُرشح محتوى الكأس: ورقة الترشيح تحجز جسيمات الطين من الماء الموحل، ولا تحجز شيئًا من الكأسين الأخريين. 3) يُسلَّط ضوء المصباح خلال الكأسين الباقيتين: الكأس التي يظهر فيها مسار الضوء (تأثير تندال) هي الحليب المخفف (غروي)، والكأس التي لا يظهر فيها المسار هي محلول الملح.', '["ترك الكؤوس: يترسب الماء الموحل فقط","الترشيح: يحجز جسيمات المعلق فقط","المصباح: الحليب المخفف يُظهر تأثير تندال","محلول الملح لا يُظهر تأثير تندال"]'::jsonb, '[]'::jsonb, '[{"element":"خطوة الترك دون تحريك ونتيجتها","marks":2},{"element":"خطوة الترشيح ونتيجتها","marks":1},{"element":"خطوة المصباح ونتيجتها للغروي","marks":2},{"element":"تحديد المحلول","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"خطوات مرتبة ومنطقية مع نتيجة صحيحة لكل كأس"},{"level":"3–5 درجات","description":"تمييز صحيح لكأسين مع نقص في الخطوات أو النتائج"},{"level":"1–2 درجة","description":"تمييز صحيح لكأس واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتماد على تأثير تندال وحده للتمييز بين المعلق والغروي","توقع ترسب الحليب","توقع أن الترشيح يفصل الملح عن الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.309Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المخلوط المعلق: مخلوط غير متجانس جسيماته كبيرة تترسب إذا تُرك دون تحريك، وتُفصل بالترشيح. المخلوط الغروي: مخلوط غير متجانس جسيماته متوسطة الحجم (1–1000 nm) لا تترسب، ولا تُفصل بالترويق أو الترشيح. لا يكفي تأثير تندال لأن كلا المخلوطين يشتت الضوء ويُظهره، فهو يميزهما من المحلول لا من بعضهما. والخاصية المناسبة للتمييز: الترسب عند الترك دون تحريك أو الفصل بالترشيح؛ فالمعلق يترسب ويُفصل، والغروي لا.', '["وصف المعلق: جسيمات كبيرة تترسب وتُفصل بالترشيح","وصف الغروي: 1–1000 nm لا تترسب ولا تُفصل","كلاهما يُظهر تأثير تندال","اقتراح الترسب أو الترشيح للتمييز"]'::jsonb, '[]'::jsonb, '[{"element":"وصف المعلق","marks":1},{"element":"وصف الغروي","marks":1},{"element":"تفسير عدم كفاية تأثير تندال","marks":2},{"element":"اقتراح خاصية مناسبة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تمييز صحيح وتفسير سليم واقتراح خاصية مناسبة"},{"level":"3–4 درجات","description":"تمييز صحيح مع تفسير ناقص أو دون اقتراح"},{"level":"1–2 درجة","description":"وصف أحد المخلوطين أو ذكر أن كليهما يُظهر تأثير تندال فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المعلق لا يُظهر تأثير تندال","اقتراح تأثير تندال نفسه للتمييز","الخلط بين الغروي والمحلول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.310Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
