('mcq', 1, 'ما المقصود بالترويق؟', null, '["تمرير المخلوط خلال ورقة ترشيح لحجز الجسيمات العالقة فيه","تسخين المخلوط حتى يتبخر السائل وتبقى المادة الصلبة","تمرير حزمة ضوئية خلال المخلوط لتحديد كمية جسيماته","ترك المخلوط المعلق دون تحريك حتى تترسب جسيماته، ثم سكب السائل الرائق فوق الراسب"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'المحتوى المكمّل (ليس في الكتاب) — الترويق'),
('mcq', 2, 'على أيّ أساس يعتمد فصل مكونات المخلوط المعلق بالترويق؟', null, '["ذوبان الجسيمات في السائل","تشتيت الجسيمات للضوء","ترسب الجسيمات الكبيرة بفعل الجاذبية","اختلاف درجات غليان المكونات"]'::jsonb, 'فهم', 'تفسير أساس طريقة', 'سهل', 'المحتوى المكمّل (ليس في الكتاب) — الترويق'),
('mcq', 3, 'أيّ المخاليط الآتية يمكن فصل مكوناته بالترويق؟', null, '["محلول الملح في الماء","الماء الموحل","الحليب الطازج","مانع التجمد"]'::jsonb, 'فهم', 'تطبيق على أمثلة', 'متوسط', 'الكتاب ص 14 — المخلوط المعلق، الشكل 1-1'),
('mcq', 4, 'لماذا لا يصلح الترويق لفصل الملح عن الماء في محلول ملحي؟', null, '["لأن الملح ذائب في الماء فلا تترسب جسيماته","لأن الملح يتبخر مع الماء عند السكب","لأن الترويق يتطلب تسخين المحلول أولًا","لأن الملح يشتت الضوء فيمنع رؤية الراسب"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'المحتوى المكمّل (ليس في الكتاب) — الترويق'),
('mcq', 5, 'بعد ترويق ماء موحل بقي السائل المسكوب معكرًا قليلًا. ما الخطوة المناسبة التالية لإزالة ما بقي فيه من جسيمات معلقة؟', null, '["تحريك السائل بسرعة ثم سكبه مباشرة","إضافة مزيد من الماء الموحل إليه","تسخينه ليتحول إلى محلول متجانس","ترشيح السائل باستعمال ورقة الترشيح"]'::jsonb, 'تطبيق', 'اختيار إجراء مناسب', 'متوسط', 'المحتوى المكمّل (ليس في الكتاب) — الترويق'),
('mcq', 6, 'أيّ مقارنة بين الترويق والترشيح صحيحة؟', null, '["الترويق يعتمد على الترسب ثم السكب، والترشيح على ورقة تحجز الجسيمات","الترويق والترشيح اسمان لطريقة واحدة","الترويق يفصل المحلول، والترشيح يفصل الغروي","الترويق يعطي سائلًا نقيًّا تمامًا، بخلاف الترشيح"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'المحتوى المكمّل (ليس في الكتاب) — الترويق'),
('mcq', 7, 'تُرك وعاء فيه حليب ووعاء فيه ماء موحل فترة دون تحريك، فترسّب الطين في الوعاء الثاني ولم يترسب شيء في الأول. ما التفسير الصحيح؟', null, '["الحليب محلول متجانس لا جسيمات منتشرة فيه","جسيمات الحليب أكبر من الطين فتبقى طافية","جسيمات الطين كبيرة فتترسب، وجسيمات الحليب الغروية لا تترسب","الماء الموحل غروي، والحليب معلق"]'::jsonb, 'تحليل', 'تحليل مشاهدة', 'صعب', 'الكتاب ص 14–15 — المخلوط المعلق والغروي؛ المحتوى المكمّل (ليس في الكتاب) — الترويق'),
('essay', 1, 'وضّح المقصود بالترويق، ثم صف خطواته عند فصل الطين عن الماء في عينة من الماء الموحل.', null, null, 'فهم', 'توضيح ووصف خطوات', 'متوسط', 'المحتوى المكمّل (ليس في الكتاب) — الترويق'),
('essay', 2, 'لديك ماء موحل، ويُراد الحصول منه على ماء صافٍ قدر الإمكان. اقترح خطوات مرتبة تستعمل فيها الترويق ثم الترشيح، وفسّر سبب استعمال الطريقتين معًا بدل الاكتفاء بإحداهما.', null, null, 'تطبيق', 'اقتراح إجراء وتفسيره', 'صعب', 'المحتوى المكمّل (ليس في الكتاب) — الترويق'),
('essay', 3, 'حاول طالب فصل مكونات ثلاثة مخاليط بالترويق: الماء الموحل، ومحلول السكر في الماء، والحليب. توقّع نتيجة كل محاولة، وفسّر توقعك.', null, null, 'تحليل', 'توقع وتفسير', 'صعب', 'الكتاب ص 14–15 — المخلوط المعلق والغروي؛ المحتوى المكمّل (ليس في الكتاب) — الترويق')
