from (values
('mcq', 1, 3, 'الترويق طريقة لفصل مكونات المخلوط المعلق: يُترك المخلوط فترة دون تحريك حتى تترسب جسيماته في القاع، ثم يُسكب السائل الرائق الذي فوقها بهدوء.', '["هذا وصف الترشيح، وهو طريقة مختلفة تعتمد على ورقة الترشيح لا على الترسب.","هذا وصف التبخير، والترويق لا يتضمن تسخينًا.","هذا استعمال لتأثير تندال، لا وصف للترويق.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.311Z"}'::jsonb),
('mcq', 2, 2, 'ينجح الترويق لأن جسيمات المعلق كبيرة وثقيلة نسبيًّا، فتترسب في القاع بفعل الجاذبية إذا تُرك المخلوط دون تحريك.', '["الجسيمات الذائبة لا تترسب؛ لذا لا يفصل الترويق المذاب عن المذيب.","تشتيت الضوء هو تأثير تندال، ولا علاقة له بآلية الترويق.","","اختلاف درجات الغليان أساس التقطير، لا الترويق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.311Z"}'::jsonb),
('mcq', 3, 1, 'الماء الموحل مخلوط معلق، تترسب جسيمات الطين فيه إذا تُرك دون تحريك، فيمكن سكب الماء فوقها.', '["الملح ذائب في الماء، فلا تترسب جسيماته ولا يفصلها الترويق.","","الحليب مخلوط غروي لا تترسب جسيماته، فلا يُفصل بالترويق.","مانع التجمد محلول سائل لا تترسب مكوناته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.311Z"}'::jsonb),
('mcq', 4, 0, 'يعتمد الترويق على ترسب الجسيمات، والملح في المحلول ذائب؛ فلا يترسب مهما طالت مدة ترك المحلول دون تحريك.', '["","الملح لا يتبخر عند السكب؛ والسبب أنه ذائب فلا يترسب أصلًا.","الترويق لا يتطلب تسخينًا، بل ترك المخلوط دون تحريك.","المحاليل لا تُظهر تأثير تندال، ولا يتكون راسب أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.311Z"}'::jsonb),
('mcq', 5, 3, 'الفصل بالترويق غير تام غالبًا، فيُتبَع بالترشيح لإزالة ما بقي من جسيمات معلقة؛ إذ تحجزها ورقة الترشيح.', '["التحريك يعيد إثارة الجسيمات ونشرها في السائل بدل فصلها.","إضافة ماء موحل تزيد الجسيمات المعلقة ولا تزيلها.","التسخين لا يحول جسيمات الطين إلى مادة ذائبة، ولا يفصلها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.311Z"}'::jsonb),
('mcq', 6, 0, 'الترويق يعتمد على ترك المخلوط حتى تترسب جسيماته ثم سكب السائل، أما الترشيح فيعتمد على ورقة الترشيح التي تحجز الجسيمات المعلقة.', '["","هما طريقتان مختلفتان في الآلية، وإن استُعملتا لفصل المعلق.","الطريقتان لا تفصلان مكونات المحلول ولا الغروي، بل المعلق.","الفصل بالترويق غير تام غالبًا، ولذلك يُتبع بالترشيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.311Z"}'::jsonb),
('mcq', 7, 2, 'جسيمات المعلق (الطين) كبيرة وثقيلة فتترسب بالترويق، أما الحليب فمخلوط غروي جسيماته متوسطة الحجم لا تترسب؛ لذا لا يصلح الترويق لفصل مكوناته.', '["الحليب مخلوط غروي (مستحلب) فيه جسيمات منتشرة، وليس محلولًا.","جسيمات الغروي أصغر من جسيمات المعلق، لا أكبر.","","عكس التصنيف؛ فالماء الموحل معلق، والحليب غروي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.312Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الترويق: طريقة لفصل مكونات المخلوط المعلق تعتمد على ترك المخلوط فترة دون تحريك حتى تترسب جسيماته الكبيرة في القاع بفعل الجاذبية، ثم سكب السائل الرائق فوقها. الخطوات: 1) يوضع الماء الموحل في وعاء ويُترك فترة دون تحريك. 2) يترسب الطين في القاع ويصبح الماء فوقه أكثر صفاءً. 3) يُسكب الماء الرائق بهدوء في وعاء آخر دون إثارة الراسب.', '["تعريف الترويق","الترك دون تحريك","ترسب الطين بفعل الجاذبية","سكب السائل الرائق بهدوء دون إثارة الراسب"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"الخطوات مرتبة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وخطوات كاملة مرتبة"},{"level":"2–3 درجات","description":"تعريف صحيح مع خطوات ناقصة، أو خطوات صحيحة دون تعريف"},{"level":"1 درجة","description":"ذكر الترسب فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الترويق والترشيح","إغفال خطوة السكب","تحريك المخلوط قبل السكب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.312Z"}'::jsonb),
('essay', 2, null::int, null, null, '1) يُترك الماء الموحل فترة دون تحريك حتى يترسب معظم الطين. 2) يُسكب الماء الرائق بهدوء في وعاء آخر (ترويق). 3) يُمرر الماء المسكوب خلال ورقة ترشيح فتحجز ما بقي من جسيمات معلقة. التفسير: الترويق يتخلص من معظم الجسيمات الكبيرة لكنه غير تام، فيبقى السائل معكرًا قليلًا؛ والترشيح يزيل ما بقي منها. كما أن ترويق المخلوط أولًا يقلل كمية الطين التي تصل إلى ورقة الترشيح فلا تنسد بسرعة.', '["خطوة الترك دون تحريك","خطوة السكب","خطوة الترشيح","الترويق غير تام","الترشيح يزيل الجسيمات المتبقية","الترويق أولًا يخفف العبء على ورقة الترشيح"]'::jsonb, '[]'::jsonb, '[{"element":"الخطوات مرتبة","marks":3},{"element":"تفسير عدم كفاية الترويق","marks":1},{"element":"تفسير دور الترشيح وفائدة الترتيب","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"خطوات مرتبة صحيحة وتفسير كامل لاستعمال الطريقتين"},{"level":"3–5 درجات","description":"خطوات صحيحة مع تفسير ناقص"},{"level":"1–2 درجة","description":"ذكر الطريقتين دون ترتيب أو تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الترتيب دون تعليل","الاعتقاد أن الماء الناتج نقي تمامًا","إغفال أن الترويق غير تام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.312Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الماء الموحل: تنجح المحاولة (جزئيًّا)؛ لأنه مخلوط معلق جسيماته كبيرة تترسب بالجاذبية فيُسكب الماء فوقها. محلول السكر: تفشل المحاولة؛ لأن السكر ذائب في الماء فلا تترسب جسيماته. الحليب: تفشل المحاولة؛ لأنه مخلوط غروي جسيماته متوسطة الحجم (1–1000 nm) لا تترسب. إذن يصلح الترويق للمخلوط المعلق فقط.', '["الماء الموحل: ينجح لأنه معلق تترسب جسيماته","محلول السكر: يفشل لأن السكر ذائب","الحليب: يفشل لأن جسيماته الغروية لا تترسب","الاستنتاج: الترويق للمعلق فقط"]'::jsonb, '[]'::jsonb, '[{"element":"توقع وتفسير الماء الموحل","marks":2},{"element":"توقع وتفسير محلول السكر","marks":2},{"element":"توقع وتفسير الحليب","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"توقعات صحيحة للثلاثة مع تفسير مناسب لكل منها"},{"level":"3–5 درجات","description":"توقعان صحيحان معللان، أو ثلاثة دون تعليل كافٍ"},{"level":"1–2 درجة","description":"توقع واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توقع ترسب السكر إذا تُرك طويلًا","توقع ترسب الحليب","عدّ الحليب معلقًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.312Z"}'::jsonb)
