('mcq', 5, 'أيّ مما يأتي مثال على تأثير تندال في واقع الحياة؟', null, '["ترسب الطين في قاع كأس ماء موحل","ظهور مسار أشعة الشمس في الهواء المشبع بالدخان","ذوبان السكر في الشاي","انعكاس صورة شجرة على سطح بحيرة هادئة"]'::jsonb, 'تذكر', 'تذكر مثال', 'سهل', 'الكتاب ص 16 — تأثير تندال، الكيمياء في واقع الحياة'),
('mcq', 6, 'يُستعمل تأثير تندال في قياس تعكّر ماء الشرب. علامَ يدل ازدياد شدة الضوء المشتت من عينة ماء؟', null, '["ازدياد نقاء العينة من الشوائب","ازدياد كمية الملح الذائب في العينة","نقص عدد الجسيمات المنتشرة في العينة","ازدياد كمية الجسيمات المنتشرة في العينة"]'::jsonb, 'تطبيق', 'تطبيق في سياق عملي', 'متوسط', 'الكتاب ص 16–17 — تأثير تندال، مختبر تحليل البيانات'),
('mcq', 7, 'أظهر المخلوطان (أ) و(ب) تأثير تندال. ثم تُرك كلٌّ منهما ساعات دون تحريك، فترسبت جسيمات (أ) ولم تترسب جسيمات (ب). ما الاستنتاج الصحيح؟', null, '["(أ) غروي و(ب) معلق، وتأثير تندال يميز بينهما","(أ) معلق و(ب) محلول، وتأثير تندال يميز بينهما","(أ) معلق و(ب) غروي، وتأثير تندال وحده لا يميز بينهما","(أ) و(ب) غرويان، والترسب لا يميز بينهما"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 14–16 — المخلوط المعلق، تأثير تندال'),
('essay', 1, 'وضّح المقصود بتأثير تندال، واذكر أنواع المخاليط التي تُظهره والتي لا تُظهره، ثم اذكر مثالًا على ملاحظته في الحياة اليومية.', null, null, 'فهم', 'توضيح وتمثيل', 'متوسط', 'الكتاب ص 16 — تأثير تندال'),
('essay', 2, 'نرى أحيانًا مسار أشعة الشمس واضحًا عند مرورها خلال الغيوم أو في غرفة يتصاعد فيها دخان، في حين لا نرى مسارها في هواء نقي صافٍ. فسّر ذلك مستخدمًا تأثير تندال.', null, null, 'تطبيق', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 15–16 — الجدول 1-1، تأثير تندال، الكيمياء في واقع الحياة'),
('essay', 3, 'صمّم تجربة بسيطة تستعمل فيها تأثير تندال للمقارنة بين درجة تعكّر ثلاث عينات من ماء الشرب، محددًا: المتغير المستقل، والمتغير التابع، ومتغيرين ضابطين، وكيف تفسر النتائج.', null, null, 'إبداع', 'تصميم تجربة', 'صعب', 'الكتاب ص 16–17 — تأثير تندال، مختبر تحليل البيانات')
