('mcq', 1, 0, 'تأثير تندال هو تشتيت جسيمات المخلوط الغروي المنتشرة للضوء.', '["","هذا تعريف الحركة البراونية لا تأثير تندال.","هذا وصف الترويق في المعلق.","المحاليل لا تُظهر تأثير تندال، والتأثير تشتيت لا امتصاص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.313Z"}'::jsonb),
('mcq', 2, 1, 'يُظهر تأثير تندال المخاليط الغروية والمخاليط المعلقة، أما المحاليل فلا. الحليب المخفف مخلوط غروي، والماء الموحل مخلوط معلق، والهواء المشبع بالدخان مخلوط غروي؛ فكلها تُظهره. أما كل مجموعة أخرى ففيها محلول (ماء البحر المرشح، محلول السكر، الهواء النقي). فالإجابة: الحليب المخفف، الماء الموحل، الهواء المشبع بالدخان.', '["ماء البحر المرشح محلول (كلوريد الصوديوم في الماء)، والمحاليل لا تُظهر تأثير تندال.","","محلول السكر في الماء محلول متجانس لا يُظهر تأثير تندال، وإن أظهره الضباب والماء الموحل.","الهواء النقي محلول غازي لا يُظهر تأثير تندال، وإن أظهرته الغيوم والحليب المخفف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.313Z"}'::jsonb),
('mcq', 3, 2, 'جسيمات الغروي المنتشرة تشتت الضوء فيظهر مسار الحزمة في الكأس (2)، أما المحلول فلا يشتت الضوء.', '["المحلول لا يُظهر تأثير تندال، فلا يظهر فيه المسار.","المحلول لا يشتت الضوء، فلا يظهر المسار إلا في الغروي.","","الغروي المخفف يشتت الضوء رغم أنه يبدو صافيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.313Z"}'::jsonb),
('mcq', 4, 3, 'يبدو الغروي المخفف كالمحلول لأن عدد جسيماته المنتشرة قليل جدًّا، إلا أنها تعمل على تشتيت الضوء؛ فيظهر تأثير تندال.', '["جسيمات الغروي لا تترسب، والتأثير ناتج عن الجسيمات المنتشرة.","جسيمات الغروي أكبر من جسيمات المحلول، ولذلك تشتت الضوء.","لو امتُص الضوء كله لما ظهر مساره؛ والتأثير تشتيت لا امتصاص.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.313Z"}'::jsonb),
('mcq', 5, 1, 'يمكن ملاحظة تأثير تندال عند مرور أشعة الشمس خلال الهواء المشبع بالدخان؛ إذ تشتت جسيمات الدخان الضوء.', '["هذا ترسب جسيمات المعلق، لا تشتيت للضوء.","","هذا تكوين محلول، والمحاليل لا تُظهر تأثير تندال.","هذا انعكاس عن سطح، لا تشتيت للضوء بجسيمات منتشرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.313Z"}'::jsonb),
('mcq', 6, 3, 'يُستخدم تأثير تندال في تحديد كمية الجسيمات المنتشرة؛ فكلما زادت الجسيمات زاد الضوء المشتت، أي زاد تعكر الماء.', '["العينة الأنقى فيها جسيمات أقل فتشتت ضوءًا أقل.","المواد الذائبة تكوّن محلولًا لا يُظهر تأثير تندال.","نقص الجسيمات يقلل الضوء المشتت؛ هذا عكس العلاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.314Z"}'::jsonb),
('mcq', 7, 2, 'كلا المعلق والغروي يُظهر تأثير تندال، لكن جسيمات المعلق تترسب وجسيمات الغروي لا تترسب؛ فـ(أ) معلق و(ب) غروي، ولم يكفِ تأثير تندال وحده للتمييز.', '["عكس التصنيف؛ فالترسب صفة المعلق لا الغروي.","المحلول لا يُظهر تأثير تندال، و(ب) أظهره.","","جسيمات الغروي لا تترسب، فـ(أ) ليس غرويًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.314Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تأثير تندال: تشتيت جسيمات المخلوط الغروي المنتشرة للضوء، فيظهر مسار حزمة الضوء خلال المخلوط. تُظهره المخاليط الغروية والمخاليط المعلقة، ولا تُظهره المحاليل. مثال: ظهور أشعة الشمس عند مرورها خلال الهواء المشبع بالدخان، أو مرور الضوء خلال الضباب أو الغيوم.', '["التعريف: تشتيت الجسيمات المنتشرة للضوء","تُظهره المخاليط الغروية والمعلقة","لا تُظهره المحاليل","مثال صحيح من الحياة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المخاليط التي تُظهره","marks":1},{"element":"المخاليط التي لا تُظهره","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وتصنيف كامل ومثال مناسب"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في التصنيف أو المثال"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال أن المعلق يُظهر التأثير","القول إن المحاليل تُظهره","تعريفه بأنه امتصاص للضوء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.314Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الغيوم مخلوط غروي (هباء جوي سائل) تنتشر فيه قطيرات ماء في الهواء، والدخان مخلوط غروي (هباء جوي صلب) تنتشر فيه جسيمات صلبة في الهواء. هذه الجسيمات المنتشرة تشتت ضوء الشمس في اتجاهات مختلفة، فيصل جزء منه إلى أعيننا، فنرى مسار الأشعة (تأثير تندال). أما الهواء النقي فمحلول غازي لا يحتوي على جسيمات منتشرة تشتت الضوء، والمحاليل لا تُظهر تأثير تندال؛ فلا يُرى مسار الأشعة فيه.', '["الغيوم والدخان مخاليط غروية","الجسيمات المنتشرة تشتت الضوء فيصل إلى العين","الهواء النقي محلول","المحاليل لا تُظهر تأثير تندال"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الغيوم والدخان","marks":1},{"element":"تفسير تشتيت الضوء ورؤية المسار","marks":2},{"element":"تصنيف الهواء النقي","marks":1},{"element":"تفسير عدم ظهور المسار فيه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل للحالتين مستند إلى تأثير تندال"},{"level":"3–4 درجات","description":"تفسير صحيح لإحدى الحالتين وتفسير ناقص للأخرى"},{"level":"1–2 درجة","description":"ذكر اسم تأثير تندال دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الهواء النقي يمتص الضوء","عدّ الهواء النقي مخلوطًا غرويًّا","تفسير الظاهرة بانعكاس الضوء عن سطح الغيوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.314Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التجربة: توضع كميات متساوية من العينات الثلاث في كؤوس زجاجية شفافة متماثلة في غرفة معتمة، ويُمرَّر ضوء المصباح نفسه من الجانب خلال كل كأس من المسافة نفسها، وتُلاحظ (أو تُقاس بمقياس ضوء) شدة الضوء المشتت ووضوح مسار الحزمة. المتغير المستقل: نوع العينة (مصدر الماء). المتغير التابع: شدة الضوء المشتت (وضوح مسار الحزمة). المتغيرات الضابطة: حجم العينة، ونوع الكأس، ومصدر الضوء وشدته، والمسافة وزاوية الرصد. التفسير: العينة التي تشتت ضوءًا أكثر تحتوي على جسيمات منتشرة أكثر، فهي الأكثر تعكرًا؛ والعينة التي لا يظهر فيها مسار الحزمة تقريبًا هي الأقل تعكرًا.', '["إجراء: تمرير الضوء نفسه خلال عينات متساوية في كؤوس متماثلة","المتغير المستقل: العينة","المتغير التابع: شدة الضوء المشتت","متغيران ضابطان مناسبان","التفسير: تشتيت أكثر يعني جسيمات أكثر وتعكرًا أعلى"]'::jsonb, '[]'::jsonb, '[{"element":"خطوات الإجراء","marks":2},{"element":"المتغير المستقل","marks":1},{"element":"المتغير التابع","marks":1},{"element":"متغيران ضابطان","marks":1},{"element":"تفسير النتائج","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تصميم منطقي كامل مع تحديد صحيح للمتغيرات وتفسير سليم"},{"level":"3–5 درجات","description":"تصميم مقبول مع نقص في تحديد المتغيرات أو التفسير"},{"level":"1–2 درجة","description":"فكرة تمرير الضوء دون تحديد متغيرات أو تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل شدة الضوء المشتت متغيرًا مستقلًا","عدم تثبيت مصدر الضوء أو حجم العينة","تفسير التشتت الأكبر بنقاء أعلى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.315Z"}'::jsonb)
