('mcq', 1, 'أي مما يأتي يفسّر بقاء الجسيمات المنتشرة في المخلوط الغروي دون أن تترسب؟', null, '["ذوبان الجسيمات المنتشرة ذوبانًا تامًّا في وسط الانتشار","تكوّن طبقات كهروستاتيكية حولها تجعلها تتنافر عند تصادمها","كِبَر أحجام الجسيمات المنتشرة مقارنة بجسيمات المخلوط المعلق","تفاعل الجسيمات المنتشرة كيميائيًّا مع جسيمات وسط الانتشار"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 15 — المخاليط الغروية'),
('mcq', 2, 'ما الذي يتكوّن حول الجسيمات المنتشرة في المخلوط الغروي نتيجة جذب المجموعات المشحونة على سطحها لجسيمات وسط الانتشار؟', null, '["روابط تساهمية دائمة","طبقة من راسب صلب","فقاعات غازية صغيرة","طبقات كهروستاتيكية مشحونة"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 15 — المخاليط الغروية'),
('mcq', 3, 'عندما يقترب جسيمان منتشران في مخلوط غروي أحدهما من الآخر ويتصادمان، فإن الطبقتين الكهروستاتيكيتين المحيطتين بهما:', null, '["تتنافران فيبقى الجسيمان منفصلين","تتجاذبان فيتحد الجسيمان ويترسبان","تتعادلان فيذوب الجسيمان في الوسط","تختفيان فيزداد حجم الجسيمين"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 15 — المخاليط الغروية'),
('mcq', 4, 'كيف تُسهم الحركة البراونية في منع ترسب الجسيمات المنتشرة في المخلوط الغروي السائل؟', null, '["تنقل الشحنات من جسيمات الوسط إلى الجسيمات المنتشرة فتتعادل","تُذيب الجسيمات المنتشرة تدريجيًّا في وسط الانتشار","تصادمات جسيمات الوسط بالجسيمات المنتشرة تُبقيها متحركة فلا تترسب","تدفع الجسيمات المنتشرة كلها لتتجمع عند سطح المخلوط"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 16 — الحركة البراونية'),
('mcq', 5, 'تُرك مخلوطان فترة دون تحريك: الأول تتراوح أقطار جسيماته بين 1 nm و1000 nm، والثاني جسيماته أكبر من ذلك كثيرًا. لوحظ ترسب جسيمات الثاني فقط. ما التفسير الأنسب؟', null, '["جسيمات الأول متوسطة الحجم تبقيها الطبقات الكهروستاتيكية والحركة البراونية منتشرة، وجسيمات الثاني كبيرة فتترسب","الأول محلول ذابت جسيماته في المذيب، والثاني مخلوط غروي تترسب جسيماته عند تركه","جسيمات الثاني تحيط بها طبقات كهروستاتيكية أقوى، فتتجاذب وتترسب أسرع","لا تحدث في الأول أي تصادمات بين الجسيمات، بينما تتصادم جسيمات الثاني فتترسب"]'::jsonb, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 14–16 — المخلوط المعلق والمخاليط الغروية'),
('mcq', 6, 'أي الخصائص الآتية لسطح الجسيمات المنتشرة في المخلوط الغروي هي أصل الطبقات التي تمنعها من الترسب؟', null, '["خلوّ سطحها من أي شحنات أو مجموعات قطبية","وجود طبقة دهنية عازلة تغلّف سطحها","ارتفاع كثافة سطحها مقارنة بوسط الانتشار","وجود مجموعات ذرية أو قطبية مشحونة على سطحها"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 15 — المخاليط الغروية'),
('mcq', 7, 'لو أمكن إزالة الطبقات الكهروستاتيكية المحيطة بجسيمات مخلوط غروي، فما المتوقع أن يحدث؟', null, '["يتحول المخلوط إلى محلول متجانس","تزداد الجسيمات تنافرًا فتتباعد أكثر","تتجمع الجسيمات عند تصادمها فتترسب","تبقى الجسيمات منتشرة دون أي تغيير"]'::jsonb, 'تطبيق', 'تنبؤ', 'متوسط', 'الكتاب ص 15 — المخاليط الغروية'),
('essay', 1, 'اشرح سببين لعدم ترسب جسيمات المخلوط الغروي.', null, null, 'فهم', 'شرح', 'متوسط', 'الكتاب ص 15–16 — المخاليط الغروية؛ الحركة البراونية (ماذا قرأت؟)'),
('essay', 2, 'في نموذج يمثّل مخلوطًا غرويًّا جسيمات غروية سطحها مشحون بشحنات موجبة، تحيط بها جسيمات من وسط الانتشار، ويُشار فيه إلى «تجاذب» بين الجسيم الغروي وجسيمات الوسط، وإلى «تنافر» بين جسيمين غرويين. صف ما يحدث على مستوى الجسيمات في هذا الشكل، وبيّن كيف يؤدي التجاذب والتنافر معًا إلى بقاء الجسيمات منتشرة.', null, null, 'تحليل', 'تفسير شكل', 'صعب', 'الكتاب ص 15 — الشكل 1-2'),
('essay', 3, 'قارن بين سلوك جسيمات الماء الموحل (مخلوط معلق) وجسيمات الحليب (مخلوط غروي) عند ترك كلٍّ منهما فترة دون تحريك، وفسّر سبب الاختلاف.', null, null, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 14–16 — المخلوط المعلق والمخاليط الغروية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
