select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'على سطح الجسيمات المنتشرة مجموعات ذرية أو قطبية مشحونة تجذب جسيمات وسط الانتشار، فتتكون حولها طبقات كهروستاتيكية تتنافر عند تصادم الجسيمات، فتبقى الجسيمات منتشرة ولا تترسب. إذن الإجابة: تكوّن طبقات كهروستاتيكية حولها تجعلها تتنافر عند تصادمها.', '["الجسيمات المنتشرة لا تذوب؛ فلو ذابت لكان المخلوط محلولًا لا مخلوطًا غرويًّا، والمخلوط الغروي غير متجانس.","","العكس هو الصحيح؛ فجسيمات المعلق أكبر كثيرًا، وجسيمات الغروي متوسطة الحجم (1 nm إلى 1000 nm).","لا يحدث تفاعل كيميائي؛ فالمخلوط تحتفظ فيه كل مادة بخصائصها، والسبب تجاذب كهروستاتيكي يكوّن طبقات تتنافر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.315Z"}'::jsonb),
('mcq', 2, 3, 'تجذب المجموعات الذرية أو القطبية المشحونة على سطح الجسيمات المنتشرة المناطقَ الموجبة أو السالبة لجسيمات وسط الانتشار، فتتكون حول الجسيمات طبقات كهروستاتيكية. فالإجابة: طبقات كهروستاتيكية مشحونة.', '["التجاذب هنا كهروستاتيكي بين مناطق مشحونة، ولا تتكون روابط تساهمية بين الجسيمات المنتشرة ووسط الانتشار.","لا يتكون راسب حول الجسيمات؛ بل إن الطبقات المتكونة تمنع الترسب.","الجسيمات المنتشرة تجذب جسيمات الوسط نفسه لا غازًا، فلا تتكون فقاعات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.315Z"}'::jsonb),
('mcq', 3, 0, 'الطبقات الكهروستاتيكية يتنافر بعضها مع بعض عندما تتصادم الجسيمات المنتشرة، فتبقى الجسيمات منفصلة في المخلوط الغروي ولا تترسب. إذن: تتنافران فيبقى الجسيمان منفصلين.', '["","الطبقتان متشابهتان في الشحنة فتتنافران ولا تتجاذبان؛ والتجمع والترسب يحدثان فقط إذا تُدُخِّل في هذه الطبقات.","لا تتعادل الطبقات عند التصادم ولا تذوب الجسيمات؛ بل تتنافر الطبقات وتبقى الجسيمات منتشرة.","لا تختفي الطبقات بمجرد التصادم؛ واختفاؤها لو حدث لأدى إلى تجمع الجسيمات وترسبها لا إلى بقائها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.316Z"}'::jsonb),
('mcq', 4, 2, 'الحركة البراونية تنتج عن تصادم جسيمات الوسط مع الجسيمات المنتشرة، وأن هذه التصادمات تمنع الجسيمات المنتشرة من الترسب في المخلوط. فالإجابة: تصادمات جسيمات الوسط بالجسيمات المنتشرة تُبقيها متحركة فلا تترسب.', '["الحركة البراونية تصادمات تُحرّك الجسيمات، وليست انتقالًا للشحنات؛ وتعادل الشحنات لو حدث لأتلف المخلوط.","الحركة البراونية لا تُذيب الجسيمات؛ فالجسيمات تبقى منتشرة غير ذائبة والمخلوط غروي غير متجانس.","","الحركة البراونية عشوائية في كل الاتجاهات، فلا تجمع الجسيمات في مكان واحد؛ بل تُبقيها موزعة في المخلوط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.316Z"}'::jsonb),
('mcq', 5, 0, 'المخلوط الأول غروي (أقطار جسيماته بين 1 nm و1000 nm)، تُبقي جسيماته منتشرةً الطبقاتُ الكهروستاتيكية المتنافرة حولها والحركة البراونية. أما الثاني فمخلوط معلق جسيماته أكبر كثيرًا من جسيمات الوسط فتترسب بالترويق. إذن الإجابة: جسيمات الأول متوسطة الحجم تبقيها الطبقات الكهروستاتيكية والحركة البراونية منتشرة، وجسيمات الثاني كبيرة فتترسب.', '["","أقطار الجسيمات من 1 nm إلى 1000 nm هي مدى المخلوط الغروي لا المحلول، والمخلوط الغروي لا تترسب جسيماته؛ أما الذي تترسب جسيماته فهو المعلق.","الطبقات الكهروستاتيكية تسبب التنافر وتمنع الترسب لا التجاذب؛ وسبب ترسب جسيمات المعلق كبر حجمها.","في المخلوط الغروي تحدث تصادمات مستمرة (الحركة البراونية)، وهي من أسباب عدم الترسب؛ فالتصادم لا يسبب الترسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.316Z"}'::jsonb),
('mcq', 6, 3, 'الجسيمات المنتشرة تُمنع من الترسب لوجود مجموعات ذرية أو قطبية مشحونة على سطحها، تجذب المناطق الموجبة أو السالبة لجسيمات وسط الانتشار فتتكون الطبقات الكهروستاتيكية. فالإجابة: وجود مجموعات ذرية أو قطبية مشحونة على سطحها.', '["لو خلا السطح من الشحنات لما جذبت الجسيماتُ جسيماتِ الوسط ولما تكونت الطبقات الكهروستاتيكية.","لا توجد طبقة دهنية؛ فالطبقات المذكورة كهروستاتيكية تنشأ عن مجموعات مشحونة على السطح.","الكثافة الأعلى تُسرّع الترسب لا تمنعه، فعدم الترسب مرتبط بالمجموعات المشحونة على السطح.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.316Z"}'::jsonb),
('mcq', 7, 2, 'الطبقات الكهروستاتيكية هي ما يجعل الجسيمات تتنافر فلا تتجمع. وإذا تدخلنا في هذه الطبقات فسوف تترسب الجسيمات المنتشرة، إذ تتجمع معًا ويتلف المخلوط الغروي. فالمتوقع: تتجمع الجسيمات عند تصادمها فتترسب.', '["إزالة الطبقات لا تُذيب الجسيمات؛ فلا ينتج محلول، بل تتجمع الجسيمات وتترسب.","التنافر مصدره الطبقات نفسها؛ فإذا زالت زال التنافر ولم يزدد.","","الطبقات الكهروستاتيكية سبب رئيس لعدم الترسب؛ والتدخل فيها يؤدي إلى ترسب الجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.316Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السبب الأول: على سطح الجسيمات المنتشرة مجموعات ذرية أو قطبية مشحونة تجذب المناطق الموجبة أو السالبة لجسيمات وسط الانتشار، فتتكون حول الجسيمات طبقات كهروستاتيكية يتنافر بعضها مع بعض عندما تتصادم الجسيمات، فتبقى منفصلة ولا تترسب. السبب الثاني: الحركة البراونية؛ وهي حركة عشوائية مستمرة تنتج عن تصادم جسيمات وسط الانتشار مع الجسيمات المنتشرة، وهذه التصادمات تمنع الجسيمات المنتشرة من الترسب.', '["مجموعات مشحونة على سطح الجسيمات تجذب جسيمات الوسط فتتكون طبقات كهروستاتيكية","تنافر الطبقات عند تصادم الجسيمات يُبقيها منفصلة","الحركة البراونية: تصادم جسيمات الوسط مع الجسيمات المنتشرة","هذه التصادمات تمنع الجسيمات من الترسب"]'::jsonb, '[]'::jsonb, '[{"element":"تكوّن الطبقات الكهروستاتيكية وسببه","marks":1},{"element":"تنافر الطبقات ومنعه الترسب","marks":1},{"element":"الحركة البراونية وسببها (تصادم جسيمات الوسط)","marks":1},{"element":"ربط التصادمات بمنع الترسب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يشرح السببين كاملين: تكوّن الطبقات الكهروستاتيكية وتنافرها، والحركة البراونية الناتجة عن التصادمات ودورها."},{"level":"2–3 درجات","description":"يذكر السببين مع شرح ناقص لأحدهما، أو يشرح سببًا واحدًا شرحًا كاملًا."},{"level":"درجة واحدة","description":"يذكر اسم سبب واحد دون شرح."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["القول إن الجسيمات المنتشرة تذوب في وسط الانتشار.","القول إن الطبقات الكهروستاتيكية تتجاذب بدل أن تتنافر.","ذكر الحركة البراونية دون بيان أنها ناتجة عن تصادم جسيمات الوسط مع الجسيمات المنتشرة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.317Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الشحنات الموجبة على سطح الجسيم الغروي تجذب المناطق السالبة من جسيمات وسط الانتشار (التجاذب)، فتتجمع حول كل جسيم غروي طبقة من جسيمات الوسط تُسمى طبقة كهروستاتيكية. ولأن الجسيمات الغروية تحاط بطبقات متشابهة، فعندما يقترب جسيمان ويتصادمان تتنافر طبقتاهما (التنافر)، فلا يلتصق الجسيمان ولا يتجمعان في جسيمات أكبر. وبذلك يؤدي التجاذب إلى تكوين الطبقات، ويؤدي التنافر بين الطبقات إلى منع تجمع الجسيمات، فتبقى منتشرة في المخلوط ولا تترسب.', '["التجاذب بين الشحنات على سطح الجسيم والمناطق المخالفة الشحنة في جسيمات الوسط","تكوّن طبقة كهروستاتيكية حول كل جسيم","التنافر بين الطبقات المتشابهة عند تصادم جسيمين","عدم تجمع الجسيمات وعدم ترسبها","الربط بين دوري التجاذب والتنافر"]'::jsonb, '[]'::jsonb, '[{"element":"وصف التجاذب ومصدره","marks":1},{"element":"تكوّن الطبقات الكهروستاتيكية","marks":1},{"element":"وصف التنافر عند التصادم","marks":1},{"element":"النتيجة: لا تجمع ولا ترسب","marks":1},{"element":"الربط بين التجاذب والتنافر في تفسير واحد","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"يصف التجاذب والطبقات والتنافر، ويستنتج عدم الترسب، ويربط الدورين بوضوح."},{"level":"3–4 درجات","description":"يصف معظم العناصر مع نقص في الربط أو في تحديد مصدر التجاذب."},{"level":"1–2 درجة","description":"يذكر التجاذب أو التنافر فقط دون تفسير متماسك."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الخلط بين التجاذب (جسيم–وسط) والتنافر (طبقة–طبقة).","القول إن الجسيمات الغروية تتجاذب فيما بينها.","إغفال أن تنافر الطبقات يمنع تجمع الجسيمات في جسيمات أكبر."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.317Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عند ترك الماء الموحل دون تحريك تترسب جسيماته في القاع (الترويق)؛ لأن أحجام جسيمات المخلوط المعلق أكبر كثيرًا من أحجام جسيمات الوسط. أما الحليب فلا تترسب جسيماته، ولا يمكن فصل مكوناته بالترويق أو الترشيح؛ لأن جسيماته متوسطة الحجم (أقطارها بين 1 nm و1000 nm)، وتحيط بها طبقات كهروستاتيكية تتنافر عند التصادم، كما أن الحركة البراونية الناتجة عن تصادم جسيمات الوسط بالجسيمات المنتشرة تمنعها من الترسب.', '["جسيمات الماء الموحل تترسب عند تركه","سبب ترسبها: كبر حجمها مقارنة بجسيمات الوسط","جسيمات الحليب لا تترسب ولا تُفصل بالترويق","حجم الجسيمات الغروية 1 nm–1000 nm","الطبقات الكهروستاتيكية والحركة البراونية تمنع الترسب"]'::jsonb, '[]'::jsonb, '[{"element":"سلوك الماء الموحل","marks":1},{"element":"تفسير ترسب جسيمات المعلق","marks":1},{"element":"سلوك الحليب","marks":1},{"element":"تفسير بالطبقات الكهروستاتيكية","marks":1},{"element":"تفسير بالحركة البراونية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"يقارن السلوكين بدقة ويفسر ترسب المعلق وعدم ترسب الغروي بالسببين."},{"level":"3–4 درجات","description":"يقارن السلوكين ويفسر بسبب واحد لعدم ترسب الغروي."},{"level":"1–2 درجة","description":"يصف السلوكين دون تفسير، أو يفسر أحدهما فقط."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["القول إن جسيمات الحليب تترسب ببطء ثم تُفصل بالترويق.","تفسير عدم ترسب جسيمات الحليب بأنها ذائبة.","عكس أحجام الجسيمات بين المعلق والغروي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.317Z"}'::jsonb)
