('mcq', 1, 2, 'الضباب قطيرات ماء سائلة منتشرة في الهواء (وسط غازي)، ولذلك يُصنَّف هباءً جويًّا سائلًا مثل الغيوم ورذاذ مزيل العرق. فالإجابة: هباء جوي سائل.', '["الهباء الجوي الصلب جسيماته المنتشرة صلبة كالدخان والغبار، أما الضباب فقطيرات سائلة في الهواء.","المستحلب سائل منتشر في وسط سائل كالحليب، أما وسط انتشار الضباب فغاز (الهواء).","","الرغوة الصلبة غاز منتشر في وسط صلب كحلوى الخطمي، والضباب سائل منتشر في غاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.318Z"}'::jsonb),
('mcq', 2, 0, 'الضباب مخلوط تنتشر فيه قطيرات ماء صغيرة في الهواء، وعندما يسقط عليها ضوء المصابيح تشتته في اتجاهات مختلفة (تأثير تندال)، فيرتد جزء منه نحو السائق كستارة مضيئة تحجب الطريق. إذن السبب: تشتيت قطيرات الضباب لضوء المصابيح فيرتد جزء منه نحو عيني السائق.', '["","الضباب لا يمتص الضوء كله؛ والسبب الرئيس لضعف الرؤية تشتيت القطيرات للضوء (تأثير تندال).","الضباب ليس محلولًا بل هباء جوي سائل، والمحاليل لا تُظهر تأثير تندال ولا تحجب الرؤية.","المصابيح لا تنطفئ، والمشكلة في ما يحدث للضوء بعد خروجه وسقوطه على القطيرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.318Z"}'::jsonb),
('mcq', 3, 3, 'حزمة الأنوار العالية قوية وموجهة إلى الأمام والأعلى، فتسقط على عدد أكبر من قطيرات الضباب في مستوى نظر السائق، فتشتت القطيرات الضوء (تأثير تندال) ويزداد الضوء المرتد نحو عينيه، أما الأنوار المنخفضة فموجهة نحو سطح الطريق. فالإجابة: لأن حزمتها القوية الموجهة إلى الأمام والأعلى تضيء قطيرات أكثر في مستوى نظر السائق فيزداد الضوء المشتت المرتد نحوه.', '["الأنوار لا تبخر الضباب ولا تزيد سمكه؛ وصعوبة الرؤية سببها زيادة الضوء المشتت المرتد.","الضوء الساقط على قطيرات الضباب يتشتت أيًّا كانت شدته؛ والأنوار العالية تزيد التشتت لا تلغيه.","المشكلة ليست ظلمة الطريق بالامتصاص، بل الضوء المشتت المرتد الذي يحجب الرؤية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.318Z"}'::jsonb),
('mcq', 4, 1, 'الأنوار المنخفضة ومصابيح الضباب موجهة إلى أسفل نحو سطح الطريق، فيقل الضوء الذي تشتته القطيرات في مستوى عيني السائق، وتبقى الرؤية أوضح. فالإجراء الأنسب: استعمال الأنوار المنخفضة أو مصابيح الضباب المثبتة في أسفل السيارة.', '["زيادة الضوء الساقط على القطيرات تزيد الضوء المشتت المرتد نحو السائق فتسوء الرؤية.","","إطفاء الأنوار يُفقد السائق رؤية الطريق ويجعل الآخرين لا يرون سيارته؛ والحل توجيه الضوء إلى أسفل لا إلغاؤه.","توجيه الضوء إلى الأعلى يُسقطه على قطيرات أكثر في مستوى النظر فيزداد التشتت المرتد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (2%)"}],"at":"2026-10-17T11:36:22.318Z"}'::jsonb),
('mcq', 5, 2, 'ظهور مسار حزمة الضوء نتيجة تشتيت الجسيمات المنتشرة له يُسمى تأثير تندال، ويُلاحظ عند مرور ضوء خلال الضباب. فالإجابة: تأثير تندال.', '["الحركة البراونية حركة عشوائية لجسيمات المخلوط الغروي السائل، لا علاقة لها بظهور مسار الضوء.","الترويق ترسب جسيمات المعلق عند تركه دون تحريك، وليس ظاهرة ضوئية.","","الامتزاج وصف لسائلين يذوب أحدهما في الآخر، وليس ظاهرة ضوئية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.319Z"}'::jsonb),
('mcq', 6, 1, 'الرطوبة محلول غازي (الماء مذاب في الهواء)، والمحاليل لا تُظهر تأثير تندال لأنه لا يمكن تمييز المذاب فيها. أما الضباب فهباء جوي سائل تشتت قطيراته الضوء. إذن: الرطوبة محلول غازي لا يُظهر تأثير تندال، أما الضباب فهباء جوي سائل تشتت قطيراته الضوء.', '["الرطوبة محلول غازي (ماء مذاب في الهواء)، والضباب هباء جوي سائل لا محلول؛ فالتصنيفان معكوسان وخاطئان.","","الماء في الضباب قطيرات سائلة منتشرة لا بخار ذائب، وهذا الفرق في الحالة هو سبب ظهور تأثير تندال.","المحاليل ومنها الرطوبة لا تُظهر تأثير تندال؛ فالفرق في نوع المخلوط لا في الكثافة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.319Z"}'::jsonb),
('mcq', 7, 0, 'الدخان في الهواء هباء جوي صلب، وجسيماته المنتشرة تشتت الضوء كما تشتته قطيرات الضباب؛ وتأثير تندال يُشاهد عند مرور أشعة الشمس خلال الهواء المشبع بالدخان. فالسبب: جسيمات الدخان الصلبة المنتشرة في الهواء تشتت ضوء المصابيح.', '["","الدخان ليس محلولًا بل هباء جوي صلب، والسبب الرئيس هو تشتيت الضوء لا امتصاصه الكامل.","جسيمات الدخان لا تذوب في الهواء؛ بل تبقى منتشرة فيه، ولو ذابت لما شتتت الضوء.","المستحلب سائل في سائل، أما الدخان فجسيمات صلبة في غاز (هباء جوي صلب)، وهي تشتت الضوء في اتجاهات مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.319Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الضباب هباء جوي سائل؛ أي قطيرات ماء سائلة صغيرة منتشرة في الهواء (وسط غازي). عندما يسقط ضوء المصابيح على هذه القطيرات فإنها تشتته في اتجاهات مختلفة، فيظهر مسار حزمة الضوء واضحًا، وتُسمى هذه الظاهرة تأثير تندال. ويرتد جزء من الضوء المشتت نحو السائق فتضعف رؤيته للطريق.', '["الضباب هباء جوي سائل (سائل منتشر في غاز)","القطيرات تشتت الضوء في اتجاهات مختلفة","اسم الظاهرة: تأثير تندال","ارتداد جزء من الضوء نحو السائق فتضعف الرؤية"]'::jsonb, '[]'::jsonb, '[{"element":"نوع المخلوط الغروي للضباب","marks":1},{"element":"تشتيت القطيرات للضوء","marks":1},{"element":"تسمية الظاهرة","marks":1},{"element":"أثر ذلك في رؤية السائق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يذكر نوع الضباب، ويصف التشتت، ويسمي الظاهرة، ويبين أثرها في الرؤية."},{"level":"2–3 درجات","description":"يصف التشتت ويسمي الظاهرة مع نقص في التصنيف أو الأثر."},{"level":"درجة واحدة","description":"يسمي الظاهرة فقط أو يذكر نوع الضباب فقط."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["تصنيف الضباب هباءً جويًّا صلبًا أو محلولًا.","القول إن الضباب يمتص الضوء كله.","الخلط بين تأثير تندال والحركة البراونية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.319Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المنطقة (1): الرطوبة محلول غازي (الماء مذاب في الهواء)، والمحاليل لا تُظهر تأثير تندال، فلا تضعف الرؤية بسببه. المنطقة (2): الضباب مخلوط غروي من نوع الهباء الجوي السائل؛ قطيراته تشتت ضوء المصابيح فتضعف الرؤية. المنطقة (3): الدخان مخلوط غروي من نوع الهباء الجوي الصلب؛ جسيماته الصلبة تشتت الضوء فتضعف الرؤية أيضًا. إذن تضعف الرؤية في المنطقتين (2) و(3) لأن جسيماتهما المنتشرة تشتت الضوء، ولا تضعف في (1) لأنها محلول.', '["الرطوبة محلول غازي","الضباب هباء جوي سائل","الدخان هباء جوي صلب","المحاليل لا تُظهر تأثير تندال","الضعف في المنطقتين (2) و(3) لتشتيت الجسيمات المنتشرة للضوء"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الرطوبة","marks":1},{"element":"تصنيف الضباب","marks":1},{"element":"تصنيف الدخان","marks":1},{"element":"التنبؤ بالمنطقتين الصحيحتين","marks":1},{"element":"التبرير بتأثير تندال وعدم ظهوره في المحاليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"يصنف المناطق الثلاث بدقة، ويتنبأ بالمنطقتين (2) و(3)، ويبرر بتأثير تندال."},{"level":"3–4 درجات","description":"يتنبأ تنبؤًا صحيحًا مع خطأ في تصنيف واحد أو تبرير ناقص."},{"level":"1–2 درجة","description":"يتنبأ بمنطقة واحدة صحيحة أو يصنف دون تنبؤ."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["عدّ الرطوبة مخلوطًا غرويًّا يُظهر تأثير تندال.","تصنيف الدخان هباءً جويًّا سائلًا.","القول إن الرؤية تضعف في الضباب فقط لأنه يحتوي على ماء."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.320Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. فالضباب هباء جوي سائل تشتت قطيراته الضوء (تأثير تندال). والأنوار العالية حزمتها قوية وموجهة إلى الأمام والأعلى، فتسقط على عدد أكبر من القطيرات في مستوى نظر السائق، فيزداد الضوء المشتت المرتد نحوه، ويرى أمامه ما يشبه ستارة مضيئة تحجب الطريق؛ فزيادة الإضاءة هنا تسوء بها الرؤية. والممارسة الأفضل استعمال الأنوار المنخفضة أو مصابيح الضباب المثبتة أسفل السيارة؛ لأنها موجهة نحو سطح الطريق فيقل الضوء المشتت في مستوى عيني السائق.', '["الحكم: العبارة غير صحيحة","قطيرات الضباب تشتت الضوء (تأثير تندال)","الأنوار العالية تضيء قطيرات أكثر في مستوى النظر فيزداد الضوء المرتد","اقتراح الأنوار المنخفضة أو مصابيح الضباب","تبرير الاقتراح بتوجيه الضوء نحو الطريق"]'::jsonb, '[]'::jsonb, '[{"element":"إصدار حكم صحيح","marks":1},{"element":"التفسير بتأثير تندال","marks":1},{"element":"بيان أثر الأنوار العالية","marks":1},{"element":"الممارسة البديلة","marks":1},{"element":"تبرير الممارسة البديلة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"يحكم بخطأ العبارة، ويفسر بتأثير تندال وأثر الأنوار العالية، ويقترح البديل ويبرره."},{"level":"3–4 درجات","description":"يحكم ويفسر مع نقص في تبرير البديل أو في بيان أثر الأنوار العالية."},{"level":"1–2 درجة","description":"يحكم بخطأ العبارة مع تفسير ضعيف أو دون بديل."},{"level":"صفر","description":"يؤيد العبارة أو لا يجيب."}]'::jsonb, '["تأييد العبارة لأن الضوء الأكثر يعني رؤية أفضل دائمًا.","اقتراح إطفاء الأنوار كليًّا.","تفسير صعوبة الرؤية بامتصاص الضباب للضوء فقط."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.320Z"}'::jsonb)
