('mcq', 5, 'شاهد طالب بالمجهر جسيمات دقيقة منتشرة في مخلوط غروي سائل. أيّ الأوصاف الآتية يطابق حركتها إذا كانت حركة براونية؟', null, '["تتحرك ببطء في خط مستقيم نحو قاع الإناء","تتحرك باستمرار في اتجاهات عشوائية متغيرة","تتحرك في مسارات منتظمة ثم تتوقف بعد دقائق","تبقى ساكنة تمامًا في أماكنها دون أي حركة"]'::jsonb, 'فهم', 'تطبيق تعريف', 'متوسط', 'الكتاب ص 16 — الحركة البراونية'),
('mcq', 6, 'في أيّ مما يأتي يُتوقع أن تُلاحظ الحركة البراونية؟', null, '["جسيمات الدهن المنتشرة في الحليب","حبيبات الرمل المترسبة في قاع كأس ماء","برادة الحديد الموضوعة في كأس جافة","قطع الطين الكبيرة في الماء الموحل بعد ترسبها"]'::jsonb, 'تطبيق', 'تطبيق في موقف جديد', 'متوسط', 'الكتاب ص 15–16 — المخاليط الغروية؛ الحركة البراونية'),
('mcq', 7, 'أيّ العبارات الآتية تصف الحركة البراونية وصفًا صحيحًا؟', null, '["تُلاحظ في المحاليل، وتنتج عن تشتيت جسيمات المذاب للضوء","تُلاحظ في المخاليط المعلقة، وتنتج عن جذب الأرض للجسيمات","تُلاحظ في المخاليط الغروية، وتنتج عن إضافة مادة متأينة إليها","تُلاحظ في المخاليط الغروية السائلة، وتنتج عن تصادم جسيمات الوسط بالجسيمات المنتشرة"]'::jsonb, 'فهم', 'تمييز عبارة صحيحة', 'صعب', 'الكتاب ص 16 — الحركة البراونية'),
('essay', 1, 'عرّف الحركة البراونية، واذكر اسم العالِم الذي لاحظها أول مرة، وفي أيّ مادة لاحظها.', null, null, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 16 — الحركة البراونية'),
('essay', 2, 'ما الذي يسبب الحركة البراونية؟ وما أثرها في الجسيمات المنتشرة في المخلوط الغروي؟', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 16 و18 — الحركة البراونية؛ التقويم 1-1 س7'),
('essay', 3, 'كتب طالب: «الحركة البراونية وتأثير تندال اسمان لظاهرة واحدة تحدث في المخاليط الغروية». ناقش صحة هذه العبارة، مبيّنًا الفرق بين الظاهرتين من حيث: ماهية كلٍّ منهما، وسببها أو ما تنتج عنه.', null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 16 — الحركة البراونية؛ تأثير تندال')
