select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الحركة البراونية هي حركة عشوائية غير منتظمة ومستمرة تتحركها الجسيمات المنتشرة في المخاليط الغروية السائلة. فالإجابة: حركة عشوائية غير منتظمة ومستمرة لجسيمات المخلوط الغروي السائل.', '["","الحركة البراونية عشوائية غير منتظمة، وهي حركة لجسيمات المخاليط الغروية السائلة لا المحاليل.","هذا وصف لترسب جسيمات المعلق (الترويق)، والحركة البراونية بالعكس تمنع الترسب.","تشتيت الجسيمات للضوء هو تأثير تندال، وليس الحركة البراونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.321Z"}'::jsonb),
('mcq', 2, 2, 'لاحظ عالم النبات الإسكتلندي روبرت براون (1773–1858) هذه الحركة أول مرة، فسُمّيت باسمه. فالإجابة: روبرت براون.', '["ارتبط اسم تندال بظاهرة تشتيت الجسيمات المنتشرة للضوء (تأثير تندال)، لا بالحركة البراونية.","دالتون صاحب النظرية الذرية، ولم يلاحظ الحركة العشوائية لحبوب اللقاح.","","مندليف معروف بترتيب الجدول الدوري، ولا علاقة له بالحركة البراونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-17T11:36:22.321Z"}'::jsonb),
('mcq', 3, 1, 'لاحظ روبرت براون الحركة العشوائية لحبوب اللقاح المتناثرة في الماء أول مرة. فالإجابة: حبوب اللقاح المتناثرة في الماء.', '["لاحظ براون الحركة في حبوب اللقاح في الماء، لا في الدخان.","","الزيت والخل مثال على السوائل غير الممتزجة، لا على مشاهدة براون.","السكر يذوب في الماء مكونًا محلولًا، وبراون لاحظ حبوب لقاح غير ذائبة متناثرة في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.321Z"}'::jsonb),
('mcq', 4, 3, 'الحركة البراونية تنتج عن تصادم جسيمات الوسط مع الجسيمات المنتشرة. فالإجابة: تصادم جسيمات وسط الانتشار مع الجسيمات المنتشرة.', '["الجاذبية تسبب الترسب في المخلوط المعلق، أما الحركة البراونية فعشوائية في كل الاتجاهات وتمنع الترسب.","تشتيت الضوء هو تأثير تندال، وهو ظاهرة ضوئية لا تسبب حركة الجسيمات.","الجسيمات المنتشرة في المخلوط الغروي لا تذوب، وإلا لكان المخلوط محلولًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-17T11:36:22.321Z"}'::jsonb),
('mcq', 5, 1, 'الحركة البراونية عشوائية غير منتظمة ومستمرة؛ فالطالب يرى الجسيمات تتحرك دون توقف وفي اتجاهات تتغير باستمرار. فالإجابة: تتحرك باستمرار في اتجاهات عشوائية متغيرة.', '["الحركة نحو القاع ترسب، والحركة البراونية عشوائية الاتجاه وتمنع الترسب.","","الحركة البراونية غير منتظمة ومستمرة، فلا تكون مساراتها منتظمة ولا تتوقف.","الجسيمات المنتشرة في المخلوط الغروي السائل في حركة مستمرة، فلا تكون ساكنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-17T11:36:22.321Z"}'::jsonb),
('mcq', 6, 0, 'الحليب مخلوط غروي سائل (مستحلب)، تتصادم فيه جسيمات وسط الانتشار مع الجسيمات المنتشرة فتتحرك حركة براونية. أما الرمل وقطع الطين المترسبة والبرادة الجافة فليست جسيمات منتشرة في مخلوط غروي سائل. فالإجابة: جسيمات الدهن المنتشرة في الحليب.', '["","حبيبات الرمل لا تذوب ولا تبقى منتشرة بل تترسب، والحركة البراونية صفة جسيمات المخلوط الغروي السائل.","لا يوجد وسط انتشار سائل تتصادم جسيماته مع البرادة، فلا تحدث حركة براونية.","الماء الموحل مخلوط معلق تترسب جسيماته الكبيرة، والحركة البراونية تُلاحظ في المخاليط الغروية السائلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.321Z"}'::jsonb),
('mcq', 7, 3, 'الجسيمات المنتشرة في المخاليط الغروية السائلة تتحرك حركة عشوائية تُسمى الحركة البراونية، وأنها تنتج عن تصادم جسيمات الوسط مع الجسيمات المنتشرة. فالعبارة الصحيحة: تُلاحظ في المخاليط الغروية السائلة، وتنتج عن تصادم جسيمات الوسط بالجسيمات المنتشرة.', '["الحركة البراونية تخص جسيمات المخاليط الغروية السائلة، وتشتيت الضوء هو تأثير تندال لا سبب الحركة.","جذب الأرض يسبب ترسب جسيمات المعلق، أما الحركة البراونية فسببها التصادمات وتُلاحظ في الغرويات.","إضافة مادة متأينة تُتلف المخلوط الغروي فتترسب جسيماته، ولا تسبب الحركة البراونية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.321Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الحركة البراونية: حركة عشوائية غير منتظمة ومستمرة تتحركها الجسيمات المنتشرة في المخاليط الغروية السائلة. لاحظها أول مرة عالم النبات الإسكتلندي روبرت براون (1773–1858)، عندما لاحظ الحركة العشوائية لحبوب اللقاح المتناثرة في الماء، فسُمّيت باسمه.', '["حركة عشوائية غير منتظمة ومستمرة","لجسيمات المخاليط الغروية السائلة","روبرت براون","حبوب اللقاح المتناثرة في الماء"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الحركة (عشوائية غير منتظمة مستمرة)","marks":1},{"element":"تحديد أنها لجسيمات المخلوط الغروي السائل","marks":1},{"element":"اسم العالم","marks":1},{"element":"المادة التي لوحظت فيها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل مع اسم العالم والمادة."},{"level":"2–3 درجات","description":"تعريف ناقص صفةً أو مجالًا، أو إغفال اسم العالم أو المادة."},{"level":"درجة واحدة","description":"يذكر عنصرًا واحدًا صحيحًا فقط."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["وصف الحركة بأنها منتظمة.","نسبة الحركة إلى المحاليل.","الخلط بين براون وتندال."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-17T11:36:22.321Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تنتج الحركة البراونية عن تصادم جسيمات وسط الانتشار مع الجسيمات المنتشرة في المخلوط الغروي السائل؛ فجسيمات الوسط تصطدم بالجسيمات المنتشرة من اتجاهات مختلفة فتحركها حركة عشوائية مستمرة. وأثرها أن هذه التصادمات تمنع الجسيمات المنتشرة من الترسب في المخلوط، فتبقى منتشرة فيه.', '["السبب: تصادم جسيمات الوسط مع الجسيمات المنتشرة","التصادمات من اتجاهات مختلفة فتكون الحركة عشوائية","الأثر: منع الجسيمات المنتشرة من الترسب"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر السبب","marks":2},{"element":"ربط العشوائية بالتصادمات","marks":1},{"element":"ذكر الأثر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يذكر السبب كاملًا ويربطه بالعشوائية ويذكر الأثر."},{"level":"2–3 درجات","description":"يذكر السبب والأثر دون ربط، أو السبب كاملًا دون الأثر."},{"level":"درجة واحدة","description":"يذكر الأثر فقط أو السبب بصورة غامضة."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["القول إن الحركة البراونية تسبب الترسب.","نسبة الحركة إلى الجاذبية أو إلى تشتيت الضوء.","القول إن الجسيمات المنتشرة تتصادم مع جدار الإناء فقط."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-17T11:36:22.322Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فهما ظاهرتان مختلفتان وإن كانتا تحدثان في المخاليط الغروية. الحركة البراونية حركة عشوائية غير منتظمة ومستمرة لجسيمات المخلوط الغروي السائل، تنتج عن تصادم جسيمات وسط الانتشار مع الجسيمات المنتشرة. أما تأثير تندال فظاهرة ضوئية هي تشتيت الجسيمات المنتشرة للضوء، فيظهر مسار حزمة الضوء عند مرورها خلال المخلوط. فالأولى تتعلق بحركة الجسيمات، والثانية بتفاعل الجسيمات مع الضوء.', '["الحكم: العبارة غير صحيحة","الحركة البراونية: حركة عشوائية مستمرة للجسيمات","سببها: تصادم جسيمات الوسط بالجسيمات المنتشرة","تأثير تندال: تشتيت الجسيمات المنتشرة للضوء"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"ماهية الحركة البراونية","marks":1},{"element":"سبب الحركة البراونية","marks":1},{"element":"ماهية تأثير تندال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحكم بخطأ العبارة ويميز الظاهرتين ماهيةً وسببًا."},{"level":"2–3 درجات","description":"يحكم ويميز الظاهرتين مع نقص في أحد العناصر."},{"level":"درجة واحدة","description":"يحكم بخطأ العبارة دون تمييز واضح."},{"level":"صفر","description":"يؤيد العبارة أو لا يجيب."}]'::jsonb, '["عدّ تأثير تندال حركة للجسيمات.","نسبة الحركة البراونية إلى الضوء."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.322Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
