('mcq', 2, 'ما المقصود بوسط الانتشار في المخلوط الغروي؟', null, '["المادة الأقل توافرًا والمنتشرة في المخلوط","المادة الأكثر توافرًا في المخلوط الغروي","المادة التي تترسب عند ترك المخلوط","المادة التي تذوب كليًّا في المخلوط"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 15 — المخاليط الغروية'),
('mcq', 3, 'الزبد مخلوط غروي جسيماته المنتشرة سائلة ووسط انتشاره صلب. إلى أيّ أنواع المخاليط الغروية ينتمي؟', null, '["مستحلب صلب","رغوة صلبة","مستحلب","هباء جوي سائل"]'::jsonb, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 15 — الجدول 1-1 أنواع المخاليط الغروية'),
('mcq', 4, 'يُصنَّف الدخان في الهواء هباءً جويًّا صلبًا. ما الحالة الفيزيائية لكلٍّ من الجسيمات المنتشرة ووسط الانتشار فيه؟', null, '["جسيمات غازية منتشرة في وسط صلب","جسيمات سائلة منتشرة في وسط غازي","جسيمات صلبة منتشرة في وسط غازي","جسيمات صلبة منتشرة في وسط سائل"]'::jsonb, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 15 — الجدول 1-1 أنواع المخاليط الغروية'),
('mcq', 5, 'يبيّن الجدول الحالة الفيزيائية للجسيمات المنتشرة ولوسط الانتشار في أربعة مخاليط غروية رُمز لها بالرموز (س، ص، ع، ل). أيّها رغوة صلبة؟', '{"headers":["المخلوط","الجسيمات المنتشرة","وسط الانتشار"],"rows":[["س","سائل","غاز"],["ص","غاز","صلب"],["ع","صلب","سائل"],["ل","سائل","سائل"]]}'::jsonb, '["س","ص","ع","ل"]'::jsonb, 'تطبيق', 'تفسير بيانات', 'متوسط', 'الكتاب ص 15 — الجدول 1-1 أنواع المخاليط الغروية'),
('mcq', 6, 'أيّ الأزواج الآتية ينتمي مثالاها إلى النوع نفسه من المخاليط الغروية؟', null, '["الدخان، والضباب","الحليب، والزبد","الدم، والصابون الذي يطفو","الغيوم، ورذاذ مزيل العرق"]'::jsonb, 'تحليل', 'مقارنة وتصنيف', 'صعب', 'الكتاب ص 15 — الجدول 1-1 أنواع المخاليط الغروية'),
('mcq', 7, 'أيّ الأزواج الآتية (المثال — الجسيمات المنتشرة في وسط الانتشار) صحيح؟', null, '["المايونيز — سائل في صلب","الأحجار الكريمة الملونة — غاز في صلب","الجيلاتين — صلب في سائل","الجبن — سائل في سائل"]'::jsonb, 'فهم', 'تصنيف أمثلة', 'متوسط', 'الكتاب ص 15 — الجدول 1-1 أنواع المخاليط الغروية'),
('essay', 1, 'اذكر أربعة أنواع مختلفة من المخاليط الغروية، وحدّد لكلٍّ منها الحالة الفيزيائية للجسيمات المنتشرة ولوسط الانتشار، ومثالًا عليه.', null, null, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 15 و18 — الجدول 1-1؛ التقويم 1-1 س5'),
('essay', 2, 'صنّف كلًّا من المخاليط الغروية الآتية بتحديد حالة الجسيمات المنتشرة وحالة وسط الانتشار واسم النوع: الضباب، الجيلاتين، حلوى الخطمي، المايونيز، الجبن.', null, null, 'تطبيق', 'تصنيف', 'صعب', 'الكتاب ص 15 — الجدول 1-1 أنواع المخاليط الغروية'),
('essay', 3, 'كلٌّ من الدخان والضباب «هباء جوي»، وكلٌّ من الحليب والزبد «مستحلب»، لكن كل مثالين منهما يُصنَّفان في نوعين مختلفين. ما المعيار الذي يُعتمد عليه في تصنيف المخاليط الغروية؟ وكيف يفسر هذا المعيار الاختلاف في كل حالة؟', null, null, 'تحليل', 'تحليل معيار تصنيف', 'صعب', 'الكتاب ص 15 — الجدول 1-1 أنواع المخاليط الغروية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
