from (values
('mcq', 1, 3, 'الحليب مستحلب غروي؛ لأن الجسيمات المنتشرة السائلة تنتشر بين جسيمات وسط الانتشار السائل. فالإجابة: جسيماته المنتشرة سائلة ووسط انتشاره سائل.', '["الصلب المنتشر في سائل (صلب في سائل) مثاله الدم والجيلاتين لا الحليب.","السائل المنتشر في صلب هو المستحلب الصلب كالزبد والجبن.","الحليب لا يحتوي على جسيمات غازية منتشرة؛ فجسيماته المنتشرة قطيرات سائلة في وسط سائل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-17T11:36:22.322Z"}'::jsonb),
('mcq', 2, 1, 'وسط الانتشار هو المادة الأكثر توافرًا في المخلوط الغروي. فالإجابة: المادة الأكثر توافرًا في المخلوط الغروي.', '["هذه هي الجسيمات المنتشرة لا وسط الانتشار.","","جسيمات المخلوط الغروي لا تترسب، والترسب صفة المعلق.","المخلوط الغروي ليس محلولًا، فلا يوصف أحد مكوناته بأنه ذائب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.322Z"}'::jsonb),
('mcq', 3, 0, 'المخلوط الغروي الذي جسيماته المنتشرة سائلة ووسط انتشاره صلب يُسمى مستحلبًا صلبًا، ومن أمثلته الزبد والجبن. فالإجابة: مستحلب صلب.', '["","الرغوة الصلبة جسيماتها المنتشرة غازية في وسط صلب، كحلوى الخطمي.","المستحلب سائل في سائل كالحليب، أما الزبد فوسط انتشاره صلب.","الهباء الجوي السائل سائل منتشر في غاز كالضباب، والزبد وسطه صلب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.323Z"}'::jsonb),
('mcq', 4, 2, 'الهباء مخلوط غروي من جسيمات دقيقة صلبة أو سائلة منتشرة في الهواء أو غاز آخر، والهباء الجوي الصلب (كالدخان والغبار في الهواء) جسيماته المنتشرة صلبة ووسط انتشاره غاز. فالإجابة: جسيمات صلبة منتشرة في وسط غازي.', '["هذا عكس الصحيح، وهو يصف الرغوة الصلبة كحلوى الخطمي.","هذا يصف الهباء الجوي السائل كالضباب والغيوم لا الدخان.","","هذا يصف نوع (صلب في سائل) كالدم والجيلاتين، ووسط الدخان غازي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.323Z"}'::jsonb),
('mcq', 5, 1, 'الرغوة الصلبة جسيماتها المنتشرة غازية ووسط انتشارها صلب، وهذا ما يحققه المخلوط (ص) وحده في الجدول. فالإجابة: ص.', '["المخلوط (س) سائل منتشر في غاز، فهو هباء جوي سائل.","","المخلوط (ع) صلب منتشر في سائل، فهو من نوع (صلب في سائل).","المخلوط (ل) سائل منتشر في سائل، فهو مستحلب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.323Z"}'::jsonb),
('mcq', 6, 3, 'الغيوم ورذاذ مزيل العرق كلاهما قطيرات سائلة منتشرة في الهواء، فهما من نوع الهباء الجوي السائل. أما بقية الأزواج فيختلف فيها حال الجسيمات المنتشرة أو وسط الانتشار. فالإجابة: الغيوم، ورذاذ مزيل العرق.', '["الدخان هباء جوي صلب (صلب في غاز)، والضباب هباء جوي سائل (سائل في غاز).","الحليب مستحلب (سائل في سائل)، والزبد مستحلب صلب (سائل في صلب).","الدم من نوع (صلب في سائل)، والصابون الذي يطفو رغوة صلبة (غاز في صلب).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.323Z"}'::jsonb),
('mcq', 7, 2, 'الدم والجيلاتين من نوع (صلب في سائل): جسيمات منتشرة صلبة في وسط انتشار سائل. فالزوج الصحيح: الجيلاتين — صلب في سائل.', '["المايونيز مستحلب (سائل في سائل) مثل الحليب، لا مستحلب صلب.","الأحجار الكريمة الملونة من نوع (صلب في صلب)، والغاز في الصلب رغوة صلبة.","","الجبن مستحلب صلب (سائل في صلب)، والسائل في السائل مستحلب كالحليب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.324Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من أنواع المخاليط الغروية: (1) المستحلب: سائل منتشر في سائل، مثل الحليب والمايونيز. (2) المستحلب الصلب: سائل منتشر في صلب، مثل الزبد والجبن. (3) الرغوة الصلبة: غاز منتشر في صلب، مثل الصابون الذي يطفو وحلوى الخطمي. (4) الهباء الجوي الصلب: صلب منتشر في غاز، مثل الدخان والغبار في الهواء. ومن الأنواع الأخرى: الهباء الجوي السائل (سائل في غاز) كالغيوم والضباب، وصلب في سائل كالدم والجيلاتين، وصلب في صلب كالأحجار الكريمة الملونة.', '["اسم النوع","حالة الجسيمات المنتشرة","حالة وسط الانتشار","مثال صحيح — لكل من الأنواع الأربعة"]'::jsonb, '[]'::jsonb, '[{"element":"النوع الأول: الاسم والحالتان والمثال","marks":2},{"element":"النوع الثاني: الاسم والحالتان والمثال","marks":2},{"element":"النوع الثالث: الاسم والحالتان والمثال","marks":2},{"element":"النوع الرابع: الاسم والحالتان والمثال","marks":2}]'::jsonb, '[{"level":"8 درجات","description":"أربعة أنواع صحيحة لكل منها الحالتان ومثال صحيح."},{"level":"5–7 درجات","description":"ثلاثة أنواع كاملة، أو أربعة أنواع مع نقص في الحالة أو المثال."},{"level":"2–4 درجات","description":"نوع أو نوعان كاملان، أو أسماء دون تحديد الحالات."},{"level":"درجة واحدة","description":"اسم نوع واحد صحيح دون تفصيل."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["عكس حالتي الجسيمات المنتشرة ووسط الانتشار.","الخلط بين المستحلب والمستحلب الصلب.","عدّ الضباب هباءً جويًّا صلبًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.324Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الضباب: سائل في غاز — هباء جوي سائل. الجيلاتين: صلب في سائل — (صلب في سائل). حلوى الخطمي: غاز في صلب — رغوة صلبة. المايونيز: سائل في سائل — مستحلب. الجبن: سائل في صلب — مستحلب صلب.', '["الضباب: سائل في غاز، هباء جوي سائل","الجيلاتين: صلب في سائل","حلوى الخطمي: غاز في صلب، رغوة صلبة","المايونيز: سائل في سائل، مستحلب","الجبن: سائل في صلب، مستحلب صلب"]'::jsonb, '[]'::jsonb, '[{"element":"الضباب","marks":1},{"element":"الجيلاتين","marks":1},{"element":"حلوى الخطمي","marks":1},{"element":"المايونيز","marks":1},{"element":"الجبن","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف الأمثلة الخمسة صحيحًا بالحالتين واسم النوع."},{"level":"3–4 درجات","description":"تصنيف ثلاثة أو أربعة أمثلة صحيحًا."},{"level":"1–2 درجة","description":"تصنيف مثال أو مثالين صحيحًا."},{"level":"صفر","description":"لا تصنيف صحيح."}]'::jsonb, '["تصنيف الجبن مستحلبًا لا مستحلبًا صلبًا.","تصنيف حلوى الخطمي مستحلبًا صلبًا.","عدّ المايونيز صلبًا في سائل."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.324Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تُصنّف المخاليط الغروية تبعًا للحالة الفيزيائية لكلٍّ من الجسيمات المنتشرة ووسط الانتشار. الدخان والضباب وسط انتشارهما غاز (الهواء)، لكن الجسيمات المنتشرة في الدخان صلبة فهو هباء جوي صلب، وفي الضباب سائلة فهو هباء جوي سائل. والحليب والزبد جسيماتهما المنتشرة سائلة، لكن وسط انتشار الحليب سائل فهو مستحلب، ووسط انتشار الزبد صلب فهو مستحلب صلب.', '["المعيار: الحالة الفيزيائية للجسيمات المنتشرة ولوسط الانتشار","الدخان والضباب: الوسط نفسه (غاز) والجسيمات تختلف (صلب/سائل)","الحليب والزبد: الجسيمات نفسها (سائل) والوسط يختلف (سائل/صلب)"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر المعيار","marks":2},{"element":"تفسير اختلاف الدخان والضباب","marks":1},{"element":"تفسير اختلاف الحليب والزبد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يذكر المعيار كاملًا ويفسر الحالتين بتحديد العنصر المختلف في كل منهما."},{"level":"2–3 درجات","description":"يذكر المعيار ويفسر حالة واحدة، أو يفسر الحالتين دون ذكر المعيار صراحة."},{"level":"درجة واحدة","description":"يذكر جزءًا من المعيار فقط."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["ذكر حالة الجسيمات المنتشرة وحدها معيارًا.","القول إن الاختلاف في حجم الجسيمات.","عكس وسطي الحليب والزبد."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.324Z"}'::jsonb)
