('mcq', 3, 'تُسمّى المادة المتأينة التي يؤدي تحريكها في مخلوط غروي إلى ترسب جسيماته أيضًا مادة:', null, '["غير ذائبة","إلكتروليتية","غير قطبية","ممتزجة"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 15 — المخاليط الغروية'),
('mcq', 4, 'ما القاسم المشترك بين أثر إضافة مادة متأينة إلى مخلوط غروي وأثر تسخينه؟', null, '["كلاهما يتغلب على أثر الطبقات الكهروستاتيكية فتترسب الجسيمات","كلاهما يزيد الحركة البراونية فيُبقي الجسيمات منتشرة","كلاهما يحوّل المخلوط الغروي إلى محلول متجانس","كلاهما يزيد تأثير تندال دون أن تترسب الجسيمات"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 15 — المخاليط الغروية'),
('mcq', 5, 'أيّ الإجراءات الآتية يؤدي إلى ترسب جسيمات مخلوط غروي؟', null, '["تحريك مادة متأينة فيه","تركه فترة دون تحريك","ترشيحه بورقة الترشيح","تمرير حزمة ضوء خلاله"]'::jsonb, 'تطبيق', 'تطبيق في موقف جديد', 'سهل', 'الكتاب ص 15–16 — المخاليط الغروية؛ تأثير تندال'),
('mcq', 6, 'الطبقات الكهروستاتيكية حول الجسيمات المنتشرة سبب تنافرها. فماذا يدل ترسب الجسيمات بعد تحريك مادة متأينة في المخلوط على أثر هذه المادة؟', null, '["أنها تزيد سُمك الطبقات الكهروستاتيكية فيقوى التنافر بين الجسيمات","أنها تزيد سرعة الحركة البراونية فتتباعد الجسيمات عن بعضها","أنها تتدخل في الطبقات الكهروستاتيكية فتتجمع الجسيمات عند تصادمها","أنها تُذيب الجسيمات المنتشرة فتختفي من المخلوط"]'::jsonb, 'تحليل', 'استدلال', 'صعب', 'الكتاب ص 15 — المخاليط الغروية'),
('mcq', 7, 'مخلوط غروي ثابت لا تترسب جسيماته عند تركه أيامًا، لكنها تترسب عند تسخينه. ما الذي تغيّر في الجسيمات المتصادمة عند التسخين؟', null, '["نقصت طاقتها الحركية فتوقفت الحركة البراونية","ازدادت الشحنات على أسطحها فقوي تنافرها","تحوّلت إلى أيونات ذائبة في وسط الانتشار","ازدادت طاقتها الحركية فتغلبت على القوى الكهروستاتيكية"]'::jsonb, 'تطبيق', 'تفسير ملاحظة', 'صعب', 'الكتاب ص 15 — المخاليط الغروية'),
('essay', 1, 'فسّر: يتلف المخلوط الغروي وتترسب جسيماته عند تحريك مادة متأينة (إلكتروليتية) فيه.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 15 — المخاليط الغروية'),
('essay', 2, 'فسّر: تسخين المخلوط الغروي يُتلفه ويُرسب جسيماته، مع أن الجسيمات تبقى منتشرة فيه عند تركه في درجة حرارة الغرفة.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 15 — المخاليط الغروية'),
