('mcq', 1, 2, 'عند تحريك مادة متأينة (إلكتروليتية) في مخلوط غروي تتجمع الجسيمات المنتشرة معًا، ويتلف المخلوط الغروي، وتترسب جسيماته. فالإجابة: تتجمع الجسيمات المنتشرة وتترسب فيتلف المخلوط.', '["المادة المتأينة لا تُذيب الجسيمات المنتشرة؛ بل تتدخل في الطبقات الكهروستاتيكية فتتجمع الجسيمات.","المادة المتأينة تُتلف المخلوط الغروي لا أنها تزيد ثباته.","","المادة المتأينة تؤثر في الطبقات الكهروستاتيكية، فيتغير المخلوط وتترسب جسيماته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.325Z"}'::jsonb),
('mcq', 2, 3, 'التسخين يُتلف المخلوط الغروي؛ لأن الحرارة تعطي الجسيمات المتصادمة طاقة حركية كافية للتغلب على القوى الكهروستاتيكية، ثم ترسبها في المخلوط. فالإجابة: لأن الحرارة تعطي الجسيمات المتصادمة طاقة حركية كافية للتغلب على القوى الكهروستاتيكية.', '["لا يُفسَّر التلف بتبخر الوسط، بل بتغلب الجسيمات المتصادمة على القوى الكهروستاتيكية.","زيادة التنافر تزيد ثبات المخلوط وتمنع الترسب، فلا تفسر التلف.","لو ذابت الجسيمات لتكوّن محلول ولم تترسب؛ والملاحظ ترسبها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.325Z"}'::jsonb),
('mcq', 3, 1, 'عند تحريك مادة متأينة (إلكتروليتية) في مخلوط غروي تتجمع جسيماته؛ فالمادة المتأينة تُسمى أيضًا مادة إلكتروليتية.', '["المادة غير الذائبة هي التي لا تذوب في المذيب، وليست مرادفًا للمادة المتأينة.","","المادة المتأينة تُنتج أيونات مشحونة، فلا توصف بأنها غير قطبية.","الممتزجة وصف لسائلين يذوب أحدهما في الآخر بأي نسبة، لا للمادة المتأينة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.325Z"}'::jsonb),
('mcq', 4, 0, 'إذا تدخلنا في الطبقات الكهروستاتيكية فسوف تترسب الجسيمات المنتشرة: فالمادة المتأينة تتدخل فيها فتتجمع الجسيمات، والتسخين يعطي الجسيمات طاقة للتغلب على القوى الكهروستاتيكية. فالقاسم المشترك: كلاهما يتغلب على أثر الطبقات الكهروستاتيكية فتترسب الجسيمات.', '["","الإجراءان يُتلفان المخلوط ويُرسبان جسيماته، فلا يُبقيانها منتشرة.","النتيجة ترسب الجسيمات وتلف المخلوط، لا تكوّن محلول متجانس.","تترسب الجسيمات في الحالتين، ولا يربطهما بزيادة تأثير تندال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.325Z"}'::jsonb),
('mcq', 5, 0, 'المخلوط الغروي لا يُفصل بالترويق أو الترشيح، لكن تحريك مادة متأينة فيه يتدخل في الطبقات الكهروستاتيكية فتتجمع الجسيمات وتترسب. فالإجابة: تحريك مادة متأينة فيه.', '["","جسيمات المخلوط الغروي لا تترسب بالترويق؛ فالترك دون تحريك يفصل المعلق فقط.","لا يمكن فصل مكونات المخلوط الغروي بالترشيح كما في الحليب.","تمرير الضوء يُظهر تأثير تندال فقط ولا يُرسب الجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.325Z"}'::jsonb),
('mcq', 6, 2, 'ما دام التنافر بين الطبقات الكهروستاتيكية هو ما يمنع الترسب، فإن ترسب الجسيمات يعني أن المادة المتأينة تدخلت في هذه الطبقات، فلم تعد تمنع الجسيمات من التجمع عند تصادمها، فتجمعت وترسبت. فالإجابة: أنها تتدخل في الطبقات الكهروستاتيكية فتتجمع الجسيمات عند تصادمها.', '["قوة التنافر تمنع الترسب، فلا يمكن أن تفسر الترسب الملاحظ.","تباعد الجسيمات يُبقيها منتشرة لا يُرسبها، فالترسب مرتبط بالتدخل في الطبقات الكهروستاتيكية.","","الذوبان لا يُنتج راسبًا؛ والملاحظ ترسب الجسيمات لا اختفاؤها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.326Z"}'::jsonb),
('mcq', 7, 3, 'قبل التسخين لا تملك الجسيمات المتصادمة طاقة كافية للتغلب على القوى الكهروستاتيكية فتبقى منتشرة، وبالتسخين تعطيها الحرارة طاقة حركية كافية للتغلب على هذه القوى فتترسب. فالإجابة: ازدادت طاقتها الحركية فتغلبت على القوى الكهروستاتيكية.', '["التسخين يزيد الطاقة الحركية لا ينقصها، فالترسب مرتبط بطاقة كافية للتغلب على القوى.","زيادة التنافر تُبقي الجسيمات منتشرة، فلا تفسر ترسبها عند التسخين.","التحول إلى أيونات ذائبة لا يُكوّن راسبًا، والملاحظ ترسب الجسيمات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.326Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تبقى الجسيمات المنتشرة في المخلوط الغروي دون ترسب لأن المجموعات المشحونة على سطحها تجذب جسيمات وسط الانتشار فتتكون حولها طبقات كهروستاتيكية تتنافر عند تصادم الجسيمات. وعند تحريك مادة متأينة في المخلوط فإنها تتدخل في هذه الطبقات الكهروستاتيكية، فلا يعود التنافر يمنع الجسيمات من الاقتراب، فتتجمع الجسيمات المنتشرة معًا عند تصادمها وتترسب، فيتلف المخلوط الغروي.', '["ثبات الغروي سببه الطبقات الكهروستاتيكية المتنافرة","المادة المتأينة تتدخل في الطبقات الكهروستاتيكية","تجمع الجسيمات المنتشرة معًا","ترسب الجسيمات وتلف المخلوط"]'::jsonb, '[]'::jsonb, '[{"element":"سبب ثبات المخلوط الغروي","marks":1},{"element":"تدخل المادة المتأينة في الطبقات","marks":1},{"element":"تجمع الجسيمات","marks":1},{"element":"الترسب والتلف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يفسر الثبات ثم أثر المادة المتأينة وصولًا إلى التجمع والترسب."},{"level":"2–3 درجات","description":"يذكر تدخل المادة المتأينة والترسب دون تفسير الثبات أو التجمع."},{"level":"درجة واحدة","description":"يذكر الترسب فقط دون تفسير."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["القول إن المادة المتأينة تُذيب الجسيمات المنتشرة.","القول إن المادة المتأينة تزيد التنافر.","إغفال دور الطبقات الكهروستاتيكية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.326Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في درجة حرارة الغرفة تتصادم الجسيمات المنتشرة، لكن الطبقات الكهروستاتيكية حولها تتنافر، وطاقة الجسيمات لا تكفي للتغلب على هذه القوى الكهروستاتيكية، فتبقى منفصلة منتشرة. وعند التسخين تعطي الحرارة الجسيمات المتصادمة طاقة حركية كافية للتغلب على القوى الكهروستاتيكية، فتقترب وتتجمع، ثم تترسب في المخلوط، فيتلف المخلوط الغروي.', '["في درجة الغرفة: الطبقات المتنافرة تمنع التجمع","الطاقة لا تكفي للتغلب على القوى الكهروستاتيكية","التسخين يعطي طاقة حركية كافية","التغلب على القوى الكهروستاتيكية فتترسب الجسيمات"]'::jsonb, '[]'::jsonb, '[{"element":"حال المخلوط في درجة حرارة الغرفة","marks":1},{"element":"عدم كفاية الطاقة قبل التسخين","marks":1},{"element":"زيادة الطاقة الحركية بالتسخين","marks":1},{"element":"التغلب على القوى والترسب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يقارن الحالتين ويفسر الترسب بالطاقة الحركية الكافية للتغلب على القوى الكهروستاتيكية."},{"level":"2–3 درجات","description":"يفسر أثر التسخين دون مقارنة بحال المخلوط قبله، أو بمقارنة ناقصة."},{"level":"درجة واحدة","description":"يذكر أن الحرارة تزيد حركة الجسيمات دون ربط بالقوى الكهروستاتيكية."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["تفسير التلف بتبخر وسط الانتشار وحده.","القول إن الحرارة تزيد الشحنات فيزداد التنافر.","القول إن الحرارة تُذيب الجسيمات."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.326Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التنبؤ: في العينتين ستتجمع الجسيمات المنتشرة وتترسب، ويتلف المخلوط الغروي. المقارنة: النتيجة واحدة (ترسب الجسيمات وتلف المخلوط). أما كيفية التأثير فتختلف: المادة المتأينة تتدخل في الطبقات الكهروستاتيكية نفسها فتتجمع الجسيمات المنتشرة معًا؛ أما التسخين فلا يغير الطبقات مباشرة، بل يعطي الجسيمات المتصادمة طاقة حركية كافية للتغلب على القوى الكهروستاتيكية بينها، فتترسب.', '["التنبؤ بالترسب في العينتين","النتيجة واحدة: تلف المخلوط","المادة المتأينة تتدخل في الطبقات الكهروستاتيكية","التسخين يزيد الطاقة الحركية للتغلب على القوى الكهروستاتيكية"]'::jsonb, '[]'::jsonb, '[{"element":"التنبؤ في العينة الأولى","marks":1},{"element":"التنبؤ في العينة الثانية","marks":1},{"element":"المقارنة في النتيجة","marks":1},{"element":"آلية المادة المتأينة","marks":1},{"element":"آلية التسخين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تنبؤ صحيح للعينتين ومقارنة كاملة في النتيجة والآلية."},{"level":"3–4 درجات","description":"تنبؤ صحيح مع مقارنة ناقصة في إحدى الآليتين."},{"level":"1–2 درجة","description":"تنبؤ صحيح دون مقارنة، أو تنبؤ لعينة واحدة."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["التنبؤ بأن التسخين يحول المخلوط إلى محلول.","عدّ الآليتين متطابقتين تمامًا.","القول إن المادة المتأينة تزيد ثبات المخلوط."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.326Z"}'::jsonb)
