from (values
('mcq', 1, 1, 'المادتان السائلتان اللتان تذوب إحداهما في الأخرى بأي نسبة تُسميان المواد القابلة للامتزاج. فالإجابة: مواد قابلة للامتزاج.', '["السوائل غير الممتزجة تمتزج فترة قصيرة ثم تنفصل، فلا تذوب إحداها في الأخرى.","","المادة غير الذائبة لا تذوب في المذيب، وهذا عكس المطلوب.","المخلوط الغروي غير متجانس جسيماته منتشرة لا ذائبة، والسائلان القابلان للامتزاج يكوّنان محلولًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.327Z"}'::jsonb),
('mcq', 2, 0, 'السوائل غير الممتزجة هي السوائل التي تمتزج معًا فترة قصيرة عند خلطها ثم تنفصل بعدها. فالإجابة: سوائل غير ممتزجة.', '["","السوائل الممتزجة يذوب أحدها في الآخر بأي نسبة ولا تنفصل.","المحلول متجانس ولا تنفصل مكوناته بعد الخلط.","المادة الذائبة تذوب في المذيب، والسوائل الموصوفة لا يذوب أحدها في الآخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.327Z"}'::jsonb),
('mcq', 3, 3, 'الزيت لا يمتزج مع الخل؛ أي أن الزيت لا يذوب في الخل، فإذا خُلطا امتزجا فترة قصيرة ثم انفصلا. فالإجابة: الزيت والخل.', '["هما مكونا مانع التجمد، وهما سائلان قابلان للامتزاج يكوّنان محلولًا سائلًا.","الخل يمتزج بالماء ولا ينفصل عنه بعد الخلط.","عصير الليمون يمتزج بالماء مكونًا شرابًا متجانسًا لا ينفصل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.328Z"}'::jsonb),
('mcq', 4, 2, 'مانع التجمد محلول سائل: المذيب الماء والمذاب الإيثيلين جلايكول (سائل)، وهو مثال على المواد القابلة للامتزاج. فالإجابة: أنهما قابلان للامتزاج؛ يذوب أحدهما في الآخر.', '["لو انفصلا لما تكوّن محلول متجانس كمانع التجمد.","الإيثيلين جلايكول مذاب في الماء، فهو ذائب لا غير ذائب.","","المستحلب مخلوط غروي غير متجانس، أما مانع التجمد فمحلول متجانس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.328Z"}'::jsonb),
('mcq', 5, 3, 'امتزاج السائلين فترة قصيرة ثم انفصالهما إلى طبقتين هو وصف السوائل غير الممتزجة. فالإجابة: السائلان غير ممتزجين.', '["لو كانا ممتزجين لبقيا محلولًا متجانسًا ولم ينفصلا إلى طبقتين.","انفصال السائلين يعني أن أحدهما لا يذوب في الآخر، فلا يكون مذيبًا له.","المخلوط الغروي لا تنفصل مكوناته عند تركه، والملاحظ انفصال طبقتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.328Z"}'::jsonb),
('mcq', 6, 1, 'الزيت لا يمتزج مع الخل؛ أي أن الزيت لا يذوب في الخل. فالإجابة: أن الزيت لا يذوب في الخل.', '["الذوبان بأي نسبة صفة السوائل القابلة للامتزاج لا الزيت والخل.","","الرج يمزجهما فترة قصيرة ثم ينفصلان، فلا يتكون محلول.","عدم الامتزاج يتعلق بعدم الذوبان، ولا يدل على تفاعل كيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.329Z"}'::jsonb),
('mcq', 7, 0, 'السائلان غير الممتزجين لا يذوب أحدهما في الآخر، فينفصلان إلى طبقتين يمكن تمييز كل منهما، والمخلوط الذي يمكن تمييز مكوناته مخلوط غير متجانس. فالإجابة: مخلوط غير متجانس يمكن تمييز مكوناته.', '["","المحلول لا يمكن فيه التمييز بين مكوناته، أما هنا فالطبقتان مميزتان.","لم يحدث تفاعل كيميائي، فكل سائل يحتفظ بخصائصه في المخلوط.","المكونان سائلان لا غازان، ولم يتكون محلول أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.329Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السوائل الممتزجة (القابلة للامتزاج): مادتان سائلتان تذوب إحداهما في الأخرى بأي نسبة، ومثالها مانع التجمد (الإيثيلين جلايكول في الماء). السوائل غير الممتزجة: سوائل تمتزج معًا فترة قصيرة عند خلطها ثم تنفصل بعدها، أي لا يذوب أحدها في الآخر، ومثالها الزيت والخل. ويقبل أي مثال صحيح.', '["تعريف السوائل الممتزجة","مثال: مانع التجمد (الإيثيلين جلايكول والماء)","تعريف السوائل غير الممتزجة","مثال: الزيت والخل"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الممتزجة","marks":1},{"element":"مثال الممتزجة","marks":1},{"element":"تعريف غير الممتزجة","marks":1},{"element":"مثال غير الممتزجة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان صحيحان ومثالان صحيحان."},{"level":"2–3 درجات","description":"تعريفان دون أمثلة، أو تعريف ومثال لنوع واحد مع جزء من الآخر."},{"level":"درجة واحدة","description":"عنصر واحد صحيح."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["عدّ الزيت والخل ممتزجين لأنهما يمتزجان عند الرج.","إغفال عبارة «بأي نسبة» في تعريف الممتزجة.","ذكر مثال لمادة صلبة ذائبة في سائل (كالسكر في الماء) بدل سائلين."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.329Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الاختبار: يُوضع السائلان (أ) و(ب) معًا في أنبوب اختبار، ويُرجّ الأنبوب، ثم يُترك فترة دون تحريك ويُلاحظ. إذا انفصلا بعد مدة إلى طبقتين فهما غير ممتزجين، وإذا بقيا سائلًا واحدًا متجانسًا لا تنفصل مكوناته فهما ممتزجان. التنبؤ: الزوج (1) الزيت والخل يمتزجان فترة قصيرة ثم ينفصلان إلى طبقتين؛ لأن الزيت لا يذوب في الخل (غير ممتزجين). الزوج (2) الإيثيلين جلايكول والماء يبقيان محلولًا متجانسًا (مانع التجمد)؛ لأنهما قابلان للامتزاج يذوب أحدهما في الآخر.', '["خلط السائلين ورجّهما","ترك المخلوط فترة دون تحريك","معيار الحكم: انفصال طبقتين أو بقاء محلول متجانس","تنبؤ وتبرير للزيت والخل","تنبؤ وتبرير للإيثيلين جلايكول والماء"]'::jsonb, '[]'::jsonb, '[{"element":"خطوات الاختبار","marks":1},{"element":"الترك والملاحظة","marks":1},{"element":"معيار الحكم","marks":1},{"element":"الزوج (1)","marks":1},{"element":"الزوج (2)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"اختبار واضح بمعيار حكم صحيح، وتنبؤان مبرران."},{"level":"3–4 درجات","description":"اختبار صحيح مع تنبؤ مبرر لزوج واحد، أو تنبؤان دون معيار واضح."},{"level":"1–2 درجة","description":"تنبؤ صحيح دون اختبار، أو اختبار دون معيار ولا تنبؤ."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الحكم مباشرة بعد الرج دون ترك المخلوط، فيُعد الزيت والخل ممتزجين خطأً.","التنبؤ بانفصال الإيثيلين جلايكول عن الماء.","عدم ذكر معيار الحكم."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.329Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المحلول مخلوط متجانس لا يمكن التمييز فيه بين المذاب والمذيب. في مانع التجمد يذوب الإيثيلين جلايكول (المذاب) في الماء (المذيب) لأنهما سائلان قابلان للامتزاج، فيتكون مخلوط متجانس لا تنفصل مكوناته، فهو محلول سائل. أما الزيت والخل فسائلان غير ممتزجين؛ الزيت لا يذوب في الخل، فيمتزجان فترة قصيرة ثم ينفصلان إلى طبقتين يمكن تمييزهما، فالمخلوط غير متجانس وليس محلولًا.', '["صفة المحلول: متجانس لا يُميَّز فيه المذاب من المذيب","مانع التجمد: سائلان ممتزجان فيتكون محلول","الزيت والخل: غير ممتزجين، الزيت لا يذوب في الخل","انفصالهما يجعل المخلوط غير متجانس"]'::jsonb, '[]'::jsonb, '[{"element":"صفة المحلول","marks":1},{"element":"تفسير مانع التجمد","marks":1},{"element":"تفسير الزيت والخل","marks":1},{"element":"الاستنتاج: غير متجانس وليس محلولًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يذكر صفة المحلول ويفسر الحالتين ويستنتج بوضوح."},{"level":"2–3 درجات","description":"يفسر الحالتين دون ربطهما بصفة المحلول، أو يفسر حالة واحدة مع صفة المحلول."},{"level":"درجة واحدة","description":"يذكر أن الزيت والخل غير ممتزجين دون تفسير."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["القول إن الزيت والخل محلول لأنهما سائلان.","عدّ مانع التجمد مخلوطًا غرويًّا.","إغفال أن المحلول لا يمكن تمييز مكوناته."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.329Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
