('mcq', 4, 'حرّك طالب ملعقة رمل في كأس ماء ثم تركها، فاستقر الرمل في القاع وبقيت حبيباته مميزة. ماذا يستنتج؟', null, '["الرمل مادة ذائبة في الماء","الرمل مادة غير ذائبة في الماء","الرمل هو المذيب والماء هو المذاب","تكوّن محلول متجانس من الرمل والماء"]'::jsonb, 'تطبيق', 'تفسير ملاحظة', 'متوسط', 'الكتاب ص 16–17 — تكوين المحاليل'),
('mcq', 5, 'يعرض الجدول بعض المحاليل المائية. ماذا تستنتج عن المواد الثلاث المذكورة في عمود المذاب بالنسبة إلى الماء؟', '{"headers":["المحلول","المذيب","المذاب"],"rows":[["ماء غازي","الماء (سائل)","ثاني أكسيد الكربون (غاز)"],["مانع التجمد","الماء (سائل)","الإيثيلين جلايكول (سائل)"],["ماء البحر","الماء (سائل)","كلوريد الصوديوم (صلب)"]]}'::jsonb, '["كلها مواد غير ذائبة في الماء","كلها مذيبات تذيب الماء","كلها مواد ذائبة في الماء مع اختلاف حالاتها الفيزيائية","كلها مواد صلبة ذائبة في الماء"]'::jsonb, 'تطبيق', 'تفسير بيانات', 'متوسط', 'الكتاب ص 17 — الجدول 1-2 أنواع المحاليل'),
('mcq', 6, 'أيّ العبارات الآتية أدقّ في وصف المادة غير الذائبة؟', null, '["مادة لا تذوب في مذيب معين، كالرمل في الماء","مادة لا تذوب في أي مذيب على الإطلاق","مادة تذوب في المذيب ثم تترسب فورًا في القاع","مادة تذوب في المذيب فلا يمكن تمييزها"]'::jsonb, 'تحليل', 'تمييز عبارة دقيقة', 'صعب', 'الكتاب ص 16–17 — تكوين المحاليل'),
('mcq', 7, 'ما الذي ينتج عند إضافة مادة ذائبة إلى مذيب، وما الذي ينتج عند إضافة مادة غير ذائبة إليه؟', null, '["الأولى: مخلوط غير متجانس تُميَّز مكوناته — الثانية: محلول متجانس لا تُميَّز مكوناته","الأولى: محلول متجانس لا تُميَّز مكوناته — الثانية: مخلوط غير متجانس تُميَّز مكوناته","الأولى: محلول متجانس لا تُميَّز مكوناته — الثانية: محلول متجانس أيضًا","الأولى: مادة نقية جديدة — الثانية: مخلوط غير متجانس تُميَّز مكوناته"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 14 و16–17 — المخاليط؛ تكوين المحاليل'),
('essay', 1, 'فرّق بين المادة الذائبة والمادة غير الذائبة، مع ذكر مثال على كلٍّ منهما.', null, null, 'فهم', 'تمييز', 'سهل', 'الكتاب ص 16–17 — تكوين المحاليل'),
('essay', 2, 'أُجريت ثلاث تجارب: (1) أُضيف سكر إلى ماء وحُرّك، (2) أُضيف رمل إلى ماء وحُرّك ثم تُرك، (3) أُضيف زيت إلى خل ورُجّ ثم تُرك. صِف ما يُتوقع ملاحظته في كل تجربة، وصنّف المادة المضافة (ذائبة أم غير ذائبة) في المذيب المستخدم، مع التبرير.', null, null, 'تطبيق', 'تنبؤ وتصنيف', 'متوسط', 'الكتاب ص 16–17 — تكوين المحاليل'),
('essay', 3, 'قال طالب بعد إذابة السكر في الماء: «اختفى السكر، إذن لم يعد موجودًا في الكأس، أما الرمل فبقي لأنه مادة غير ذائبة». قوّم عبارة الطالب، موضحًا ما حدث للسكر فعلًا، ودليلًا من الحياة اليومية على بقائه، والفرق بينه وبين الرمل.', null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 16–17 — تكوين المحاليل')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
