from (values
('mcq', 1, 3, 'المادة الذائبة هي المادة التي تذوب في المذيب، كالسكر الذي يذوب في الماء. فالإجابة: المادة التي تذوب في المذيب.', '["الوسط الذي يذيب المادة هو المذيب لا المادة الذائبة.","هذا تعريف المادة غير الذائبة.","هذا تعريف وسط الانتشار في المخلوط الغروي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.330Z"}'::jsonb),
('mcq', 2, 2, 'الرمل لا يذوب في الماء، فهو مثال على المادة غير الذائبة، بينما السكر وكلوريد الصوديوم والإيثيلين جلايكول تذوب في الماء. فالإجابة: الرمل الناعم.', '["السكر يذوب في الماء، وهو مثال على المادة الذائبة.","كلوريد الصوديوم مذاب في ماء البحر، فهو ذائب في الماء.","","الإيثيلين جلايكول مذاب في الماء في مانع التجمد، فهو ذائب في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.330Z"}'::jsonb),
('mcq', 3, 0, 'ذوبان السكر في الماء لعمل شراب محلّى كالشاي مثالًا على المادة الذائبة؛ فالسكر يذوب في المذيب (الماء). فالإجابة: مادة ذائبة.', '["","المذيب هو الوسط الذي يذيب، وهو هنا الماء لا السكر.","السكر يذوب في الماء ولا يبقى مميزًا، فليس غير ذائب.","وسط الانتشار مصطلح للمخلوط الغروي، والشاي المحلّى محلول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.330Z"}'::jsonb),
('mcq', 4, 1, 'بقاء حبيبات الرمل مميزة واستقرارها في القاع يعني أنها لم تذب في الماء؛ والرمل مثال على المادة غير الذائبة في الماء. فالإجابة: الرمل مادة غير ذائبة في الماء.', '["لو ذاب الرمل لما بقيت حبيباته مميزة ولما استقرت في القاع.","","لم يذب أي منهما في الآخر، فلا يوجد مذيب ومذاب هنا.","المحلول لا يمكن فيه تمييز مكوناته، أما الرمل هنا فمميز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.330Z"}'::jsonb),
('mcq', 5, 2, 'في المحاليل الثلاثة المذيب هو الماء، والمذاب ثاني أكسيد الكربون (غاز) والإيثيلين جلايكول (سائل) وكلوريد الصوديوم (صلب)؛ فكلها تذوب في الماء، أي مواد ذائبة، مع اختلاف حالاتها. فالإجابة: كلها مواد ذائبة في الماء مع اختلاف حالاتها الفيزيائية.', '["هذه المواد مذابة في الماء في محاليل، فهي ذائبة لا غير ذائبة.","المذيب في المحاليل الثلاثة هو الماء، وهذه المواد هي المذابة.","","ثاني أكسيد الكربون غاز والإيثيلين جلايكول سائل؛ فليست كلها صلبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.330Z"}'::jsonb),
('mcq', 6, 0, 'المادة غير الذائبة هي المادة التي لا تذوب في المذيب، ومثالها الرمل الذي لا يذوب في الماء؛ فالوصف مرتبط بمذيب معين. كما أن الزيت لا يذوب في الخل. فالإجابة: مادة لا تذوب في مذيب معين، كالرمل في الماء.', '["","تُعرَّف بالنسبة إلى «المذيب»، فالحكم يخص مذيبًا معينًا لا كل المذيبات.","المادة غير الذائبة لا تذوب أصلًا، فلا يصح وصفها بأنها تذوب ثم تترسب.","هذا وصف المادة الذائبة في المحلول لا غير الذائبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.331Z"}'::jsonb),
('mcq', 7, 1, 'المادة الذائبة تذوب في المذيب فتكوّن محلولًا، والمحلول مخلوط متجانس لا يمكن التمييز فيه بين المذاب والمذيب. أما المادة غير الذائبة فلا تذوب، فيبقى المخلوط غير متجانس يمكن تمييز مكوناته. فالإجابة: «الأولى: محلول متجانس لا تُميَّز مكوناته — الثانية: مخلوط غير متجانس تُميَّز مكوناته».', '["هذا عكس الصحيح؛ فالمادة الذائبة تكوّن محلولًا متجانسًا، وغير الذائبة تبقى مميزة.","","المادة غير الذائبة لا تذوب فلا تكوّن محلولًا؛ بل تبقى مميزة كالرمل في الماء.","ذوبان المادة لا يُنتج مادة نقية جديدة؛ بل محلولًا تحتفظ فيه كل مادة بخصائصها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.331Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المادة الذائبة: المادة التي تذوب في المذيب، مثل السكر الذي يذوب في الماء لعمل شراب محلّى كالشاي. المادة غير الذائبة: المادة التي لا تذوب في المذيب، مثل الرمل الذي لا يذوب في الماء. ويقبل أي مثال صحيح.', '["تعريف المادة الذائبة","مثال: السكر في الماء","تعريف المادة غير الذائبة","مثال: الرمل في الماء"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المادة الذائبة","marks":1},{"element":"مثال المادة الذائبة","marks":1},{"element":"تعريف المادة غير الذائبة","marks":1},{"element":"مثال المادة غير الذائبة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان ومثالان صحيحان."},{"level":"2–3 درجات","description":"تعريفان دون مثالين، أو تعريف ومثال لنوع واحد مع جزء من الآخر."},{"level":"درجة واحدة","description":"عنصر واحد صحيح."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الخلط بين المادة الذائبة والمذيب.","ذكر الرمل مثالًا على مادة ذائبة لأنه يختفي عند التحريك."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.331Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) يختفي السكر في الماء ولا يمكن تمييزه، ويتكون شراب متجانس محلّى؛ فالسكر مادة ذائبة في الماء لأنه يذوب فيه مكونًا محلولًا. (2) تبقى حبيبات الرمل مميزة وتستقر في القاع بعد الترك؛ فالرمل مادة غير ذائبة في الماء لأنه لا يذوب فيه. (3) يمتزج الزيت والخل فترة قصيرة ثم ينفصلان إلى طبقتين؛ فالزيت مادة غير ذائبة في الخل، إذ الزيت لا يمتزج مع الخل أي لا يذوب فيه.', '["السكر: يختفي ويتكون محلول — ذائب","الرمل: يبقى مميزًا ويستقر — غير ذائب","الزيت: ينفصل عن الخل — غير ذائب في الخل"]'::jsonb, '[]'::jsonb, '[{"element":"الملاحظة في التجربة (1)","marks":1},{"element":"التصنيف والتبرير في (1)","marks":1},{"element":"الملاحظة في التجربة (2)","marks":1},{"element":"التصنيف والتبرير في (2)","marks":1},{"element":"الملاحظة في التجربة (3)","marks":1},{"element":"التصنيف والتبرير في (3)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"ملاحظات وتصنيفات وتبريرات صحيحة للتجارب الثلاث."},{"level":"4–5 درجات","description":"تجربتان كاملتان مع جزء من الثالثة."},{"level":"2–3 درجات","description":"تجربة واحدة كاملة أو تصنيفات صحيحة دون تبرير."},{"level":"درجة واحدة","description":"تصنيف واحد صحيح دون ملاحظة أو تبرير."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["عدّ الزيت ذائبًا في الخل لأنه يمتزج معه عند الرج.","القول إن السكر غير ذائب لأنه صلب.","إغفال تحديد المذيب عند الحكم على الذوبان."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.331Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الجزء الأول من العبارة خاطئ: السكر لم يختفِ من الكأس، بل ذاب في الماء؛ فهو مادة ذائبة كوّنت مع الماء محلولًا متجانسًا لا يمكن فيه التمييز بين المذاب والمذيب عند النظر، فبدا كأنه اختفى. والدليل على بقائه أن الشراب يصبح محلّى (كالشاي المحلّى). أما الجزء الثاني فصحيح: الرمل مادة غير ذائبة في الماء، فلا يذوب فيه وتبقى حبيباته مميزة. فالفرق أن السكر ذاب وبقي موجودًا موزعًا في المحلول، والرمل لم يذب فبقي مميزًا.', '["الحكم: الجزء الأول خاطئ والثاني صحيح","السكر ذاب مكونًا محلولًا متجانسًا لا يُميَّز فيه المذاب","الدليل: طعم الشراب الحلو","الرمل غير ذائب وتبقى حبيباته مميزة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على جزأي العبارة","marks":1},{"element":"تفسير ما حدث للسكر","marks":1},{"element":"الدليل على بقاء السكر","marks":1},{"element":"الفرق بين السكر والرمل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحكم على الجزأين ويفسر الذوبان ويقدم دليلًا ويوضح الفرق."},{"level":"2–3 درجات","description":"يفسر الذوبان ويوضح الفرق دون دليل، أو يحكم دون تفسير كامل."},{"level":"درجة واحدة","description":"يحكم بخطأ القول إن السكر لم يعد موجودًا دون تفسير."},{"level":"صفر","description":"يؤيد العبارة كلها أو لا يجيب."}]'::jsonb, '["تأييد أن المادة الذائبة تختفي ولا تبقى في المحلول.","عدّ عدم رؤية السكر دليلًا على تحوله إلى مادة جديدة.","الحكم بأن الرمل ذائب جزئيًّا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.331Z"}'::jsonb)
