('mcq', 1, 'ما المقصود بتركيز المحلول؟', null, '["أقصى كمية من المذاب يمكن أن تذوب في كمية محددة من المذيب عند درجة حرارة معينة","مقياس يعبّر عن كمية المذاب الذائبة في كمية محددة من المذيب أو المحلول","السرعة التي يذوب بها المذاب في المذيب عند تحريك المحلول وتسخينه","كتلة المذيب اللازمة لإذابة مول واحد من المذاب في المحلول"]'::jsonb, 'تذكر', 'تذكر/تعريف', 'سهل', 'الكتاب ص 19 — التعبير عن التركيز'),
('mcq', 2, 'يحتوي إبريقان على شاي، لون الأول غامق ولون الثاني فاتح. أيّ العبارات الآتية تصف الإبريقين وصفًا صحيحًا؟', null, '["الشاي الفاتح محلول مركّز لأنه يحتوي على كمية أكبر من الماء","الشاي الغامق محلول مخفّف لأن جسيماته الذائبة أقل من الفاتح","الشاي الغامق محلول مركّز يحتوي على جسيمات شاي أكثر من الشاي الفاتح","للإبريقين التركيز نفسه لأن المذاب والمذيب فيهما من النوع نفسه"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'سهل', 'الكتاب ص 19 — الشكل 1-4'),
('mcq', 3, 'ما الكلمة التي تصف نوعيًّا محلولًا يحتوي على كمية كبيرة من المذاب؟', null, '["مخفّف","مشبع","مركّز","متجانس"]'::jsonb, 'تذكر', 'تذكر/مصطلح', 'سهل', 'الكتاب ص 19 — التعبير عن التركيز'),
('mcq', 4, 'أضاف شخص كمية من الماء إلى كأس عصير ليمون لأنه مركّز جدًّا. ماذا حدث لتركيز العصير؟', null, '["زاد تركيزه لأن كمية المحلول زادت","بقي تركيزه ثابتًا لأن كمية المذاب لم تتغير","أصبح محلولًا مشبعًا لا يذيب مزيدًا من المذاب","قلّ تركيزه فأصبح أكثر تخفيفًا"]'::jsonb, 'فهم', 'تنبؤ وتفسير', 'متوسط', 'الكتاب ص 19، 24 — الربط مع الحياة، مفردة «مركّز»'),
('mcq', 5, 'أيّ الأوصاف الآتية يعبّر عن تركيز المحلول تعبيرًا كميًّا لا وصفيًّا؟', null, '["محلول سكري مركّز جدًّا ذو طعم حلو","شاي مخفّف لونه فاتح","محلول أكثر تركيزًا من محلول آخر","محلول ملحي نسبة الملح فيه 3.5% بالكتلة"]'::jsonb, 'فهم', 'تمييز وتصنيف', 'متوسط', 'الكتاب ص 19 — التعبير عن التركيز'),
('mcq', 6, 'ما الذي تشترك فيه جميع طرائق التعبير الكمي عن تركيز المحلول؟', null, '["أنها تعبّر عن التركيز بوصفه نسبة بين كمية المذاب وكمية المذيب أو المحلول","أنها تستعمل عدد مولات المذاب في البسط دائمًا","أنها تستعمل حجم المحلول باللتر في المقام دائمًا","أنها تعطي قيمًا لا تتأثر بتغيّر درجة الحرارة"]'::jsonb, 'فهم', 'استنتاج', 'صعب', 'الكتاب ص 19 — التعبير عن التركيز'),
('mcq', 7, 'يبيّن الجدول كتلة السكر المذابة في حجوم متساوية من محاليل سكرية. أيّ المحاليل أكثرها تخفيفًا؟', '{"headers":["المحلول","كتلة السكر المذابة","حجم المحلول"],"rows":[["(أ)","20 g","250 mL"],["(ب)","12 g","250 mL"],["(ج)","5 g","250 mL"],["(د)","8 g","250 mL"]]}'::jsonb, '["المحلول (أ)","المحلول (ج)","المحلول (ب)","المحلول (د)"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 19 — التعبير عن التركيز'),
('essay', 1, 'عرّف تركيز المحلول، ثم وضّح الفرق بين المحلول المركّز والمحلول المخفّف مستعينًا بمثال الشاي الغامق والشاي الفاتح.', null, null, 'تذكر', 'تعريف وتوضيح بمثال', 'سهل', 'الكتاب ص 19 — التعبير عن التركيز، الشكل 1-4'),
('essay', 2, 'قال طالب: «محلول الملح هذا مركّز». بيّن لماذا لا يكفي هذا الوصف في المختبر، ثم اذكر طريقتين للتعبير الكمي عن التركيز يمكن أن تحل محله.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 19 — التعبير عن التركيز'),
('essay', 3, 'أذاب طالب كتلًا مختلفة من السكر في كميات من الماء كما يأتي: المحلول (س) 10 g سكر في 100 g ماء، والمحلول (ص) 10 g سكر في 200 g ماء، والمحلول (ع) 30 g سكر في 200 g ماء.
