from (values
('mcq', 1, 1, 'تركيز المحلول مقياس يعبّر عن كمية المذاب الذائبة في كمية محددة من المذيب أو المحلول؛ فهو نسبة بين كمية المذاب وكمية المذيب أو المحلول.', '["هذا تعريف الذائبية (المحلول المشبع)، لا تعريف التركيز؛ فالتركيز يصف أي محلول لا الحد الأقصى فقط.","","هذا وصف لسرعة الذوبان، وهي لا تعبّر عن كمية المذاب الموجودة في المحلول.","هذه ليست طريقة للتعبير عن التركيز؛ التركيز نسبة كمية المذاب إلى كمية المذيب أو المحلول، لا كتلة مذيب لازمة لمول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.332Z"}'::jsonb),
('mcq', 2, 2, 'شدة اللون تعكس تركيز الشاي؛ فالشاي الغامق أعلى تركيزًا، أي محلول مركّز يحتوي على كمية أكبر من المذاب (جسيمات الشاي)، والشاي الفاتح محلول مخفّف يحتوي على كمية أقل منها.', '["كثرة الماء بالنسبة إلى المذاب تجعل المحلول مخففًا لا مركّزًا.","عكس الصحيح؛ اللون الغامق يدل على جسيمات شاي ذائبة أكثر، أي تركيز أعلى.","","تشابه نوع المذاب والمذيب لا يعني تساوي التركيز؛ التركيز يتحدد بكمية المذاب في كمية المحلول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.332Z"}'::jsonb),
('mcq', 3, 2, 'يمكن التعبير عن التركيز وصفيًّا بكلمتي «مركّز» و«مخفّف»؛ والمحلول المركّز يحتوي عمومًا على كمية كبيرة من المذاب.', '["المحلول المخفّف يحتوي على كمية أقل من المذاب، فهو عكس المطلوب.","المشبع يصف محلولًا يحتوي على أقصى كمية من المذاب، وليس هو الوصف النوعي للتركيز الذي يقابل «مخفّف».","","التجانس صفة لكل المحاليل ولا يدل على كمية المذاب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.333Z"}'::jsonb),
('mcq', 4, 3, 'إضافة المذيب (الماء) تزيد كمية المحلول دون أن تزيد كمية المذاب، فتقل نسبة المذاب إلى المحلول، أي يقل التركيز ويصبح العصير مخففًا.', '["زيادة كمية المحلول مع بقاء المذاب نفسه تُنقص النسبة بينهما، فلا يزيد التركيز.","ثبات كمية المذاب لا يكفي؛ التركيز نسبة، وقد زاد المقام (كمية المحلول).","إضافة الماء تبعد المحلول عن التشبع ولا تجعله مشبعًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.333Z"}'::jsonb),
('mcq', 5, 3, 'التعبير الكمي يعطي قيمة عددية تبيّن نسبة المذاب إلى المحلول (مثل النسبة المئوية أو المولارية)، أما كلمات مثل «مركّز» و«مخفّف» فتعبير وصفي.', '["كلمة «مركّز» وصف نوعي لا يعطي قيمة عددية للتركيز.","كلمة «مخفّف» ولون الشاي وصف نوعي لا كمي.","المقارنة دون أرقام وصف نوعي، ولا تحدد مقدار التركيز.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.333Z"}'::jsonb),
('mcq', 6, 0, 'كل طرائق التعبير عن التركيز تعبّر عنه بوصفه نسبة بين كمية المذاب وبين كمية المذيب أو المحلول كله.', '["","النسبتان المئويتان بدلالة الكتلة والحجم لا تستعملان المولات.","المولالية مقامها كتلة المذيب بالكيلوجرام، والنسبة بالكتلة مقامها كتلة المحلول.","الطرائق المعتمدة على الحجم كالمولارية تتأثر بدرجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.333Z"}'::jsonb),
('mcq', 7, 1, 'في الحجوم المتساوية من المحلول يكون الأقل كتلةً من المذاب هو الأقل تركيزًا، أي الأكثر تخفيفًا؛ والمحلول (ج) يحتوي على 5 g فقط، وهي أقل كمية.', '["المحلول (أ) يحتوي على 20 g، وهي أكبر كمية، فهو أكثرها تركيزًا.","","المحلول (ب) يحتوي على 12 g، أكثر من (ج) و(د)، فليس الأكثر تخفيفًا.","المحلول (د) يحتوي على 8 g، أكثر من (ج)، فهو أعلى تركيزًا منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.333Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تركيز المحلول مقياس يعبّر عن كمية المذاب الذائبة في كمية محددة من المذيب أو المحلول. المحلول المركّز يحتوي على كمية كبيرة من المذاب، والمحلول المخفّف يحتوي على كمية أقل منه. فالشاي الغامق محلول مركّز يحتوي على جسيمات شاي أكثر، والشاي الفاتح محلول مخفّف يحتوي على جسيمات شاي أقل.', '["تعريف التركيز تعريفًا صحيحًا","وصف المحلول المركّز","وصف المحلول المخفّف","ربط المثال بالمفهومين"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف التركيز","marks":1},{"element":"المحلول المركّز","marks":1},{"element":"المحلول المخفّف","marks":1},{"element":"مثال الشاي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح ووصف دقيق للنوعين مع ربط صحيح بالمثال"},{"level":"3 درجات","description":"تعريف صحيح ووصف النوعين دون ربط واضح بالمثال"},{"level":"2 درجتان","description":"تعريف صحيح فقط أو وصف النوعين فقط"},{"level":"1 درجة","description":"إشارة جزئية صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["الخلط بين التركيز والذائبية","وصف المحلول المخفّف بأنه لا يحتوي على مذاب","عكس وصفي الشاي الغامق والفاتح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.333Z"}'::jsonb),
('essay', 2, null::int, null, null, 'وصف «مركّز» وصف نوعي (وصفي) لا يحدد مقدار المذاب في كمية معينة من المحلول، فلا يمكن به مقارنة المحاليل بدقة أو تكرار تحضيرها. لذلك يعبَّر عن التركيز كميًّا، ومن ذلك: النسبة المئوية بدلالة الكتلة، والمولارية (وكذلك النسبة المئوية بدلالة الحجم، والمولالية، والكسر المولي).', '["الوصف نوعي لا يعطي قيمة عددية","لا يسمح بالمقارنة الدقيقة أو إعادة التحضير","ذكر طريقتين كميتين صحيحتين"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أن الوصف نوعي","marks":1},{"element":"سبب عدم كفايته","marks":1},{"element":"طريقتان كميتان (درجة لكل منهما)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع طريقتين صحيحتين"},{"level":"3 درجات","description":"تفسير ناقص مع طريقتين صحيحتين، أو تفسير كامل مع طريقة واحدة"},{"level":"2 درجتان","description":"طريقتان صحيحتان دون تفسير، أو تفسير دون طرائق"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["ذكر «مخفّف» بوصفها طريقة كمية","ذكر الذائبية طريقةً للتعبير عن التركيز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.334Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) نقارن كمية المذاب في كمية المذيب: (ص) 10 g في 200 g أي 5 g لكل 100 g ماء، و(س) 10 g لكل 100 g ماء، و(ع) 30 g في 200 g أي 15 g لكل 100 g ماء. الترتيب التصاعدي: (ص) < (س) < (ع).
