('essay', 3, null::int, null, null, 'الادعاء غير صحيح. النسبة بدلالة الكتلة = (كتلة المذاب ÷ كتلة المحلول) × 100، والنسبة بدلالة الحجم = (حجم المذاب ÷ حجم المحلول) × 100. الكتلة والحجم كميتان مختلفتان، والمادتان المختلفتان (الإيثانول والماء) لا تتساوى عندهما نسبة الكتلة إلى الحجم، فإذا تساوى حجما عيّنتين منهما لم تتساوَ كتلتاهما؛ لذا تختلف قيمة النسبتين عمومًا للمحلول نفسه، ويجب ذكر نوع النسبة مع القيمة.', '["الحكم بعدم صحة الادعاء","كتابة العلاقتين","تعليل: الكتلة والحجم كميتان مختلفتان ولا تتناسبان بالقدر نفسه للمادتين","ضرورة ذكر نوع النسبة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"العلاقتان","marks":1},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع العلاقتين وتعليل علمي واضح"},{"level":"3 درجات","description":"حكم صحيح وتعليل مقبول دون العلاقتين"},{"level":"1–2 درجة","description":"حكم صحيح بلا تعليل أو علاقتان فقط"},{"level":"صفر","description":"تأييد الادعاء أو إجابة متروكة"}]'::jsonb, '["تأييد الادعاء لأن كلتيهما «نسبة مئوية»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.340Z"}'::jsonb)
