('essay', 2, null::int, null, null, 'المحلول الثاني تركيزه 1 M؛ لأن المولارية عدد مولات المذاب في لتر من المحلول لا من المذيب. في المحلول الأول يزيد المذاب حجم المحلول فيصبح أكبر من 1 L، فيقل تركيزه عن 1 M. أما الثاني فحجم المحلول النهائي 1 L ويحتوي على 1 mol، فتركيزه 1 mol ÷ 1 L = 1 M.', '["اختيار المحلول الثاني","المولارية مقامها حجم المحلول","المذاب يزيد الحجم في الأول فيقل التركيز"]'::jsonb, '[]'::jsonb, '[{"element":"الاختيار الصحيح","marks":1},{"element":"الاستناد إلى التعريف","marks":1},{"element":"تفسير خطأ الأول","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"اختيار صحيح مع تفسير كامل"},{"level":"2 درجتان","description":"اختيار صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"اختيار صحيح دون تفسير"},{"level":"صفر","description":"اختيار خاطئ أو إجابة متروكة"}]'::jsonb, '["عدّ المحلولين متساويين لأن كمية المذاب واحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.345Z"}'::jsonb),
