('mcq', 1, 'ما حجم محلول HCl القياسي الذي تركيزه 6.00 M اللازم لتحضير 500. mL من محلول تركيزه 1.50 M؟', null, '["2000 mL","375 mL","125 mL","0.125 mL"]'::jsonb, 'تطبيق', 'مسألة تخفيف', 'متوسط', 'الكتاب ص 24–25 — تخفيف المحاليل المولارية، مثال 1-3'),
('mcq', 2, 'خُفّف 20.0 mL من محلول H₂SO₄ تركيزه 0.50 M بالماء حتى أصبح حجمه 100. mL. ما تركيز المحلول الناتج؟', null, '["2.5 M","0.083 M","0.10 M","0.50 M"]'::jsonb, 'تطبيق', 'مسألة تخفيف', 'سهل', 'الكتاب ص 24–25 — تخفيف المحاليل المولارية، مثال 1-3'),
('mcq', 3, 'ما الكمية التي تبقى ثابتة عند تخفيف محلول بإضافة المذيب، وعليها بُنيت المعادلة M₁V₁ = M₂V₂؟', null, '["عدد مولات المذاب","مولارية المحلول","حجم المحلول","عدد جسيمات المذيب"]'::jsonb, 'فهم', 'تفسير مبدأ', 'سهل', 'الكتاب ص 24 — الشكل 1-6'),
('mcq', 4, 'يراد تخفيف 50.0 mL من محلول تركيزه 2.00 M إلى تركيز 0.500 M. ما حجم الماء الذي يجب إضافته؟', null, '["200. mL","150. mL","12.5 mL","250. mL"]'::jsonb, 'تطبيق', 'مسألة متعددة الخطوات', 'صعب', 'الكتاب ص 24–25 — تخفيف المحاليل المولارية، مثال 1-3'),
('mcq', 5, 'ما أكبر حجم من محلول NaOH تركيزه 0.50 M يمكن تحضيره من 25 mL من محلول قياسي تركيزه 4.0 M؟', null, '["3.1 mL","175 mL","225 mL","200 mL"]'::jsonb, 'تطبيق', 'حساب الحجم النهائي', 'متوسط', 'الكتاب ص 24–25 — تخفيف المحاليل المولارية، مثال 1-3'),
('mcq', 6, 'يراد تحضير 100 mL من محلول تركيزه 0.25 M من محلول قياسي تركيزه 1.0 M. أيّ الإجراءات الآتية صحيح؟', null, '["يؤخذ 25 mL من المحلول القياسي ويُضاف الماء حتى يصبح الحجم 100 mL","يؤخذ 25 mL من المحلول القياسي ويُضاف إليه 100 mL من الماء","يؤخذ 2.5 mL من المحلول القياسي ويُضاف الماء حتى يصبح الحجم 100 mL","يؤخذ 75 mL من المحلول القياسي ويُضاف الماء حتى يصبح الحجم 100 mL"]'::jsonb, 'تحليل', 'تقويم إجراء', 'صعب', 'الكتاب ص 24–25 — تخفيف المحاليل المولارية، مثال 1-3'),
('mcq', 7, 'في مثال 1-3 حُسب الحجم V₁ اللازم من محلول CaCl₂ القياسي (2.00 M) لتحضير 0.50 L بتركيز 0.300 M. أيّ تعويض صحيح؟', null, '["V₁ = 0.50 L × (2.00 M ÷ 0.300 M)","V₁ = 0.50 L × (0.300 M ÷ 2.00 M)","V₁ = 2.00 M × (0.300 M ÷ 0.50 L)","V₁ = 0.50 L − (0.300 M ÷ 2.00 M)"]'::jsonb, 'فهم', 'اختيار التعويض الصحيح', 'متوسط', 'الكتاب ص 25 — مثال 1-3'),
('essay', 1, 'ما حجم محلول KI القياسي الذي تركيزه 3.00 M اللازم لتحضير 0.300 L من محلول تركيزه 1.25 M؟ اكتب الناتج بالملّلتر.', null, null, 'تطبيق', 'مسألة تخفيف', 'سهل', 'الكتاب ص 25 — مسألة 24'),
('essay', 2, 'يتوفر في المختبر محلول HCl قياسي تركيزه 12.0 M. يراد تحضير 250. mL من محلول HCl تركيزه 0.600 M.
(أ) احسب حجم المحلول القياسي اللازم.
(ب) احسب حجم الماء الذي يلزم تقريبًا، ووضّح كيف يُكمل التحضير.', null, null, 'تطبيق', 'مسألة متعددة الخطوات', 'متوسط', 'الكتاب ص 24–25 — تخفيف المحاليل المولارية، مثال 1-3'),
('essay', 3, 'خفّف طالب 10.0 mL من محلول NaCl تركيزه 1.50 M حتى أصبح حجمه 50.0 mL، ثم أخذ 5.00 mL من المحلول الناتج وخفّفها حتى أصبح حجمها 25.0 mL. احسب تركيز المحلول بعد كل تخفيف، وفسّر لماذا يقل التركيز رغم ثبات عدد المولات في كل خطوة.', null, null, 'تحليل', 'مسألة تخفيف متتابع', 'صعب', 'الكتاب ص 24–25 — تخفيف المحاليل المولارية، مثال 1-3')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C1-L2-O08') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
