from (values
('mcq', 1, 2, 'V₁ = M₂V₂ ÷ M₁ = (1.50 M × 500. mL) ÷ 6.00 M = 125 mL.', '["قُلبت النسبة: 6.00 × 500 ÷ 1.50.","هذا حجم الماء المضاف (500 − 125) لا حجم المحلول القياسي.","","الناتج باللتر (0.125 L) كُتب بوحدة الملّلتر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T11:36:22.350Z"}'::jsonb),
('mcq', 2, 2, 'M₂ = M₁V₁ ÷ V₂ = (0.50 × 20.0) ÷ 100. = 0.10 M.', '["قُلبت النسبة: 0.50 × 100 ÷ 20.0، فخرج التركيز أكبر بعد التخفيف.","عُدّ 100 mL ماءً مضافًا فاستُعمل حجم كلي 120 mL، والمعطى أن الحجم النهائي 100 mL.","","افتُرض أن التخفيف لا يغيّر التركيز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.350Z"}'::jsonb),
('mcq', 3, 0, 'لا يتغير عدد مولات المذاب بالتخفيف، وعدد المولات = M × V، فيكون M₁V₁ = M₂V₂.', '["","المولارية تقل بالتخفيف.","الحجم يزداد بإضافة المذيب.","يزداد عدد جسيمات المذيب بإضافته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.351Z"}'::jsonb),
('mcq', 4, 1, 'V₂ = M₁V₁ ÷ M₂ = 2.00 × 50.0 ÷ 0.500 = 200. mL، وحجم الماء المضاف = 200. − 50.0 = 150. mL.', '["هذا الحجم النهائي للمحلول لا حجم الماء المضاف.","","قُلبت النسبة: 0.500 × 50.0 ÷ 2.00.","جُمع الحجم الأصلي مع الحجم النهائي بدل الطرح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T11:36:22.351Z"}'::jsonb),
('mcq', 5, 3, 'V₂ = M₁V₁ ÷ M₂ = 4.0 × 25 ÷ 0.50 = 200 mL.', '["قُلبت النسبة: 0.50 × 25 ÷ 4.0.","هذا حجم الماء المضاف (200 − 25) لا الحجم النهائي.","عُدّ 200 mL ماءً مضافًا فجُمع مع 25 mL، والصحيح أن V₂ هو الحجم الكلي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.351Z"}'::jsonb),
('mcq', 6, 0, 'V₁ = 0.25 × 100 ÷ 1.0 = 25 mL، ويجب أن يكون الحجم النهائي (V₂) 100 mL، فيُكمل بالماء حتى 100 mL أي يُضاف نحو 75 mL ماء.', '["","الحجم النهائي يصبح 125 mL فيكون التركيز 0.20 M.","خطأ في موضع الفاصلة العشرية؛ 2.5 mL تعطي تركيزًا 0.025 M.","خُلط بين حجم المحلول القياسي وحجم الماء؛ التركيز الناتج 0.75 M."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.351Z"}'::jsonb),
('mcq', 7, 1, 'من M₁V₁ = M₂V₂ نحصل على V₁ = V₂ × (M₂ ÷ M₁) = 0.50 L × (0.300 ÷ 2.00) = 0.075 L = 75 mL.', '["نسبة التركيزين مقلوبة، فيخرج V₁ أكبر من V₂.","","ترتيب غير صحيح للمتغيرات لا ينتج وحدة الحجم.","طرح لا أساس له؛ العلاقة ضرب V₂ في نسبة التركيزين M₂/M₁."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.351Z"}'::jsonb),
('essay', 1, null::int, null, null, 'M₁V₁ = M₂V₂ ⇒ V₁ = M₂V₂ ÷ M₁ = (1.25 M × 0.300 L) ÷ 3.00 M = 0.125 L = 125 mL.', '["كتابة معادلة التخفيف","إعادة ترتيبها لإيجاد V₁","التعويض","الناتج 125 mL"]'::jsonb, '["المعطيات: M₁ = 3.00 M، M₂ = 1.25 M، V₂ = 0.300 L","V₁ = M₂V₂ ÷ M₁","V₁ = 1.25 × 0.300 ÷ 3.00 = 0.125 L","V₁ = 0.125 L × 1000 mL/L = 125 mL"]'::jsonb, '[{"element":"المعادلة وإعادة الترتيب","marks":1},{"element":"التعويض والحساب","marks":1},{"element":"التحويل إلى mL","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حل كامل صحيح"},{"level":"2 درجتان","description":"حل صحيح دون تحويل الوحدة أو بخطأ حسابي"},{"level":"1 درجة","description":"كتابة المعادلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["قلب نسبة التركيزين","نسيان التحويل إلى mL"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T11:36:22.352Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) V₁ = M₂V₂ ÷ M₁ = 0.600 × 250. ÷ 12.0 = 12.5 mL.
(ب) يُؤخذ 12.5 mL من المحلول القياسي ويُضاف الماء حتى يصبح الحجم الكلي 250. mL، أي يُضاف نحو 250. − 12.5 = 237.5 mL من الماء (يُكمل الحجم حتى العلامة بدل إضافة رقم محسوب).', '["V₁ = 12.5 mL","حجم الماء ≈ 237.5 mL","الإكمال حتى الحجم الكلي 250 mL"]'::jsonb, '["V₁ = (0.600 × 250.) ÷ 12.0 = 12.5 mL","حجم الماء ≈ 250. − 12.5 = 237.5 mL"]'::jsonb, '[{"element":"حساب V₁","marks":2},{"element":"حجم الماء","marks":1},{"element":"وصف الإكمال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب ووصف صحيحان"},{"level":"3 درجات","description":"حساب صحيح ووصف ناقص"},{"level":"1–2 درجة","description":"حساب V₁ فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["إضافة 250 mL ماء إلى 12.5 mL","قلب النسبة فيخرج 5000 mL"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T11:36:22.352Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التخفيف الأول: M₂ = 1.50 × 10.0 ÷ 50.0 = 0.300 M.
التخفيف الثاني: M₃ = 0.300 × 5.00 ÷ 25.0 = 0.0600 M.
يقل التركيز لأن عدد مولات المذاب في العيّنة المخففة ثابت بينما يزداد حجم المحلول بإضافة المذيب، والمولارية = المولات ÷ الحجم.', '["M بعد التخفيف الأول 0.300 M","استعمال 0.300 M تركيزًا ابتدائيًّا في الثاني","M النهائي 0.0600 M","التفسير"]'::jsonb, '["M₂ = (1.50 × 10.0) ÷ 50.0 = 0.300 M","M₃ = (0.300 × 5.00) ÷ 25.0 = 0.0600 M"]'::jsonb, '[{"element":"التخفيف الأول","marks":2},{"element":"التخفيف الثاني","marks":2},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابان صحيحان وتفسير"},{"level":"3–4 درجات","description":"حسابان صحيحان دون تفسير أو خطأ في الثاني"},{"level":"1–2 درجة","description":"التخفيف الأول فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["استعمال 1.50 M في التخفيف الثاني","عدّ 50.0 mL حجم الماء المضاف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.352Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
