('essay', 3, null::int, null, null, 'الكسر المولي: البسط مولات المذاب أو المذيب، والمقام مجموع مولات المذاب والمذيب، ولا وحدة له. المولالية: البسط مولات المذاب، والمقام كتلة المذيب (kg)، ووحدتها mol/kg. لا تتأثر أيّ منهما بدرجة الحرارة لأن كلتيهما تعتمد على المولات والكتل التي لا تتأثر بالحرارة، ولا تعتمد على الحجم.', '["البسط في كل منهما","المقام في كل منهما","الوحدة","التعليل: لا تعتمدان على الحجم"]'::jsonb, '[]'::jsonb, '[{"element":"البسط","marks":1},{"element":"المقام","marks":1},{"element":"الوحدة","marks":1},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة وتعليل كاملان"},{"level":"3–4 درجات","description":"مقارنة صحيحة وتعليل ناقص"},{"level":"1–2 درجة","description":"جانب أو جانبان"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["إعطاء الكسر المولي وحدة mol","القول إن المولالية تعتمد على الحجم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.358Z"}'::jsonb)
