('mcq', 3, 0, 'إذا كانت قوى التجاذب المتكونة بين جسيمات المذاب والمذيب أكبر من قوى التجاذب بين جسيمات المذاب نفسه، فسوف تجذب جسيمات المذيب جسيمات المذاب وتفصلها وتحيط بها.', '["","في هذه الحالة تبقى جسيمات المذاب متماسكة ولا يحدث الذوبان، كما في الجبس.","الكتلة لا تحدد حدوث الذوبان، بل المقارنة بين قوى التجاذب.","درجات الانصهار والغليان ليست شرط الذوبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.365Z"}'::jsonb),
('mcq', 4, 2, 'قاعدة «المذيب يذيب شبيهه» قاعدة عامة تُستعمل لتحديد ما إذا كانت عملية الذوبان تحدث في مذيب معين.', '["القاعدة نوعية تتنبأ بحدوث الذوبان، ولا تُستعمل في حساب الكتل.","كمية الطاقة تتعلق بحرارة الذوبان، لا بهذه القاعدة.","","سرعة الذوبان تتأثر بالتحريك ومساحة السطح ودرجة الحرارة، ولا تُحسب بهذه القاعدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.365Z"}'::jsonb),
('mcq', 5, 1, 'لتحديد ما إذا كان المذيب والمذاب متماثلين تجب دراسة قطبية المركبات ونوع الروابط بين الجزيئية فيها.', '["تشابه الكتل المولية لا يعني تشابه القوى بين الجزيئات التي يتوقف عليها الذوبان.","","اللون والحالة الفيزيائية خواص لا تحدد قوى التجاذب بين الجسيمات.","درجة الغليان وحدها لا تكفي؛ المطلوب القطبية ونوع الروابط بين الجزيئية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.365Z"}'::jsonb),
('mcq', 6, 3, 'تحيط جسيمات المذيب بسطح المذاب الصلب، ثم تجذب جسيماته وتفصلها عن بعضها وتحيط بها، ثم تبتعد الجسيمات المحاطة عن المذاب الصلب وتتجه نحو المحلول.', '["لا تبتعد جسيمات المذاب نحو المحلول قبل أن تُفصل وتُحاط؛ الترتيب معكوس.","الذوبان لا تتكون فيه مادة جديدة ولا يحدث فيه ترسب.","المذاب الصلب لا ينصهر في أثناء الذوبان؛ بل تفصل جسيمات المذيب جسيماته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.365Z"}'::jsonb),
('mcq', 7, 2, 'شرط الذوبان أن تتغلب قوى التجاذب بين المذاب والمذيب على قوى التجاذب بين جسيمات المذاب، فإذا كانت الأخيرة أقوى بقيت المادة متماسكة ولا تذوب، كما في الجبس.', '["شدة تماسك جسيمات المذاب تعيق الذوبان ولا تسرّعه.","لم يحدث تجاذب كافٍ لفصل الجسيمات، والذوبان ليس تفاعلًا كيميائيًا.","","إذا لم تتغلب جسيمات الماء على تجاذب جسيمات المذاب فلن تنفصل حتى جسيمات السطح بدرجة ملحوظة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.365Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الذوبان هو عملية إحاطة جسيمات المذاب بجسيمات المذيب. ويحدث إذا كانت قوى التجاذب المتكونة بين جسيمات المذاب وجسيمات المذيب أكبر من قوى التجاذب بين جسيمات المذاب نفسه، فتجذب جسيمات المذيب جسيمات المذاب وتفصلها عن بعضها وتحيط بها.', '["تعريف الذوبان: إحاطة جسيمات المذاب بجسيمات المذيب","الشرط: قوى تجاذب المذاب–المذيب أكبر من قوى التجاذب بين جسيمات المذاب"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف الصحيح","marks":2},{"element":"ذكر الشرط مع المقارنة الصحيحة بين قوى التجاذب","marks":2}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["تعريف الذوبان بأنه انصهار المادة أو اختفاؤها","عكس المقارنة في الشرط فيُجعل تجاذب جسيمات المذاب هو الأكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.365Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عند وضع المذاب الصلب في المذيب تحيط جسيمات المذيب بسطح المذاب الصلب تمامًا. ولأن قوى التجاذب بين جسيمات المذاب والمذيب أكبر من قوى التجاذب بين جسيمات المذاب نفسه، تجذب جسيمات المذيب جسيمات المذاب وتفصل بعضها عن بعض وتحيط بها، ثم تبتعد جسيمات المذاب المحاطة بجسيمات المذيب عن المذاب الصلب وتتجه نحو المحلول، فتتعرض جسيمات أخرى من سطح المذاب للمذيب وتتكرر العملية.', '["إحاطة جسيمات المذيب بسطح المذاب","المقارنة بين قوى التجاذب سبب الانفصال","جذب جسيمات المذاب وفصلها وإحاطتها","ابتعاد الجسيمات المحاطة نحو المحلول وتعرّض جسيمات جديدة"]'::jsonb, '[]'::jsonb, '[{"element":"إحاطة سطح المذاب","marks":1},{"element":"تفسير الانفصال بقوى التجاذب","marks":2},{"element":"فصل الجسيمات وإحاطتها","marks":1},{"element":"الابتعاد نحو المحلول واستمرار العملية","marks":1}]'::jsonb, '[{"level":"5","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"3–4","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1–2","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["الاكتفاء بقول «المادة تختفي في الماء» دون وصف جسيمي","إغفال دور قوى التجاذب في تفسير الانفصال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.365Z"}'::jsonb),
('essay', 3, null::int, null, null, '«المذيب يذيب شبيهه» قاعدة عامة تُستعمل لتحديد ما إذا كانت عملية الذوبان تحدث في مذيب معين؛ فالمذاب يذوب في المذيب المماثل له. ولتحديد التماثل تجب دراسة قطبية المركبات ونوع الروابط بين الجزيئية فيها. الماء مذيب قطبي، والزيت غير قطبي، فقوى التجاذب بين جزيئات الماء القطبية وجزيئات الزيت غير القطبية ضعيفة ولا تتغلب على التجاذب بين جزيئات كل منهما، لذا لا يذوب الزيت في الماء، بل يذوب في مذيب غير قطبي.', '["معنى القاعدة: المذاب يذوب في المذيب المماثل له","تُدرس القطبية ونوع الروابط بين الجزيئية","الماء قطبي والزيت غير قطبي","التجاذب بينهما ضعيف فلا يحدث ذوبان، والزيت يذوب في مذيب غير قطبي"]'::jsonb, '[]'::jsonb, '[{"element":"معنى القاعدة","marks":1},{"element":"ما تجب دراسته","marks":2},{"element":"تصنيف الماء والزيت من حيث القطبية","marks":1},{"element":"التفسير بقوى التجاذب الضعيفة","marks":2}]'::jsonb, '[{"level":"6","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"3–5","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1–2","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["الاعتقاد أن الزيت لا يذوب لأنه أخف من الماء","ذكر القطبية دون ربطها بقوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.365Z"}'::jsonb)
