from (values
('mcq', 1, 0, 'يبدأ تفسير الذوبان بأن جزيئات الماء قطبية، وأنها في حركة مستمرة بحسب نظرية الحركة الجزيئية؛ فتصطدم بسطح البلورة وتجذب أقطابها الأيونات.', '["","جزيئات الماء قطبية ومتحركة باستمرار، ولو كانت غير قطبية لما جذبت الأيونات.","الماء مركب جزيئي قطبي وليس مركبًا أيونيًا.","كتلة الجزيء وتباعده ليسا أساس التفسير؛ الأساس القطبية والحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.366Z"}'::jsonb),
('mcq', 2, 2, 'أقطاب جزيئات الماء المشحونة تجذب أيونات الصوديوم والكلوريد، وهذا التجاذب أكبر من التجاذب بين الأيونات في البلورة، لذلك تنزلق الأيونات مبتعدة عن سطح البلورة.', '["الذوبان هنا لا ينتج مادة جديدة؛ الأيونات نفسها تُحاط بجزيئات الماء.","لو ازداد تجاذب الأيونات لبقيت في البلورة ولم تذب.","","لا يحدث انتقال إلكترونات؛ التأثير تجاذب كهربائي بين الأقطاب والأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.366Z"}'::jsonb),
('mcq', 3, 3, 'أيون Na⁺ موجب، فتجذبه أقطاب جزيئات الماء ذات الشحنة المخالفة، وهي الطرف السالب جزئيًا من الجزيء (ذرة الأكسجين).', '["الطرف الموجب جزئيًا يتنافر مع Na⁺ الموجب، وهو الطرف المتجه نحو Cl⁻.","جزيء الماء قطبي، فيتجه بطرفه المخالف للشحنة نحو الأيون.","الماء متعادل كليًا لكنه قطبي، فلطرفيه شحنتان جزئيتان تجذبان الأيونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.366Z"}'::jsonb),
('mcq', 4, 1, 'لا يمكن إذابة جميع المركبات الأيونية في الماء؛ فالجبس لا يذوب لأن قوى التجاذب بين أيوناته قوية لا تستطيع قوى التجاذب بين جزيئات الماء والأيونات التغلب عليها.', '["قطبية الماء لا تكفي دائمًا؛ فبعض المركبات الأيونية كالجبس لا تذوب.","","كلوريد الصوديوم مثلًا مركب أيوني يذوب في الماء.","تنفصل الأيونات في الماء وتُحاط بجزيئاته، ولا تذوب جزيئات متعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.367Z"}'::jsonb),
('mcq', 5, 2, 'تحيط جزيئات الماء بالأيونات وتسحبها نحو المحلول، معرّضة أيونات أخرى على سطح البلورة للذوبان، وهكذا تستمر العملية حتى تذوب البلورة كلها.', '["عودة الأيونات إلى البلورة تبلور، وهو يعاكس الذوبان ولا يسببه.","الأيونات تبقى أيونات محاطة بالماء ولا تتحول إلى ذرات.","","التبخر لا يفكك البلورة؛ التفكك سببه تجاذب الماء مع الأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.367Z"}'::jsonb),
('mcq', 6, 0, 'أيون Cl⁻ سالب، فتجذبه الأقطاب الموجبة جزئيًا لجزيئات الماء، وهي ذرات الهيدروجين، فتتجه نحوه، بينما يتجه الأكسجين نحو Na⁺.', '["","الأكسجين السالب جزئيًا يتنافر مع Cl⁻ السالب؛ هذا الاتجاه يحدث حول Na⁺.","التجاذب بين الأقطاب والأيون يجعل جزيئات الماء تتوجه باتجاه محدد.","الإحاطة تجاذب بين أقطاب وأيون، وليست روابط تساهمية جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.367Z"}'::jsonb),
('mcq', 7, 3, 'الذوبان يحدث إذا تغلّب تجاذب جزيئات الماء مع الأيونات على تجاذب الأيونات في البلورة. ذوبان X يعني أن هذا الشرط تحقق له، وعدم ذوبان Y (كالجبس) يعني أن قوى التجاذب بين أيوناته أقوى من أن يتغلب عليها الماء.', '["كل المركبات الأيونية مكونة من أيونات مشحونة؛ الفرق في شدة التجاذب لا في وجود الشحنة.","المعطى أن كليهما أيوني؛ وبعض المركبات الأيونية لا تذوب.","قطبية الماء خاصية ثابتة له لا تتغير بتغير المذاب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.367Z"}'::jsonb),
('essay', 1, null::int, null, null, 'جزيئات الماء قطبية وفي حركة مستمرة. عند وضع بلورة NaCl في الماء تصطدم جزيئاته بسطح البلورة، فتجذب الأقطاب السالبة جزئيًا (الأكسجين) أيونات Na⁺ الموجبة، وتجذب الأقطاب الموجبة جزئيًا (الهيدروجين) أيونات Cl⁻ السالبة. ولأن هذا التجاذب بين أقطاب الماء والأيونات أكبر من التجاذب بين الأيونات في البلورة، تنزلق الأيونات مبتعدة عن سطح البلورة، وتحيط بها جزيئات الماء وتسحبها نحو المحلول، فتتعرض أيونات أخرى على السطح للذوبان، وتستمر العملية حتى تذوب البلورة كلها.', '["قطبية الماء وحركته المستمرة","اصطدام الماء بسطح البلورة وجذب أقطابه للأيونات المخالفة","تجاذب الماء–الأيونات أكبر من تجاذب الأيونات في البلورة","إحاطة الأيونات وسحبها نحو المحلول واستمرار العملية"]'::jsonb, '[]'::jsonb, '[{"element":"قطبية الماء وحركته","marks":1},{"element":"جذب الأقطاب للأيونات المخالفة لها في الشحنة","marks":2},{"element":"المقارنة بين قوى التجاذب","marks":2},{"element":"الإحاطة والسحب واستمرار العملية","marks":1}]'::jsonb, '[{"level":"6","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"3–5","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1–2","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["القول إن NaCl يتفاعل مع الماء كيميائيًا","عكس اتجاه الأقطاب (الهيدروجين نحو Na⁺)","إغفال المقارنة بين قوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.367Z"}'::jsonb),
('essay', 2, null::int, null, null, 'شرط ذوبان المركب الأيوني في الماء أن يكون التجاذب بين جزيئات الماء والأيونات أكبر من التجاذب بين الأيونات في البلورة. في كلوريد الصوديوم يتحقق هذا الشرط فتنفصل الأيونات وتُحاط بالماء. أما في الجبس فقوى التجاذب بين أيوناته قوية بحيث لا تستطيع قوى التجاذب بين جزيئات الماء والأيونات التغلب عليها، فتبقى الأيونات في البلورة ولا يذوب. إذن كون المركب أيونيًا والمذيب قطبيًا لا يضمن الذوبان دائمًا.', '["شرط الذوبان: تجاذب الماء–الأيونات أكبر من تجاذب الأيونات","في NaCl يتحقق الشرط","في الجبس تجاذب الأيونات أقوى فلا يتغلب عليه الماء","الاستنتاج: ليست كل المركبات الأيونية ذائبة"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر الشرط","marks":1},{"element":"تطبيقه على NaCl","marks":1},{"element":"تفسير عدم ذوبان الجبس","marks":2},{"element":"الاستنتاج العام","marks":1}]'::jsonb, '[{"level":"5","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"3–4","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1–2","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["تفسير عدم ذوبان الجبس بأنه غير أيوني","الاكتفاء بقول «لأنه صلب» دون مقارنة قوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.367Z"}'::jsonb),
('essay', 3, null::int, null, null, 'جزيء الماء قطبي: طرف الأكسجين سالب جزئيًا وطرف ذرتي الهيدروجين موجب جزئيًا. حول أيون Na⁺ الموجب تتجه جزيئات الماء بذرات الأكسجين نحو الأيون لأن الشحنتين المختلفتين تتجاذبان. وحول أيون Cl⁻ السالب تتجه جزيئات الماء بذرات الهيدروجين نحو الأيون للسبب نفسه. وبهذا يُحاط كل أيون بعدد من جزيئات الماء.', '["تحديد طرفي جزيء الماء وشحنتيهما الجزئيتين","الأكسجين نحو Na⁺ مع التعليل","الهيدروجين نحو Cl⁻ مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"قطبية جزيء الماء وطرفاه","marks":1},{"element":"الترتيب حول Na⁺ مع التعليل","marks":1.5},{"element":"الترتيب حول Cl⁻ مع التعليل","marks":1.5}]'::jsonb, '[{"level":"4","description":"يحدد قطبية الماء ويصف الترتيب حول كلا الأيونين مع التعليل الصحيح."},{"level":"2–3","description":"يصف الترتيب حول أيون واحد صحيحًا مع تعليله، أو حول الأيونين دون تعليل."},{"level":"1","description":"يذكر أن الماء قطبي أو أن الأيونات تُحاط بالماء دون تحديد الاتجاه."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["جعل الهيدروجين متجهًا نحو Na⁺","عدم ذكر التعليل بالتجاذب بين الشحنات المختلفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.367Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C1-L3-O02') and x.type = v.type and x.number = v.number
