select (select id from public.objectives where code = 'K3-C1-L3-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'كم رابطة O–H يحتوي عليها جزيء السكروز C₁₂H₂₂O₁₁؟', null, '["11 رابطة","8 روابط","22 رابطة","4 روابط"]'::jsonb, 'تذكر', 'استرجاع معلومة', 'سهل', 'الكتاب ص 31 — الشكل 1-11'),
('mcq', 2, 'تصبح كل رابطة O–H في جزيء السكروز عند ملامسته الماء موقعًا لـ:', null, '["تكوين روابط أيونية مع جزيئات الماء","تفكك الجزيء إلى أيونات H⁺ وOH⁻","تكوين روابط تساهمية جديدة مع الماء","تكوين روابط هيدروجينية مع جزيئات الماء"]'::jsonb, 'تذكر', 'استرجاع آلية', 'سهل', 'الكتاب ص 31 — محاليل المركبات الجزيئية'),
('mcq', 3, 'لماذا تترك جزيئات السكروز البلورة وتصبح ذائبة في الماء؟', null, '["لأن قوى التجاذب بين السكروز والماء تتغلب على التجاذب بين جزيئات السكروز","لأن جزيئات السكروز غير قطبية مثل الماء","لأن التجاذب بين جزيئات السكروز أقوى من تجاذبها مع الماء","لأن الماء يكسر الروابط التساهمية داخل جزيء السكروز"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 31 — محاليل المركبات الجزيئية'),
('mcq', 4, 'ما طبيعة جسيمات السكروز الموجودة في محلوله المائي؟', null, '["أيونات موجبة وسالبة منفصلة","ذرات كربون وهيدروجين وأكسجين منفصلة","جزيئات سكروز كاملة تحيط بها جزيئات الماء","جزيئات أصغر ناتجة عن تفاعله مع الماء"]'::jsonb, 'فهم', 'تمييز طبيعة الجسيمات', 'متوسط', 'الكتاب ص 31 — محاليل المركبات الجزيئية'),
('mcq', 5, 'يتكون الزيت من الكربون والهيدروجين، ولا يكوّن محلولًا مع الماء، في حين يذوب السكروز فيه. ما سبب هذا الاختلاف؟', null, '["الزيت قطبي جدًّا بحيث يتنافر مع الماء القطبي","السكروز قطبي يكوّن روابط هيدروجينية مع الماء، والزيت غير قطبي تجاذبه مع الماء ضعيف","السكروز مركب أيوني والزيت مركب جزيئي","كتلة جزيء الزيت أكبر كثيرًا من كتلة جزيء السكروز"]'::jsonb, 'فهم', 'تفسير بالمقارنة', 'متوسط', 'الكتاب ص 31 — محاليل المركبات الجزيئية'),
('mcq', 6, 'أيّ العبارات الآتية تقارن مقارنة صحيحة بين ذوبان NaCl وذوبان السكروز في الماء؟', null, '["في الحالتين تنفصل أيونات موجبة وسالبة تحيط بها جزيئات الماء","في NaCl تتكون روابط هيدروجينية، وفي السكروز تنفصل أيونات","NaCl يذوب لأن الماء قطبي، والسكروز يذوب لأن الماء غير قطبي","في NaCl تنفصل أيونات، وفي السكروز تنفصل جزيئات كاملة ترتبط بالماء بروابط هيدروجينية"]'::jsonb, 'تحليل', 'مقارنة آليتين', 'صعب', 'الكتاب ص 30–31 — محاليل المركبات الأيونية والجزيئية'),
('mcq', 7, 'مركب جزيئي قطبي يحتوي جزيئه على عدة مجموعات O–H. ما التوقع الأرجح عند وضعه في الماء، ولماذا؟', null, '["لا يذوب لأن المركبات الجزيئية لا تذوب في الماء","يذوب لأنه يتأين إلى أيونات في الماء","يذوب لأن مجموعات O–H تكوّن روابط هيدروجينية مع الماء","لا يذوب لأن روابط O–H تتنافر مع جزيئات الماء"]'::jsonb, 'تطبيق', 'تنبؤ بالقياس', 'صعب', 'الكتاب ص 31 — محاليل المركبات الجزيئية'),
('essay', 1, 'فسّر آلية ذوبان السكروز (سكر المائدة) في الماء، مستعينًا بنوع الروابط التي تتكون بين جزيئاته وجزيئات الماء.', null, null, 'فهم', 'تفسير آلية', 'متوسط', 'الكتاب ص 31 — محاليل المركبات الجزيئية، الشكل 1-11'),
('essay', 2, 'قارن بين آلية ذوبان كلوريد الصوديوم وآلية ذوبان السكروز في الماء، مبينًا وجهًا للتشابه ووجهين للاختلاف.', null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 30–31، والتقويم 1-3 السؤال 42'),
('essay', 3, 'علّل: يذوب سكر المائدة في الماء، بينما لا يكوّن الزيت محلولًا مع الماء ويذوب في مذيب غير قطبي.', null, null, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 31 — محاليل المركبات الجزيئية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
