insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يحتوي جزيء السكروز على 8 روابط O–H قطبية، تكوّن كل منها روابط هيدروجينية مع جزيئات الماء.', '["11 هو عدد ذرات الأكسجين في الصيغة، وليست كلها مرتبطة بالهيدروجين.","","22 هو عدد ذرات الهيدروجين في الصيغة، ومعظمها مرتبط بالكربون لا بالأكسجين.","العدد أقل من الصحيح؛ الجزيء يحتوي على 8 روابط O–H."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.368Z"}'::jsonb),
('mcq', 2, 3, 'بمجرد ملامسة بلورات السكر الماءَ تصطدم جزيئات الماء بسطحها، وتصبح كل رابطة O–H في السكروز موقعًا لتكوين روابط هيدروجينية مع الماء.', '["السكروز مركب جزيئي لا يحتوي أيونات، فلا تتكون روابط أيونية.","السكروز لا يتأين في الماء؛ تبقى جزيئاته كاملة.","التجاذب بين السكروز والماء روابط هيدروجينية، وليس روابط تساهمية تغير تركيب الجزيء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.368Z"}'::jsonb),
('mcq', 3, 0, 'قوى التجاذب بين جزيئات السكروز يتم التغلب عليها بقوى التجاذب التي تتكون بين جزيئاته وجزيئات الماء القطبية، فتترك جزيئات السكروز البلورة وتصبح ذائبة.', '["","السكروز والماء كلاهما قطبي، والماء ليس غير قطبي.","لو كان كذلك لبقيت الجزيئات في البلورة ولم تذب.","الذوبان لا يكسر الروابط داخل الجزيء؛ يتغلب فقط على التجاذب بين الجزيئات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.368Z"}'::jsonb),
('mcq', 4, 2, 'عند ذوبان السكروز تترك جزيئاته البلورة وتصبح ذائبة في الماء؛ أي تبقى جزيئات كاملة مرتبطة بالماء بروابط هيدروجينية، لأنه مركب جزيئي لا يتكون من أيونات.', '["هذا يحدث للمركبات الأيونية مثل NaCl، أما السكروز فمركب جزيئي.","الذوبان لا يفكك الجزيء إلى ذراته.","","الذوبان عملية فيزيائية لا تُنتج جزيئات جديدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.368Z"}'::jsonb),
('mcq', 5, 1, 'السكروز قطبي ويحتوي على روابط O–H تكوّن روابط هيدروجينية مع الماء، فيتغلب تجاذبه مع الماء على تجاذب جزيئاته. أما الزيت فغير قطبي، وقوى التجاذب بين جزيئاته وجزيئات الماء القطبية ضعيفة، لذا لا يذوب فيه.', '["الزيت غير قطبي؛ والمواد القطبية لا تتنافر مع الماء بل تذوب فيه غالبًا.","","السكروز مركب جزيئي كالزيت؛ الفرق في القطبية.","الكتلة ليست سبب الاختلاف بل القطبية وقوى التجاذب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.369Z"}'::jsonb),
('mcq', 6, 3, 'في المركب الأيوني NaCl تجذب أقطاب الماء الأيونات وتفصلها، أما في المركب الجزيئي السكروز فتنفصل جزيئات كاملة بعد تكوين روابط هيدروجينية بين روابط O–H فيها والماء. وفي الحالتين تتغلب قوى التجاذب مع الماء على التجاذب داخل البلورة.', '["السكروز لا يتأين؛ تنفصل جزيئاته كاملة.","العبارة عكست الآليتين؛ الأيونات في NaCl والروابط الهيدروجينية في السكروز.","الماء قطبي في الحالتين، والسكروز نفسه قطبي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.369Z"}'::jsonb),
('mcq', 7, 2, 'قياسًا على السكروز: روابط O–H القطبية تصبح مواقع لتكوين روابط هيدروجينية مع الماء، فتتغلب قوى التجاذب مع الماء على التجاذب بين جزيئات المركب، فيذوب.', '["الماء مذيب جيد للكثير من المركبات الجزيئية كالسكروز.","المركب جزيئي، وذوبانه ناتج عن الروابط الهيدروجينية لا عن التأين.","","روابط O–H القطبية تتجاذب مع الماء بروابط هيدروجينية ولا تتنافر معه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.369Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الماء مذيب جيد للكثير من المركبات الجزيئية. السكروز مركب جزيئي قطبي يحتوي جزيئه على 8 روابط O–H. بمجرد ملامسة بلورات السكر الماء تصطدم جزيئات الماء بالسطح الخارجي للبلورات، وتصبح كل رابطة O–H في السكروز موقعًا لتكوين روابط هيدروجينية مع الماء. فتتغلب قوى التجاذب المتكونة بين جزيئات السكروز وجزيئات الماء القطبية على قوى التجاذب بين جزيئات السكروز نفسها، فتترك جزيئات السكروز البلورة وتصبح ذائبة في الماء.', '["السكروز مركب جزيئي قطبي فيه روابط O–H","اصطدام الماء بسطح البلورة","تكوّن روابط هيدروجينية بين O–H والماء","تغلب تجاذب السكروز–الماء على تجاذب جزيئات السكروز فتنفصل الجزيئات"]'::jsonb, '[]'::jsonb, '[{"element":"قطبية السكروز وروابط O–H","marks":1},{"element":"اصطدام الماء بالسطح","marks":1},{"element":"الروابط الهيدروجينية","marks":2},{"element":"المقارنة بين قوى التجاذب وانفصال الجزيئات","marks":2}]'::jsonb, '[{"level":"6","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"3–5","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1–2","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["القول إن السكروز يتأين في الماء","تسمية التجاذب روابط أيونية بدل الهيدروجينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.369Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التشابه: في الحالتين تصطدم جزيئات الماء القطبية بسطح البلورة، وتتغلب قوى التجاذب بين الماء وجسيمات المذاب على قوى التجاذب بين جسيمات المذاب، فتنفصل الجسيمات وتحيط بها جزيئات الماء. الاختلاف: (1) نوع الجسيمات المنفصلة: أيونات Na⁺ وCl⁻ في كلوريد الصوديوم، وجزيئات سكروز كاملة في السكروز. (2) نوع التجاذب: في NaCl تجاذب بين أقطاب الماء والأيونات المشحونة، وفي السكروز روابط هيدروجينية بين روابط O–H وجزيئات الماء.', '["وجه التشابه: تغلب التجاذب مع الماء على التجاذب داخل البلورة وإحاطة الجسيمات","اختلاف نوع الجسيمات المنفصلة (أيونات / جزيئات)","اختلاف نوع التجاذب (أقطاب–أيونات / روابط هيدروجينية)"]'::jsonb, '[]'::jsonb, '[{"element":"وجه التشابه","marks":2},{"element":"الاختلاف في نوع الجسيمات","marks":2},{"element":"الاختلاف في نوع التجاذب","marks":2}]'::jsonb, '[{"level":"6","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"3–5","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1–2","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["القول إن الآليتين متطابقتان تمامًا","القول إن السكروز يتفكك إلى أيونات كالملح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.369Z"}'::jsonb),
('essay', 3, null::int, null, null, 'السكروز قطبي ويحتوي على روابط O–H تكوّن روابط هيدروجينية مع جزيئات الماء القطبية، فتتغلب قوى التجاذب بينه وبين الماء على قوى التجاذب بين جزيئاته فيذوب. أما الزيت فيتكون من الكربون والهيدروجين وهو غير قطبي، وقوى التجاذب بين جزيئاته وجزيئات الماء القطبية ضعيفة فلا يذوب فيه، ويذوب بسهولة أكبر في المذيب غير القطبي لأن المذاب غير القطبي يذوب في المذيب غير القطبي.', '["قطبية السكروز وروابطه الهيدروجينية مع الماء","الزيت غير قطبي وتجاذبه مع الماء ضعيف","الزيت يذوب في المذيب غير القطبي"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل ذوبان السكر","marks":2},{"element":"تعليل عدم ذوبان الزيت في الماء","marks":1.5},{"element":"تعليل ذوبانه في مذيب غير قطبي","marks":0.5}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["تعليل عدم ذوبان الزيت بأنه أقل كثافة من الماء","إغفال ذكر الروابط الهيدروجينية في ذوبان السكر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.369Z"}'::jsonb)
