('mcq', 1, 'ما أثر تحريك المحلول في سرعة ذوبان مذاب صلب فيه؟', null, '["يقلل سرعة الذوبان","لا يؤثر في سرعة الذوبان","يزيد سرعة الذوبان","يوقف الذوبان حتى يسكن المحلول"]'::jsonb, 'تذكر', 'استرجاع أثر', 'سهل', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: التحريك'),
('mcq', 2, 'كيف يزيد التحريك سرعة الذوبان على مستوى الجسيمات؟', null, '["يبعد جسيمات المذاب عن سطوح التماس بسرعة فتحدث تصادمات جديدة مع المذيب","يكسر جزيئات المذاب إلى ذرات أصغر فتذوب أسرع","يرفع درجة حرارة المذيب ارتفاعًا كبيرًا","يزيد أقصى كمية من المذاب يمكن أن تذوب"]'::jsonb, 'فهم', 'تفسير جسيمي', 'متوسط', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: التحريك'),
('mcq', 3, 'ماذا يحدث للجسيمات الذائبة قرب سطح المذاب إذا تُرك المحلول دون تحريك؟', null, '["تعود جميعها إلى البلورة فيتوقف الذوبان","تتحرك بعيدًا عن مناطق التماس ببطء","تبتعد عن مناطق التماس بسرعة كبيرة","تتجمع فوق سطح المحلول"]'::jsonb, 'فهم', 'تفسير حالة مقابلة', 'سهل', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: التحريك'),
('mcq', 4, 'وُضع مكعبا سكر متماثلان في كوبين متماثلين من الشاي المثلج عند درجة الحرارة نفسها، وحُرّك أحدهما فقط. ما النتيجة المتوقعة؟', null, '["يذوب المكعب في الكوب غير المحرّك أسرع","يذوب المكعبان في الزمن نفسه","لا يذوب أي منهما لأن الشاي مثلج","يذوب المكعب في الكوب المحرّك أسرع"]'::jsonb, 'تطبيق', 'تنبؤ بنتيجة تجربة', 'متوسط', 'الكتاب ص 32 — الشكل 1-12'),
('mcq', 5, 'ما الأساس المشترك الذي تزيد به العوامل الثلاثة (التحريك، ومساحة السطح، ودرجة الحرارة) سرعة الذوبان؟', null, '["زيادة التصادمات بين جسيمات المذاب والمذيب","تقليل عدد جسيمات المذيب حول المذاب","زيادة الذائبية القصوى للمذاب","تحويل المذاب إلى أيونات"]'::jsonb, 'فهم', 'تعميم', 'متوسط', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان'),
('mcq', 6, 'أيّ العبارات الآتية تصف أثر التحريك وصفًا دقيقًا؟', null, '["يزيد أقصى كمية تذوب ولا يغيّر سرعة الذوبان","يزيد سرعة الذوبان وأقصى كمية تذوب معًا","يزيد سرعة الذوبان ولا يغيّر أقصى كمية يمكن أن تذوب","لا يغيّر سرعة الذوبان ولا أقصى كمية تذوب"]'::jsonb, 'تحليل', 'تمييز بين مفهومين', 'صعب', 'الكتاب ص 32–33 — التحريك والذائبية'),
('mcq', 7, 'أراد طالب دراسة أثر التحريك وحده في سرعة ذوبان الملح. أيّ تصميم يحقق ذلك؟', null, '["كأس بماء ساخن محرّكة وكأس بماء بارد غير محرّكة","كأسان محرّكتان، في إحداهما ملح ناعم وفي الأخرى قطع كبيرة","كأس محرّكة بملح ناعم وكأس ساكنة بقطع ملح كبيرة","كأسان بماء متساوي الحرارة وكمية ملح متماثلة الحبيبات، يُحرّك أحدهما فقط"]'::jsonb, 'تحليل', 'تصميم تجربة عادلة', 'صعب', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: التحريك'),
('essay', 1, 'وضّح على مستوى الجسيمات كيف يزيد تحريك المحلول من سرعة ذوبان مكعب سكر في الشاي.', null, null, 'فهم', 'توضيح جسيمي', 'متوسط', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: التحريك'),
('essay', 2, 'صمّم تجربة بسيطة تبيّن أثر التحريك في سرعة الذوبان، محددًا المتغير المستقل، والمتغير التابع، ومتغيرين يجب ضبطهما، والنتيجة المتوقعة.', null, null, 'تطبيق', 'تصميم تجربة', 'صعب', 'الكتاب ص 32 — الشكل 1-12'),
('essay', 3, 'قال طالب: «إذا حرّكتُ محلولًا مشبعًا من السكر مدة أطول، فسيذوب فيه سكر إضافي عند درجة الحرارة نفسها». قوّم هذه العبارة.', null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 32–33 — التحريك، والمحلول المشبع')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C1-L3-O04') and x.type = v.type and x.number = v.number);
