select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'التحريك إحدى ثلاث طرائق شائعة لزيادة التصادمات بين جسيمات المذاب والمذيب وزيادة سرعة الذوبان.', '["التحريك يسرّع الذوبان ولا يبطئه.","سرعة ذوبان مكعب السكر تزداد عند تحريكه.","","التحريك لا يوقف الذوبان بل يسرّعه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.370Z"}'::jsonb),
('mcq', 2, 0, 'يعمل تحريك المحلول على إبعاد جسيمات المذاب عن سطوح التماس بسرعة أكبر، وبذلك يسمح بحدوث تصادمات أخرى بين جسيمات المذاب والمذيب، فتزداد سرعة الذوبان.', '["","التحريك لا يكسر الجزيئات؛ هو ينقل الجسيمات الذائبة بعيدًا عن سطح التماس.","رفع درجة الحرارة عامل مستقل، والتحريك لا يسخّن المحلول تسخينًا يُذكر.","التحريك يؤثر في سرعة الذوبان لا في الذائبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T11:36:22.370Z"}'::jsonb),
('mcq', 3, 1, 'من دون تحريك المحلول تتحرك الجسيمات الذائبة بعيدًا عن مناطق التماس ببطء، فتقل التصادمات الجديدة ويكون الذوبان أبطأ.', '["الذوبان يستمر دون تحريك لكن ببطء، ولا تعود كل الجسيمات إلى البلورة.","","الابتعاد السريع هو ما يحققه التحريك، لا غيابه.","لا تتجمع الجسيمات الذائبة على السطح؛ بل تبقى قرب منطقة التماس وتنتشر ببطء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.370Z"}'::jsonb),
('mcq', 4, 3, 'تثبيت حجم المكعب ودرجة الحرارة يجعل التحريك المتغير الوحيد، والتحريك يزيد سرعة الذوبان، فيذوب مكعب السكر في الكوب المحرّك أسرع.', '["التحريك يسرّع الذوبان، فلا يكون الكوب الساكن أسرع.","التحريك المتغير الوحيد بين الكوبين وهو يؤثر في سرعة الذوبان.","السكر يذوب في الشاي المثلج ولكن ببطء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.370Z"}'::jsonb),
('mcq', 5, 0, 'يحدث الذوبان عند تصادم جسيمات المذاب والمذيب معًا، والطرائق الثلاث هي طرائق لزيادة التصادمات بين جسيمات المذاب والمذيب وزيادة سرعة الذوبان.', '["","تقليل جسيمات المذيب يقلل التصادمات فيبطئ الذوبان.","التحريك ومساحة السطح لا يغيران الذائبية؛ أثرها في السرعة عبر التصادمات.","لا تحول هذه العوامل المذاب إلى أيونات؛ السكر مثلًا يبقى جزيئات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.370Z"}'::jsonb),
('mcq', 6, 2, 'التحريك يسرّع الوصول إلى الحالة النهائية بإبعاد الجسيمات الذائبة عن سطوح التماس، لكن أقصى كمية تذوب (الذائبية) تعتمد على طبيعة المذاب والمذيب ودرجة الحرارة لا على التحريك.', '["العبارة عكست الأثر؛ التحريك يغير السرعة لا الذائبية.","الذائبية لا تتغير بالتحريك عند ثبوت درجة الحرارة.","","التحريك يزيد سرعة الذوبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.370Z"}'::jsonb),
('mcq', 7, 3, 'لدراسة أثر التحريك وحده يجب تثبيت العاملين الآخرين المؤثرين في سرعة الذوبان، وهما درجة حرارة المذيب ومساحة سطح المذاب (حجم الحبيبات)، وتغيير التحريك فقط.', '["تغيرت درجة الحرارة مع التحريك، فلا يُعرف أيهما سبب الفرق.","هذا التصميم يدرس مساحة السطح لا التحريك.","تغير عاملان معًا، التحريك ومساحة السطح.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.371Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يحدث الذوبان عند تصادم جسيمات المذاب والمذيب. عند ذوبان جسيمات السكر تبقى قرب سطح المكعب، ومن دون تحريك تتحرك بعيدًا عن مناطق التماس ببطء. أما التحريك فيعمل على إبعاد جسيمات المذاب الذائبة عن سطوح التماس بسرعة أكبر، فيصل مذيب جديد إلى سطح السكر، وتحدث تصادمات أخرى بين جسيمات المذاب والمذيب، فتزداد سرعة الذوبان.', '["الذوبان يحدث بتصادم جسيمات المذاب والمذيب","دون تحريك تبتعد الجسيمات الذائبة ببطء","التحريك يبعدها عن سطوح التماس بسرعة","فتحدث تصادمات جديدة وتزداد السرعة"]'::jsonb, '[]'::jsonb, '[{"element":"ربط الذوبان بالتصادمات","marks":1},{"element":"حالة عدم التحريك","marks":1},{"element":"دور التحريك في إبعاد الجسيمات","marks":1},{"element":"النتيجة: تصادمات أكثر وسرعة أكبر","marks":1}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["القول إن التحريك يكسر السكر إلى قطع أصغر","الخلط بين سرعة الذوبان والذائبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T11:36:22.371Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تُحضّر كأسان متماثلتان فيهما الحجم نفسه من الماء عند درجة الحرارة نفسها، ويوضع في كل منهما مكعب سكر متماثل الكتلة والحجم. يُحرّك محتوى إحدى الكأسين باستمرار وتُترك الأخرى دون تحريك، ويُقاس زمن ذوبان المكعب في كل كأس. المتغير المستقل: التحريك (وجوده أو غيابه). المتغير التابع: زمن الذوبان (أو سرعته). المتغيرات المضبوطة: درجة حرارة الماء، وحجم قطعة السكر (مساحة السطح)، وكمية الماء. النتيجة المتوقعة: يذوب السكر في الكأس المحرّكة في زمن أقل، لأن التحريك يبعد الجسيمات الذائبة عن سطوح التماس فيزيد التصادمات.', '["وصف خطوات التجربة","المتغير المستقل: التحريك","المتغير التابع: زمن الذوبان","ضبط درجة الحرارة وحجم قطعة المذاب","النتيجة المتوقعة مع تفسيرها"]'::jsonb, '[]'::jsonb, '[{"element":"الخطوات","marks":1},{"element":"المتغير المستقل","marks":1},{"element":"المتغير التابع","marks":1},{"element":"متغيران مضبوطان","marks":2},{"element":"النتيجة وتفسيرها","marks":1}]'::jsonb, '[{"level":"6","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"3–5","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1–2","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["تغيير درجة الحرارة مع التحريك في الوقت نفسه","جعل كمية السكر الذائبة القصوى هي المتغير التابع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.371Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. التحريك يزيد سرعة الذوبان فقط، لأنه يبعد جسيمات المذاب عن سطوح التماس فتحدث تصادمات أكثر، أي يجعل المحلول يصل أسرع إلى أقصى ما يمكن أن يذوب. لكن المحلول المشبع يحتوي أصلًا على أكبر كمية من المذاب يمكن أن تذوب في كمية محددة من المذيب عند درجة حرارة معينة، وهذه الكمية (الذائبية) لا تتغير بالتحريك. لزيادة الكمية الذائبة من السكر يجب تغيير درجة الحرارة (رفعها) لا التحريك.', '["الحكم: العبارة خاطئة","التحريك يؤثر في السرعة لا في الكمية القصوى","المحلول المشبع وصل إلى الذائبية عند تلك الحرارة","تغيير الكمية الذائبة يحتاج تغيير درجة الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"دور التحريك في السرعة","marks":1},{"element":"مفهوم المحلول المشبع والذائبية","marks":1},{"element":"البديل الصحيح","marks":1}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["الموافقة على العبارة لأن التحريك «يساعد على الذوبان»","عدم التمييز بين سرعة الذوبان والذائبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.371Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
